-- Turismo Rural España - Migration 0205
-- Cargar 626 municipios de turismo rural

-- Paso 1: Limpiar datos antiguos
DELETE FROM puntuaciones WHERE categoria='TurismoRural';

-- Paso 2: Crear entradas en puntuaciones con puntuación por defecto
INSERT INTO puntuaciones (codigo_ine, categoria, puntuacion, ranking_provincial)
SELECT DISTINCT codigo_ine, 'TurismoRural', 0, NULL
FROM municipios WHERE es_duplicado = 0 AND codigo_ine NOT IN
  (SELECT DISTINCT codigo_ine FROM puntuaciones WHERE categoria='TurismoRural');

