-- Paso 3: Cargar why_json con alojamientos y actividades
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Palacetes indianos a pie de playa, casonas rurales señoriales en las parroquias interiores y apartamentos rústicos de costa. | Desembocadura del río Sella y Cuevas de Tito Bustillo. Destaca por el senderismo costero de los acantilados de Guadamía, las huellas de dinosaurio en la playa de Vega y las rutas fluviales en kayak.') WHERE codigo_ine = '33056';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de aldea tradicionales con hórreo, hoteles rurales integrados en pomaradas (campos de manzanos) y casonas de piedra mariñanas. | Reserva Natural Parcial de la Ría de Villaviciosa. Ofrece rutas de observación de aves acuáticas, la Senda del río Profundo entre antiguos molinos, y playas salvajes rodeadas de acantilados como Rodiles.') WHERE codigo_ine = '33076';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Alojamientos rurales con encanto en núcleos rurales compactos y premiados, casas de piedra recuperadas con techos de madera. | Integrado en el Parque Natural de Redes. Ofrece la Ruta de los Arrudos (uno de los desfiladeros más bellos y boscosos de Asturias), el embalse de Tanes y senderos de montaña adaptados para familias.') WHERE codigo_ine = '33067';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de aldea en el valle interior, hoteles rurales con fincas agrarias y antiguos molinos harineros reconvertidos. | Reserva de la Biosfera del Río Eo, Oscos y Terras de Burón. Rutas de senderismo por la Senda Verde de la antigua vía del tren, actividades de remo en la ría del Eo y paseos por bosques autóctonos atlánticos.') WHERE codigo_ine = '33074';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Albergues y casas de aldea de piedra y pizarra negra, hostales rurales pegados al Camino de Santiago Primitivo. | Entorno del gran Embalse de Salime. Destaca por la ruta senderista del río Navia, paseos en barca por el embalse, senderos forestales de castaños milenarios y visitas etnográficas de montaña.') WHERE codigo_ine = '33027';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de montaña de piedra, hostales rurales especializados en ciclismo de carretera y alojamientos de esquí. | Parque Natural de Las Ubiñas-La Mesa. Destaca por las rutas de senderismo de alta montaña hacia el Macizo de las Ubiñas, senderos de la Vía Romana de la Carisa y rutas ciclistas en puertos míticos (Cuitu Negru).') WHERE codigo_ine = '33033';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales de pastores restauradas, apartamentos rústicos al pie de paredes de escalada. | Parque Natural de Las Ubiñas-La Mesa y Senda del Oso. Destaca por las rutas cicloturistas de la Senda del Oso, la escuela internacional de escalada en roca de El Llano y senderos de montaña boscosos.') WHERE codigo_ine = '33053';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hoteles rurales con encanto rodeados de avellanos, antiguas casonas agrícolas y casas de aldea independientes. | Sierra del Sueve y valles del río Piloña. Ofrece rutas ecuestres para ver los caballos asturcones en libertad, el sendero de las Hoces del río Espinaredo y áreas recreativas boscosas como La Pesanca.') WHERE codigo_ine = '33049';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales mariñanas, hoteles de campo con amplios jardines y apartamentos turísticos de costa. | Desembocadura del río Navia. Ofrece la Senda Costera Naviega (ruta senderista por acantilados y playas salvajes como Barayo), descensos fluviales en canoa y paseos por bosques de ribera.') WHERE codigo_ine = '33041';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de pueblo de alquiler íntegro de arquitectura tradicional, pequeños hostales rurales con encanto. | Eje central de la Senda del Oso. Ofrece cicloturismo por la antigua vía minera reconvertida, senderismo por el Desfiladero de Peñas Juntas y rutas al hermoso pueblo colgado de Bandujo (conjunto histórico).') WHERE codigo_ine = '33052';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rectorales recuperadas, casas de aldea tradicionales con muros de mampostería gruesos y pizarra. | Reserva de la Biosfera de los Oscos. Rutas de senderismo de la Senda Verde del río Agüeira, paseos entre bosques de robles y castaños, y rutas de senderos de herradura históricos aislados del ruido urbano.') WHERE codigo_ine = '33061';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casonas tradicionales integradas en conjuntos etnográficos, apartamentos rurales bioclimáticos. | Los Oscos vírgenes. Destaca por la ruta de senderismo de la Cascada de Seimeira, senderos fluviales por el río Agüeira y talleres artesanales de forja integrados en la naturaleza.') WHERE codigo_ine = '33062';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales unifamiliares con huerto, monasterios rurales reconvertidos parcialmente para pernocta. | Destaca por la Ruta de la Bobia (senderismo de media montaña con túmulos prehistóricos), senderos por el bosque de Carballeira y rutas micológicas otoñales.') WHERE codigo_ine = '33075';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de turismo rural con bodegas tradicionales de viñedo heroico, construcciones de piedra aisladas. | Frontera con el Parque de Fuentes del Narcea. Ofrece rutas de senderismo entre viñedos escarpados de montaña, visitas a los \"cortines\" (colmenas circulares de piedra contra osos) y senderos fluviales vírgenes.') WHERE codigo_ine = '33028';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Cabañas forestales de montaña, apartamentos rústicos de madera para observadores de fauna. | Parque Natural de las Fuentes del Narcea, Degaña e Ibias. Uno de los mejores enclaves para el rastreo guiado del oso pardo, rutas senderistas por las lagunas glaciares de Fasgueo y senderos entre abedulares.') WHERE codigo_ine = '33022';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casonas de campo tradicionales asturianas, apartamentos rurales junto al río Pigüeña. | Valles del Oso. Destaca por la Ruta del Oro (senderismo hacia antiguas minas romanas), senderos que conectan con los pastizales de montaña del Parque de Somiedo y ríos trucheros de aguas cristalinas.') WHERE codigo_ine = '05003';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hoteles rurales en torres medievales, palacetes agrícolas, albergues de peregrinos del Camino de Santiago. | Destaca por la ruta de senderismo del ríofiel a la Cascada de Nonaya, valles boscosos interiores, rutas micológicas y ríos salmoneros como el Narcea.') WHERE codigo_ine = '33059';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casonas rurales hidalgas, apartamentos rústicos en antiguas vegas agrícolas fluviales. | Bajo Nalón. Rutas de senderismo de los miradores del Nalón, paseos en piragua por el tramo bajo del río Nalón, senderos llanos entre plantaciones de kiwis y masas forestales. [1]') WHERE codigo_ine = '33051';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Apartamentos rurales de playa, hoteles boutique costeros, casas de aldea en el entorno costero. | Costa occidental extrema. Ofrece la ruta senderista de los acantilados de Tapia, senderos costeros hacia las playas de Penarronda y paseos marineros integrados en el paisaje atlántico.') WHERE codigo_ine = '33070';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de campo tradicionales occidentales, pequeños apartamentos rurales tranquilos de costa. | Destaca por la ruta senderista de las Cuevas de Andina (Monumento Natural de formaciones kársticas en bosque), playas salvajes como Pormenande y sendas litorales.') WHERE codigo_ine = '33023';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Alojamientos rurales enfocados al turismo activo, apartamentos de montaña de piedra caliza con chimenea. | Parque Natural de Las Ubiñas-La Mesa y Senda del Oso. Ofrece rutas al Monumento Natural de Cueva Huerta, senderismo por el Camín Real de la Mesa (antigua calzada) y puertos de montaña alpinos (San Lorenzo).') WHERE codigo_ine = '33072';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de aldea rústicas en la falda de la montaña, hostales rurales tradicionales. | Macizo del Monsacro. Destaca por las rutas de senderismo de ascensión a las capillas medievales del Monsacro, senderos entre praderías ganaderas y rutas de escalada deportiva.') WHERE codigo_ine = '33038';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de alta montaña de piedra caliza, apartamentos orientados a ciclistas extremos. | Falda del mítico Puerto de L''Angliru. Rutas de senderismo hacia la Sierra del Aramo, ascensión a pie o en bicicleta al Angliru (rampas del 23.5%), y senderos de pastores entre lagunas de montaña.') WHERE codigo_ine = '33058';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Cabañas rurales colgadas de valles profundos, casas de piedra de montaña tradicionales de alquiler íntegro. | Pre-Picos de Europa. Ofrece la espectacular ruta del Camín de la Reina, senderismo vertical por el Desfiladero de los Beyos, barranquismo en el río Dobra y rutas de aguas bravas.') WHERE codigo_ine = '05001';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de aldea tradicionales restauradas en valles llanos agrícolas y ganaderos. | Destaca por la Ruta de las Fuentes del río Seco, caminatas tranquilas de baja dificultad entre caseríos tradicionales, llagares de sidra artesanos y praderías. PROVINCIA: CANTABRIA (Texto Plano Limpio)') WHERE codigo_ine = '33065';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casonas de piedra tradicionales, hosterías de montaña, apartamentos rústicos con chimenea y posadas lebaniegas. | Centro geográfico y logístico del Valle de Liébana y acceso oriental a los Picos de Europa. Destaca por el senderismo al Monasterio de Santo Toribio de Liébana (Ruta Lebaniega), rutas micológicas, y proximidad directa al Teleférico de Fuente Dé (ascenso vertical a la alta montaña alpina).') WHERE codigo_ine = '39055';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Posadas cántabras con balconadas de madera señoriales, hoteles palacio barrocos y antiguas casas de labranza rehabilitadas. | Entorno litoral mixto y praderas verdes. Rutas de senderismo suave por los acantilados de Ubiarco, paseos cicloturistas costeros, senderos botánicos en el entorno rupestre de Altamira y rutas a caballo en fincas rurales.') WHERE codigo_ine = '39076';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Cabañas de madera forestales, apartamentos alpinos para montañeros y hoteles rurales con vistas a las cumbres calcáreas. | Alberga el circo glaciar de Fuente Dé dentro del Parque Nacional de los Picos de Europa. Rutas de senderismo de alta dificultad como la Canal de la Jenduda, el ascenso a Áliva, sendas entre hayedos centenarios y rutas de raquetas de nieve.') WHERE codigo_ine = '39015';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casonas montañesas de piedra con corraladas de sillería, palacetes agrícolas y posadas rurales integradas en valles de prados. | Incluye gran parte del Parque Natural de Oyambre y el Monte Corona. Destaca por el senderismo forestal entre secuoyas gigantes, paseos fluviales por la ría de San Vicente, rutas ornitológicas en marismas y senderos entre robledales antiguos.') WHERE codigo_ine = '39091';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Posadas de costa, apartamentos rurales con vistas al estuario y casas de aldea tradicionales mariñanas. | Corazón del Parque Natural de Oyambre. Ofrece el Camino de Santiago de la Costa, rutas de observación de aves en las marismas de Rubín y Pombo, paseos por las dunas protegidas de Merón y surf en playas salvajes rodeadas de acantilados.') WHERE codigo_ine = '39080';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de turismo rural típicas del Valle de Cabuérniga, posadas de piedra con grandes arcos rústicos de acceso. | Parque Natural de Saja-Besaya. Destaca por el Monumento Natural de La Fuentona de Ruente (espectacular surgencia kárstica intermitente), la Ruta de los Puentes, senderismo bajo frondosos cajigales (robles) y avistamiento de fauna (berrea del ciervo).') WHERE codigo_ine = '39066';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Cabañas pasiegas auténticas rehabilitadas (antiguos establos de piedra y pradera vallada), posadas rústicas del valle. | Valles Pasiegos. Ofrece un paisaje etnográfico único modelado por el pastoreo tradicional. Rutas de senderismo de media montaña siguiendo el curso alto del río Pas, túneles ferroviarios abandonados en la naturaleza y senderos micológicos.') WHERE codigo_ine = '39097';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Apartamentos rurales litorales, hoteles boutique de playa y pequeñas villas con fincas verdes. | Parque Natural de las Marismas de Santoña, Victoria y Joyel. Es un punto clave del norte de España para el turismo ornitológico de aves acuáticas migratorias. Rutas por el sendero costero de la Punta del Brusco y acantilados vírgenes.') WHERE codigo_ine = '39047';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Posadas rurales protegidas, casonas montañesas tradicionales con solanas de madera orientadas al sur. | Reserva Nacional de Caza del Saja. Incluye la joya medieval de Bárcena Mayor. Rutas de senderismo por la Senda de los Senderos, caminatas fluviales junto al río Argoza, bosques de hayas primigenios y observación de fauna.') WHERE codigo_ine = '39014';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de piedra y madera para turismo activo, apartamentos de interior con vistas a grandes moles calizas. | Valle del Asón. Capital de la espeleología y del turismo de aventura en Cantabria por su colosal subsuelo kárstico. Rutas de senderismo a cuevas con arte rupestre (Covalanas), vías ferratas de montaña y escalada deportiva vertical.') WHERE codigo_ine = '39057';
