UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casonas de indianos singulares, hoteles rurales burgueses con amplios jardines históricos y posadas de costa. | Costa occidental cántabra. Paseos por el Parque de la Estatua, rutas a pie hacia el Monte Corona, senderos litorales que cruzan acantilados de caliza y la ría de la Rabia, hábitat protegido de aves.') WHERE codigo_ine = '39024';
