UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Posadas rurales tradicionales de la Sierra Norte, casas de aldea unifamiliares con corredores rústicos. | Custodia el Hayedo de Montejo (Patrimonio de la Humanidad por la UNESCO). Rutas senderistas de acceso controlado y guiado por las riberas del río Jarama bajo hayas centenarios, senderos de herradura de montaña y turismo micológico.') WHERE codigo_ine = '28088';
