UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de piedra tradicionales de montaña con muros gruesos aislantes, apartamentos rústicos pequeños. | Falda norte del Puerto de Canencia. Destaca por sus puentes medievales de piedra (Puente Canto), rutas senderistas hacia cascadas ocultas (Chorrera de Mojonavalle) y senderos botánicos rodeados de pinos e hileras de tejos singulares.') WHERE codigo_ine = '28034';
