UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de campo con fincas amplias integradas en zonas de monte bajo, chalets rústicos tradicionales con chimenea. | Transición de la Sierra de Guadarrama a la Sierra Oeste. Rutas de senderismo hacia el Monte de la Almenara, caminatas de observación de avifauna (zonas protegidas de águila perdicera), y senderos llanos aptos para cicloturismo familiar entre pinares.') WHERE codigo_ine = '28125';
