UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Fincas agrarias y casas rurales de campo aisladas en zonas adehesadas bajas, apartamentos tradicionales sencillos. | Entorno del embalse de Picadas y del río Alberche. Rutas de senderismo de la Vía Verde del río Alberche (antiguo trazado ferroviario plano ideal para familias y cicloturismo de paseo), encinares compactos y observación de grandes rapaces de bosque.') WHERE codigo_ine = '28099';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de labranza castellanas tradicionales con tinajas de piedra gigantescas en patios interiores rústicos. | Comarca de Las Vegas. Rutas que conectan con la Vía Verde del Tajuña para caminantes y ciclistas, senderos que bajan hacia las canteras históricas de piedra caliza blanca de Colmenar y paseos fotográficos entre campos llanos cerealistas y vides. PROVINCIA: HUESCA (Texto Plano Limpio)') WHERE codigo_ine = '28043';
