UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales de piedra medieval rehabilitada, hoteles boutique en el casco histórico amurallado y apartamentos rurales con huerto. | Confluencia de los ríos Cinca y Ara, en la Comarca del Sobrarbe. Sede mundial del ciclismo de montaña (Centro BTT Zona Zero). Ofrece rutas de senderismo hacia el Cañón de Añisclo, piragüismo y kayak en el Embalse de Mediano (con su famoso campanario sumergido) y senderos micológicos.') WHERE codigo_ine = '22907';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hoteles de montaña premium con instalaciones de spa alpino, refugios de alta montaña, apartamentos rústicos e históricos palacios aragoneses rehabilitados. | Corazón del Parque Natural de Posets-Maladeta. Punto de partida para la ascensión al Pico Aneto (techo de los Pirineos) y al Posets. Destaca por el senderismo al Forau de Aigualluts (espectacular sumidero kárstico), esquí de fondo en los Llanos de Hospital y escalada clásica.') WHERE codigo_ine = '22054';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Chalets de montaña independientes, apartamentos rústicos a pie de pista invernal y hoteles pirenaicos con chimenea. | Cabecera del Valle de Tena, bajo la imponente Peña Foratata. Rutas de senderismo de alta dificultad hacia los ibones (lagos glaciares) de Anayet y Respomuso, paseos náuticos en el Embalse de Lanuza, deportes de nieve en FormigalPanticosa y senderos transfronterizos.') WHERE codigo_ine = '22204';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Grandes hoteles balneario de montaña decimonónicos, apartamentos de turismo alpino y casas rurales tradicionales pirenaicas. | Entorno del Balneario de Panticosa a 1.630 metros de altitud. Destaca por la vertiginosa ruta de senderismo de las Pasarelas de Panticosa sobre el río Caldarés, excursiones de montaña hacia el Ibón de Baños, esquí alpino y escalada en vías ferratas calizas.') WHERE codigo_ine = '22170';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales de piedra maciza y pizarra, parador de turismo de montaña en el valle, y albergues para excursionistas. | Acceso directo al Valle de Pineta dentro del Parque Nacional de Ordesa. Ofrece las rutas de senderismo de ascensión al Balcón de Pineta y al Lago de Marboré, caminatas bajo cascadas espectaculares, senderos forestales alpinos y conexión a Francia mediante túnel.') WHERE codigo_ine = '22057';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales familiares integradas en el núcleo del pueblo, apartamentos rústicos con vistas fluviales y posadas pirenaicas. | Bañado por el río Ara (único gran río virgen sin presas del Pirineo). Ofrece la espectacular ruta de la Cascada de Sorrosal, su famosa vía ferrata vertical apta para escaladores, senderismo por el Valle de Ordesa meridional y rafting fluvial en aguas bravas.') WHERE codigo_ine = '22069';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casonas infanzonas de sillería convertidas en hoteles rurales, complejos de apartamentos rústicos con jardín y casas de pueblo de alquiler íntegro. | Nudo estratégico entre el Valle de Tena y el Serrablo. Rutas de senderismo hacia el recóndito Ermita de Santa Elena en un estrecho desfiladero, parques de aventura forestal en tirolinas, cicloturismo de carretera y senderos de interpretación botánica.') WHERE codigo_ine = '22059';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de turismo rural con una de las arquitecturas de piedra mejor conservadas del Pirineo, alojamientos con suelos de losa tradicional. | Parque Natural de los Valles Occidentales. Destaca por la ruta senderista del Valle de Zuriza, caminatas de alta montaña en el entorno kárstico de Linza, senderos botánicos entre abetales salvajes y territorio histórico de los últimos osos autóctonos.') WHERE codigo_ine = '22028';
