UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hotel rural de lujo en antiguo monasterio del siglo XVII, casas rurales de mampostería antigua a la sombra del castillo. | Valle del río Ara. Destaca por las pozas naturales de la Gorga de Boltaña para el baño en verano, rutas senderistas de media montaña que conectan pueblos abandonados del viejo Sobrarbe y senderos micológicos otoñales.') WHERE codigo_ine = '22066';
