UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Apartamentos rústicos orientados al deportista de aventura, casas rurales de piedra y madera tradicionales. | Valle de Benasque bajo. Capital del vuelo libre en España (parapente y ala delta). Rutas de senderismo por el congosto de Ventamillo, senderos cicloturistas de montaña de descenso extremo (Enduro BTT) y rutas fluviales de kayak en el río Ésera.') WHERE codigo_ine = '22084';
