UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales tradicionales con hileras de piedra, apartamentos rústicos adaptados con balcones sobre el valle. | Falda de la mítica peña de Monte Perdido meridional, sobre el río Cinca. Famoso por mantener la tradición etnográfica de las nabatas (antiguas almadías de madera). Rutas de senderismo de media montaña, y senderos micológicos en bosques de pinos.') WHERE codigo_ine = '22144';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Pequeñas casas de aldea pirenaicas aisladas, apartamentos rústicos rústicos de alta montaña con chimenea. | Municipio colgado sobre riscos calizos del Sobrarbe. Destaca por la legendaria Ruta de las Ermitas de Tella (tres pequeños templos colgados sobre el vacío en un entorno de misterios de brujería), senderos a la Cueva del Oso de las Cavernas y cañones de caliza.') WHERE codigo_ine = '22227';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de piedra tradicionales de mampostería pirenaica compacta, apartamentos rústicos de montaña. | Valle de Benasque. Acceso directo al espectacular Valle de Estós. Rutas senderistas de alta montaña que cruzan prados alpinos repletos de ganado, senderos hacia el Ibón de Batisielles y cascadas de deshielo.') WHERE codigo_ine = '22200';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas infanzonas rurales de piedra con grandes arcos de entrada, apartamentos rústicos a orillas del río. | Valle del Ara medio. Senderismo tranquilo y familiar por las riberas del Ara, rutas cicloturistas de montaña que exploran los pueblos de la Solana despoblada y caminos antiguos forestales de pinos y quejigos.') WHERE codigo_ine = '22109';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de turismo rural típicas chistabinas con techados inclinados de pizarra, bordas tradicionales aisladas. | El municipio más alto del Valle de Chistau. Rutas senderistas exigentes de alta montaña hacia los picos fronterizos con Francia (Culfreda y Bachimala), paseos tradicionales entre campos de pasto alpino alto y turismo botánico de montaña.') WHERE codigo_ine = '22114';
