UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales de piedra tradicionales del prepirineo, hostales rurales especializados en turismo activo. | Al pie del colosal macizo del Turbón. Rutas de senderismo hacia las laderas mágicas del Turbón, paseos etnográficos fluviales en el río Ésera bajo cañones estrechos, y punto intermedio para el rafting alpino.') WHERE codigo_ine = '22074';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Pequeñas bordas de alta montaña aisladas, casas de turismo rural construidas con piedra gruesa oscura. | Valle de Vió, uno de los accesos altos al Cañón de Añisclo de Ordesa. Rutas de senderismo espectaculares por los miradores superiores de Ordesa, caminatas boscosas por el Hayedo de la Pardina del Señor (uno de los hayedos otoñales más fotogénicos del Pirineo) y raquetas.') WHERE codigo_ine = '22107';
