UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales rehabilitadas con patios castellano-aragoneses, pequeños alojamientos con encanto rústico de olivares. | Entorno de las sierras de la Ribagorza. Rutas de senderismo hacia el Santuario de Torreciudad, caminatas que miran al cañón del río Cinca, paseos entre campos de viñedos viejos de altura y senderos de olivares.') WHERE codigo_ine = '22214';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas tradicionales de labranza ribagorzana de alta montaña con chimeneas cónicas, apartamentos rústicos. | Valle de Barrabés, lindando con Cataluña. Rutas de senderismo de alta montaña que acceden a los ibones de Angliós, senderos ganaderos que suben a prados de altura bajo cumbres alpinas y rutas de raquetas de nieve invernales.') WHERE codigo_ine = '22157';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Apartamentos turísticos de montaña colgados literalmente sobre riscos calizos del Valle de Tena. | Cuenta con el mirador colgado sobre el Embalse de Búbal y la tirolina doble más larga de Europa sobre un lago. Rutas de senderismo a los ibones del valle, senderos boscosos de pinos y cicloturismo exigente de puertos.') WHERE codigo_ine = '22122';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hoteles de naturaleza e interior construidos bajo criterios bioclimáticos de madera y piedra, casas rurales íntimas. | Bosque de Bonansa. Espectaculares rutas de senderismo adaptado y accesible bajo densos y mágicos bosques de robles y pinos silvestres, caminatas hacia la ermita de San Roque y rutas de observación astronómica de cielos negros.') WHERE codigo_ine = '22067';
