UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de pueblo blanco andaluz de cal y teja con chimenea, antiguos molinos de agua restaurados y hoteles de montaña integrados en el valle. | En el corazón del Parque Natural Sierra de Grazalema (zona de máxima pluviosidad de España). Destaca por el sendero del Pinsapar (bosque relicto de abetos de la era glaciar), la exigente ascensión al pico El Torreón, senderismo por la Garganta Verde y rutas micológicas.') WHERE codigo_ine = '11019';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Eco-lodges integrados en la dehesa, cortijos fortificados tradicionales, tiendas glamping safari de diseño y casas de campo costeras. | Confluencia del Parque Natural del Estrecho y Los Alcornocales. Destaca por las rutas de senderismo por los acantilados del Parque del Estrecho, avistamiento ornitológico masivo de aves migratorias, avistamiento de cetáceos en libertad, dunas salvajes de Bolonia y windsurf/kitesurf.') WHERE codigo_ine = '11035';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Villas rurales con vistas panorámicas al lago, casas tradicionales encaladas de alquiler íntegro y fincas olivareras de agroturismo. | Falda de la Sierra de Líjar y bañado por el Embalse de Zahara-El Gastor. Ofrece senderismo costero de interior bordeando el embalse, deportes náuticos sin motor (kayak, paddle surf), la ruta de la Garganta Verde (cañón kárstico calizo gigantesco) y playas fluviales de interior en \"Arroyomolinos\".') WHERE codigo_ine = '11042';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales cueva auténticas (viviendas integradas bajo un colosal saliente de roca natural), hostales rústicos de arquitectura singular. | Cañón fluvial del río Guadalporcún. Rutas de senderismo de los Bandoleros, paseos de interpretación geológica por los tajos de roca que cubren las calles del municipio, rutas cicloturistas entre campos de olivares y cañadas reales.') WHERE codigo_ine = '11034';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales integradas intramuros en el interior de un alcázar medieval fortificado, y fincas de montería rústicas. | Pleno Parque Natural de Los Alcornocales. Rutas de senderismo bajo la densa selva mediterránea de alcornoques y quejigos húmedos, senderos hacia el embalse de Guadarranque, observación de la \"berrea\" del ciervo y senderismo etnográfico por antiguos canutos (valles fluviales de reliquia subtropical).') WHERE codigo_ine = '16006';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de campo de piedra con grandes patios andaluces rústicos, antiguas casas de labranza rehabilitadas con chimenea de leña. | Parque Natural de Los Alcornocales. Destaca por el Sendero del Río Hozgarganta (último río virgen sin regular de Andalucía), caminatas bajo la fronda de los bosques de niebla locales, rutas micológicas enfocadas en el hongo \"chantarela\" y senderos ecuestres.') WHERE codigo_ine = '11021';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hoteles boutique rurales en antiguas casas de vecinos fortificadas con patios de azulejos, fincas ecuestres y cortijos aislados. | Entorno de las marismas del río Barbate y colinas litorales. Rutas de senderismo suave por el núcleo de los molinos de agua de Santa Lucía (paraje natural con cascadas rústicas y acueducto romano), senderos ecuestres hacia playas vírgenes cercanas de El Palmar y cicloturismo de llanura.') WHERE codigo_ine = '11039';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casonas rurales amplias para grupos a las faldas de grandes farallones calcáreos, apartamentos turísticos de montaña. | Frontera natural entre Grazalema y Los Alcornocales. Rutas de senderismo por la histórica Calzada Romana de Ubrique a Benaocaz, senderos de escalada deportiva en las paredes rocosas de la Cruz del Tajo, y senderos micológicos de alcornocal.') WHERE codigo_ine = '11038';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Grandes cortijos ganaderos y agrícolas con encanto andaluz, hoteles de naturaleza con fincas arboladas y picadero. | Centro geográfico de Los Alcornocales (Ruta del Toro). Destaca por la ruta del sendero de Valdeinfierno (con pasarelas adaptadas en un canuto subtropical denso), rutas de cicloturismo de montaña exigentes (BTT), kayak de interior en el embalse de Charco Redondo y observación de la berrea.') WHERE codigo_ine = '16016';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Alojamientos rurales integrados en antiguas estaciones de tren restauradas, cooperativas de turismo de interior y casas de cal de pueblo. | Punto de partida neurálgico de la Vía Verde de la Sierra (36 km de antigua infraestructura ferroviaria acondicionada para cicloturismo y senderismo). Rutas hacia la Reserva Natural del Peñón de Zaframagón (la mayor colonia andaluza de buitres leonados que anida en roca) y olivares de sierra.') WHERE codigo_ine = '11024';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales rústicas, antiguos molinos de trigo rehabilitados junto a arroyos forestales y dehesas de ganado. | Parque Natural de Los Alcornocales alto. Destaca por las rutas de senderismo de ascensión al pico Aljibe (techo de la comarca con vistas de dos mares), paseos fluviales por el sendero de la Garganta de Puerto Oscuro y observación micológica de otoño.') WHERE codigo_ine = '16001';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Villas exclusivas de campo e interior lindando con estuarios marinos, apartamentos rurales en pedanías forestales. | Estuario del río Guadiaro y Pinar del Rey. Rutas de senderismo familiar plano por el Pinar del Rey (bosque público maduro de pinos, alcornoques y acebuches con arroyos), paseos de avistamiento de aves acuáticas en las lagunas de Torreguadiaro y kayak fluvial de baja dificultad.') WHERE codigo_ine = '11033';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Cortijillos costeros con huerto, chalets rurales de campo rodeados de pinares junto a la costa atlántica. | Entorno litoral de los Pinares de Roche. Espectaculares rutas de senderismo plano por los senderos de los acantilados de Roche y sus calas escondidas vírgenes, caminatas entre retamas protegidas y avistamiento costero de aves rapaces menores.') WHERE codigo_ine = '16008';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas palacio señoriales rústicas con patios de arcadas de piedra, hostales rurales con encanto andaluz medieval. | Balcón de la Janda, elevación de campiña alta. Rutas que conectan con senderos de cañadas reales ganaderas, paseos fotográficos de naturaleza por el entorno adehesado del cuaternario donde pasta el toro bravo y dehesas de encinas viejas.') WHERE codigo_ine = '11023';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Parador nacional en palacio monumental, casas de turismo rural colgadas en el desfiladero calizo e históricas haciendas. | Asentado sobre una monumental peña caliza tallada por el río Guadalete. Rutas de senderismo que bordean el Paraje Natural de la Cola del Embalse de Arcos (ornitología de primer nivel de aves acuáticas), paseos en piragua por el río y senderos agrícolas de campiña.') WHERE codigo_ine = '16004';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales de pueblo tradicionales de interior, apartamentos rústicos acogedores y fincas rurales de colina con frutales. | Transición a la Sierra de Grazalema alta. Rutas de senderismo arqueológico hacia las ruinas de la ciudad romana de Iptuci, caminatas por colinas de monte bajo mediterráneo aromático (tomillo, romero) y rutas gastronómicorurales vinculadas a la apicultura tradicional (rutas de la miel).') WHERE codigo_ine = '11026';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de pueblo andaluzas de cal blanca adaptadas con patios interiores llenos de fuentes y limoneros, hostales rústicos. | Falda de la Sierra de Líjar. Capital andaluza del vuelo libre (parapente y ala delta) gracias a sus corrientes térmicas de montaña. Rutas de senderismo técnico que suben al macizo de la Sierra de Líjar por la canal, senderos forestales de acebuches y pinares, y rutas cicloturistas.') WHERE codigo_ine = '16003';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas tradicionales de alta montaña caliza de la serranía, apartamentos rústicos con techos bajos y chimeneas de piedra. | Municipio más alto de la provincia de Cádiz (850 metros), encajonado en un poljé kárstico estrecho. Meca de la espeleología por albergar grandes simas de la región (Sima de Villaluenga). Rutas senderistas de montaña por los lapiaces calizos secos, rutas del queso payoyo y senderos pastoriles.') WHERE codigo_ine = '11040';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Fincas de viñedo de interior con casas de campo rústicas alejadas de las zonas hoteleras masivas de costa. | Entorno del Parque Natural de la Bahía de Cádiz y pinares interiores. Rutas de senderismo plano por los Pinares de la Barrosa y de Claverán, paseos botánicos por salinas tradicionales recuperadas para el ecoturismo, ornitología de flamencos y kayak de mar.') WHERE codigo_ine = '16007';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de campo agrícolas y de dehesa bajas independientes, apartamentos rústicos sencillos en entornos de pinar. | Custodia el Complejo Endorreico de Puerto Real (Lagunas de Taraje, Comisario y San Antonio). Rutas de senderismo plano de alta protección ecológica entre marismas de interior y lagunas, paseos por el pinar de Las Canteras (bosque maduro) y rutas cicloturistas de llanura.') WHERE codigo_ine = '11028';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales de campo aisladas en llanuras adehesadas de monte bajo, cortijos agrícolas tradicionales. | Entorno de las faldas de la Sierra de las Cabras y cercanía al Embalse de Guadalcacín II. Rutas de senderismo hacia el nacimiento del manantial de Tempul, senderos cicloturistas de montaña que bordean el gran embalse de interior, pesca de agua dulce y paseos entre encinares de campiña alta.') WHERE codigo_ine = '11902';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de campo tradicionales vinculadas a las huertas navaceras (cultivos en arena de playa), alojamientos de interior de viñedo. | Margen izquierda de la desembocadura del río Guadalquivir, frente al Parque Nacional de Doñana. Rutas que conectan con el Espacio Natural Protegido de Doñana mediante barcazas fluviales, paseos por el Sendero del Pinar de la Algaida (bosque de pinos con restos arqueológicos), ornitología en las marismas de Bonanza y rutas cicloturistas llanas. PROVINCIA: TERUEL (Texto Plano Limpio)') WHERE codigo_ine = '11032';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Posadas medievales integradas en murallas de yeso rojizo, casas de turismo rural con entramados de madera tradicionales y hoteles boutique con vistas al cañón fluvial. | En el corazón de la Sierra de Albarracín. Destaca por el Paisaje Protegido de los Pinares de Rodeno, rutas de senderismo hacia las pinturas rupestres prehistóricas, el sendero fluvial del río Guadalaviar que rodea el pueblo, senderos de alta montaña y una de las mecas mundiales de la escalada en bloque (búlder).') WHERE codigo_ine = '43001';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Antiguas masías fortificadas aisladas entre olivares y almendros, hoteles rurales de diseño sostenible, casas de piedra gótica rehabilitadas en el casco viejo. | Capital de la Comarca del Matarraña (la Toscana española). Ofrece rutas de senderismo y cicloturismo por las riberas del río Matarraña, conexiones directas con la Vía Verde de la Val de Zafán, paseos botánicos por valles mediterráneos y senderos micológicos de encinar.') WHERE codigo_ine = '44246';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales rústicas ligadas a antiguos molinos papeleros del siglo XVIII junto al río, hostales con encanto de montaña y fincas de agroturismo. | Estribaciones del Parque Natural de los Puertos de Beceite. Sede de la espectacular ruta senderista de El Parrizal (pasarelas de madera colgadas sobre un angosto cañón fluvial de aguas turquesas), pozas naturales aptas para el baño como L''Assut y la Pesquera, y rutas cicloturistas de montaña (BTT) de alto nivel.') WHERE codigo_ine = '44037';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casonas de piedra señoriales del Maestrazgo, antiguos cuarteles y hosterías carlistas rehabilitadas con chimeneas rústicas, apartamentos rurales familiares. | Encaramado a un impresionante risco calizo a 1.300 metros de altitud en el Maestrazgo salvaje. Rutas de senderismo de los Miradores del Maestrazgo, caminatas por las hoces y muelas calcáreas talladas por el río Cantavieja, y observación de grandes colonias de buitre leonado y cabra montés.') WHERE codigo_ine = '44059';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Palacetes rurales renacentistas de sillería dorada con balcones de forja, casas de turismo rural independientes y apartamentos boutique de interior. | Comarca del Matarraña alto. Destaca por las rutas de senderismo arqueológico hacia el poblado íbero de San Antonio, caminatas tranquilas entre campos de olivos milenarios y viñedos, rutas cicloturistas de carretera sin tráfico y paseos por bosques mediterráneos de pino carrasco.') WHERE codigo_ine = '44049';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hoteles rurales familiares de montaña orientados al turismo de nieve, casas rurales de alquiler íntegro con chimeneas de piedra y antiguos caseríos ganaderos. | Comarca de Gúdar-Javalambre. Rutas senderistas bajo bosques boreales de pino negro, turismo micológico de primer nivel (especializado en trufa negra de Teruel y robellones), proximidad directa a la estación de esquí de Valdelinares y cicloturismo de montaña por los Altos de Gúdar.') WHERE codigo_ine = '44158';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de labranza tradicionales con espectaculares aleros de madera tallada a mano, hoteles boutique rurales con patios interiores ajardinados, posadas medievales. | Piedemonte de la Sierra de Gúdar (Premio Europa Nostra por su conservación). Ofrece la ruta senderista del río Mijares, senderos de interpretación botánica por dehesas de sabinas y encinas viejas, observación de estrellas (zona con certificación Starlight de cielos limpios) y rutas a caballo.') WHERE codigo_ine = '44201';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de turismo rural intramuros integradas en una joya arquitectónica medieval intacta, palacetes de la Orden del Temple para pernocta. | Corazón del Maestrazgo. Ofrece paseos etnográficos de aislamiento absoluto, rutas de senderismo hacia el Monumento Natural de las Cuevas de Cañart, caminos tradicionales de herradura delimitados por interminables muros de piedra seca (Patrimonio de la Humanidad) y caminatas por riberas de montaña secas.') WHERE codigo_ine = '44149';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Apartamentos rústicos de alta montaña aislados, casas de piedra de cantería con ventanas saeteras tradicionales y chimeneas de campana. | Enclavado en el Parque Cultural del Maestrazgo, a las faldas de la Sierra de Gúdar. Impresionantes rutas de senderismo hacia el cañón del río Monleón, caminatas exigentes entre pinares silvestres silvestres alpinos, senderos de interpretación micológica otoñal y cascadas de deshielo ocultas.') WHERE codigo_ine = '44193';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hoteles de naturaleza de lujo orientados al ecoturismo y la gastronomía de kilómetro cero, masías unifamiliares rodeadas de pinares. | Matarraña montañoso occidental, lindando con Castellón. Destaca por las rutas de senderismo que ascienden a las Peñas de Masmut (colosales paredes de roca caliza rosada), avistamiento de buitres leonados, rutas de recolección de setas en sus frondosos pinares húmedos de montaña y BTT.') WHERE codigo_ine = '44154';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Parador nacional emplazado en un castillo calatravo medieval alto, fincas de campo de labranza y casas rurales de vega agrícola. | Entorno del río Guadalope y la Estanca de Alcañiz. Ofrece el sendero fluvial de los Azudes, observación ornitológica en el humedal de la Estanca (ánades, garzas), rutas cicloturistas llanas y punto de partida de los tramos bajo de la Vía Verde del Matarraña.') WHERE codigo_ine = '43002';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales unifamiliares con porches de roca, apartamentos rústicos al pie de imponentes peñascos calizos y castillos templarios. | Maestrazgo norte. Alberga el Monumento Natural del Puente de Fonseca (formación kárstica natural sobre el río Guadalope). Destaca por la ruta senderista que cruza el túnel excavado en la roca del embalse de Santolea y senderos micológicos de monte bajo.') WHERE codigo_ine = '44071';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Alojamientos rurales integrados en antiguas casas señoriales medievales con bodegas de vino, masías rurales con encanto en los campos linderos. | Comarca del Matarraña. Cruce de caminos de la Vía Verde de la Val de Zafán (cicloturismo de túneles y viaductos espectaculares). Rutas senderistas de arte rupestre en el barranco del Calapatá, paseos llanos fotográficos y senderos de olivares.') WHERE codigo_ine = '44086';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de pueblo tradicionales de mampostería estrecha, apartamentos rurales acogedores para familias y espeleólogos. | Maestrazgo kárstico. Alberga el Monumento Natural de las Grutas de Cristal (colosal cueva de estalactitas y estalagmitas excéntricas). Rutas de senderismo por el cañón del río Guadalopillo, caminatas geológicas interpretativas y senderos entre huertos.') WHERE codigo_ine = '44151';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales de alta montaña de piedra caliza con aislamiento reforzado, apartamentos rústicos forestales pegados al bosque. | Sierra de Albarracín, a más de 1.500 metros de altitud. Uno de los mayores pulmones de pinares de pino silvestre de España. Destaca por el senderismo micológico extremo (paraíso del hongo boletus), rutas botánicas de las fuentes de Bronchales, avistamiento de ciervos y corzos en libertad y aire puro de altitud.') WHERE codigo_ine = '44045';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Chalets alpinos rústicos de alta montaña tradicionales, apartamentos de turismo de nieve a pie de laderas forestales. | Municipio más alto de España (núcleo urbano a 1.692 metros) en la Sierra de Gúdar. Rutas de senderismo de alta montaña entre pinares boreales de pino negro autóctono, caminatas hacia los cortados de las umbrías, raquetas de nieve invernales y esquí alpino.') WHERE codigo_ine = '44244';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de piedra tradicionales de montaña con muros anchos aislantes, apartamentos rústicos en valles cerrados de frutales. | Valle del río Pau, Sierra de Gúdar. Rutas de senderismo hacia el Monumento Natural del Pino del Escobón (abeto-pino monumental centenario), paseos de interpretación fluvial, senderos ganaderos que suben a brañas de altura y turismo micológico.') WHERE codigo_ine = '44137';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Palacetes rurales de piedra caliza con espectaculares arcos, posadas de turismo rural con encanto del Matarraña. | Cuenta con la tirolina en posición tumbada más larga de Europa (casi 2 km cruzando un valle de montaña). Rutas de senderismo hacia el Covavina, caminatas que miran a los Puertos de Beceite, senderos botánicos entre encinas y olivares rústicos.') WHERE codigo_ine = '44114';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casonas rurales serranas de piedra con forja tradicional, apartamentos de montaña independientes rodeados de dehesas ganaderas. | Extremo norte de la Sierra de Albarracín. Destaca por los singulares \"Ríos de Piedra\" (colosales acumulaciones de bloques de cuarcita de origen glaciar únicos en Europa). Rutas de senderismo hacia el pico Caimodorro, paseos por melojares (robledales) y recolección de setas.') WHERE codigo_ine = '44174';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de pastores de la alta sierra tradicionales, apartamentos rústicos orientados al turismo etnográfico y de aislamiento. | Muela de San Juan, nacimiento del río Guadalaviar/Turia. Capital histórica de la transhumancia ganadera. Rutas de senderismo hacia los nacimientos fluviales, paseos por inmensos pastizales alpinos de alta montaña, senderos micológicos de otoño y avistamiento de fauna ibérica de monte alto.') WHERE codigo_ine = '44120';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Alojamientos rurales unifamiliares con chimenea central, apartamentos de montaña construidos en mampostería oscura de roca. | Segundo pueblo más alto de España, en la falda de la Muela de San Juan. Rutas de senderismo arqueológico hacia las dehesas celtíberas del llano, caminatas de invierno con raquetas de nieve, pistas de esquí de fondo forestales de naturaleza y miradores hacia valles de origen glaciar.') WHERE codigo_ine = '44119';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de campo tradicionales de la cuenca minera y agrícola del río Alfambra, pequeños hostales rurales sencillos. | Uno de los yacimientos paleontológicos de dinosaurios más importantes de Europa. Rutas de senderismo e interpretación al aire libre que siguen reproducciones de dinosaurios a escala real integradas en riberas fluviales arcillosas, y senderos geológicos singulares. PROVINCIA: CUENCA (Texto Plano Limpio)') WHERE codigo_ine = '44115';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales de piedra de mampostería con espectaculares terrazas y miradores a la laguna, chalets de madera serranos independientes y apartamentos rústicos. | Ubicado plenamente en el Parque Natural de la Serranía de Cuenca. Destaca por la emblemática Senda del Escalerón a la Raya (ruta que transita sobre colosales cortados calizos que vigilan el valle), el sendero circular llano que bordea la Laguna de Uña (paraíso de la observación de aves acuáticas y rapaces), y barranquismo técnico en el arroyo de la Madera.') WHERE codigo_ine = '16219';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casonas rurales con portadas de sillería dorada y balcones de forja tradicional, apartamentos rústicos acogedores y fincas rurales ligadas a la producción artesana de mimbre. | Puerta natural a la comarca de la Alcarria conquense y la Serranía. Sede de la espectacular ruta senderista del Estrecho de Priego (un angosto y profundo desfiladero calizo tallado por el río Escabas con paredes verticales de más de 80 metros), vías ferratas de montaña con puentes colgantes extremas para escaladores y senderos micológicos.') WHERE codigo_ine = '16170';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hostales de alta montaña especializados en senderistas, complejos de cabañas forestales de madera rodeadas de inmensos pinares silvestres y casas rurales con chimenea de campana. | Zona norte de la Serranía alta. Punto de partida directo de la ruta de senderismo hacia el Nacimiento del Río Cuervo (Monumento Natural célebre por sus saltos de agua y espectaculares formaciones de cascadas de toba caliza cubiertas de musgo mágico), senderos micológicos otoñales y avistamiento de ciervos y gamos en la umbría.') WHERE codigo_ine = '16215';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casonas de labranza tradicionales serranas unifamiliares con corrales recuperados, apartamentos rurales de interior y alojamientos de montaña junto a pinares. | Entorno de la alta serranía y del balneario de Solán de Cabras. Ofrece la ruta de senderismo de la Hoz de Beteta, caminatas de interpretación botánica por el desfiladero fluvial rodeado de tilos centenarios (un oasis húmedo único), pasarelas sobre el río Guadiela, y rutas cicloturistas de montaña (BTT).') WHERE codigo_ine = '16053';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de turismo rural con mampostería antigua de piedra a la sombra del castillo de Rochafrida, posadas serranas tradicionales con amplios porches de leña y apartamentos para montañeros. | Entorno de lapiaces y cañones calizos extremos. Destaca por la ruta senderista del Monumento Natural de las Torcas de Lagunaseca (espectaculares depresiones circulares del terreno en roca kárstica), senderos que cruzan la Hoz de Beteta bajo densos bosques de quejigos y pinos laricios, y recolección de setas en otoño.') WHERE codigo_ine = '16035';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Alojamientos rurales distribuidos en pequeños barrios o \"hazas\" de montaña tradicionales, casas de aldea de piedra caliza con aislamiento reforzado para el invierno. | Custodia la cabecera del cañón del río Cuervo. Espectaculares rutas de senderismo hacia los altos de la muela, senderos pastoriles que acceden a prados alpinos altos donde pasta el ganado, observación de cielos limpios nocturnos (zona integrada en el Parque con certificación Starlight) y raquetas de nieve invernales.') WHERE codigo_ine = '16239';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de piedra medievales de alquiler íntegro integradas dentro de un pequeño casco histórico amurallado serrano, apartamentos rústicos pequeños. | Bañado por el río Escabas alto. Ofrece paseos de aislamiento absoluto, rutas de senderismo exigentes hacia la dehesa de Poyatos, caminos tradicionales forestales entre avellanos, tejos y densas masas de pinos silvestres, y pesca deportiva truchera sin muerte de alta montaña.') WHERE codigo_ine = '16165';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales de piedra berroqueña unifamiliares con amplias parcelas forestales, apartamentos de turismo de montaña rústicos. | Entorno de las muelas de Cuenca. Alberga el paraje natural de Tierra Muerta y los Callejones de Las Majadas (espectacular laberinto de callejones, arcos y monolitos kársticos calcáreos esculpidos por el viento y el agua). Rutas senderistas geológicas e interpretativas y senderos micológicos para la recolección de hongos boletus y níscalos.') WHERE codigo_ine = '16040';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Apartamentos tradicionales rurales con chimeneas rústicas junto al río, casas de pueblo de alquiler íntegro optimizadas para grupos familiares. | Ribera del río Escabas. El mayor hub de turismo estival de agua dulce de la provincia; destaca por sus famosas playas fluviales naturales de aguas cristalinas ideales para el baño y el descanso veraniego. Rutas de senderismo plano de ribera bajo túneles vegetales de mimbreras doradas, alisos y sauces, y paseos fotográficos.') WHERE codigo_ine = '16048';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de montaña enriscadas en una colina cónica escarpada con arquitectura tradicional serrana de yeso y madera caliza, apartamentos rústicos. | Valle del río Júcar alto. Rutas de senderismo de ascensión al pico de la Mogorrita (el techo de la provincia de Cuenca con 1.864 metros de altitud), paseos fluviales por el sendero alto del Júcar, observación ornitológica de buitres leonados y rutas de micología de pinar.') WHERE codigo_ine = '16107';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Parador nacional emplazado en un imponente castillo medieval encaramado al risco, casas de turismo rural intramuros de piedra, y posadas con encanto manchego. | Ubicado sobre un espectacular meandro encajonado del río Júcar inferior. Ofrece la famosa ruta senderista de la Hoz de Alarcón (sendero circular homologado que bordea el profundo cañón fluvial bajo las torres fortificadas medievales), piragüismo, vela y kayak náutico de interior en el cercano Embalse de Alarcón.') WHERE codigo_ine = '14001';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales de piedra tradicionales del extremo oriental de la provincia (influencia valenciana y serrana), apartamentos rústicos con jardín y barbacoa. | Entorno de las serranías bajas de cuarcita. Destaca por la ruta del Sendero de las Torcas de Talayuelas, caminatas hacia los Callejones de Talayuelas (formaciones geológicas de roca de arenisca rojiza espectaculares que simulan murallas), senderos boscosos de pinos y dehesas agrícolas.') WHERE codigo_ine = '16202';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Complejos de turismo de interior y aventura, casas de cal de pueblo andalusí-manchego con chimeneas y apartamentos rurales sobre el río. | Confluencia de cinco ríos (destacando el Cabriel). Alberga el Monumento Natural de las Chorreras del Cabriel (colosal tramo fluvial de saltos de agua, cascadas, pozas naturales turquesas y tobas calcáreas). Rutas de senderismo acuático, barranquismo, rafting fluvial, kayak y sendas de media montaña.') WHERE codigo_ine = '16082';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hoteles rurales integrados en antiguas casas palacio manchegas con patios de columnas de madera, posadas rurales e históricas fincas de labranza de llanura cerealista. | Turismo rural de llanura manchega y molinos de viento. Rutas senderistas de interpretación histórica y natural rodeando las faldas de la colina que custodia su imponente y fotogénico castillo del siglo XV, caminatas tranquilas por cañadas y senderos rodeados de viñedos viejos de llanura alta.') WHERE codigo_ine = '16033';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de labranza tradicionales de la Mancha conquense de anchos muros de tapial y fachadas blancas de cal con bodegas subterráneas, alojamientos rurales pequeños. | Entorno de la llanura de viñedos y monte bajo mediterráneo. Rutas que conectan con senderos de cañadas reales ganaderas de largo recorrido, caminatas llanas ideales para cicloturismo familiar entre dehesas agrarias de encinas centenarias aisladas y observación ornitológica de aves esteparias raras.') WHERE codigo_ine = '16100';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de pueblo tradicionales manchegas adaptadas rústicamente para alquiler íntegro con patios interiores y barbacoas, hostales rurales de interior. | Conocido como El Balcón de la Mancha por su monumental cerro repleto de molinos de viento tradicionales. Alberga el Complejo Lagunar de Mota del Cuervo (Reserva de la Biosfera). Rutas de senderismo plano de alta observación ornitológica de aves palustres (flamencos, avetoros), senderos llanos de cicloturismo de campiña y paseos de interpretación agraria.') WHERE codigo_ine = '16133';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Complejos de cabañas forestales de madera integradas bajo densas pinadas, casas tradicionales serranas de mampostería gruesa caliza. | Corazón de la Serranía de Cuenca alta. Destaca por el paraje natural de Los Callejones de Las Majadas, rutas de senderismo exigentes de montaña, paseos hacia el Hosquillo (parque zoológico natural en un cañón cerrado donde se observa oso pardo, lobo ibérico y ciervos en semilibertad, con acceso controlado), y senderos de pastores.') WHERE codigo_ine = '16121';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de campo agrícolas y de monte bajo independientes de interior, apartamentos rústicos sencillos en el casco fortificado. | Entorno del gran Embalse de Buendía y riberas del río Guadiela. Sede de la famosa Ruta de las Caras (recorrido de senderismo plano mágico bajo un bosque de pinos carrascos donde se encuentran colosales esculturas y rostros esculpidos directamente en las paredes de roca arenisca naturales). Senderos náuticos de embalse (kayak, piragüismo) y paseos ornitológicos en cortados de caliza. PROVINCIA: BURGOS (Texto Plano Limpio)') WHERE codigo_ine = '16041';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de turismo rural colgadas en la roca caliza del desfiladero, posadas medievales intramuros con entramados de madera y apartamentos rústicos con vistas al río Ebro. | Ubicado plenamente en el Parque Natural de Montes Obarenes-San Zadornil. Destaca por la ruta de senderismo del Desfiladero del río Purón (estrecho cañón fluvial espectacular), la senda del cañón del Ebro, paseos botánicos por el hayedo de San Zadornil (\"la Nueva York de los bosques\") y piragüismo de interior.') WHERE codigo_ine = '09134';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Posadas reales castellanas de anchos muros de sillería dorada, hoteles rurales con encanto histórico y casas de pueblo independientes para grupos. | Espacio Natural Protegido de Sabinares del Arlanza y de la Yecla. Alberga el Desfiladero de la Yecla (espectacular y angosta garganta kárstica transitable a pie mediante pasarelas colgantes sobre el río), la ruta del Cementerio de Sad Hill (escenario cinematográfico integrado en la naturaleza dehesa), y el sendero de los sabinares más antiguos del planeta.') WHERE codigo_ine = '09358';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Palacetes rurales rústicos con fachadas de cal y vigas de madera vista, apartamentos rústicos acogedores y alojamientos de ribera junto al Arlanza. | Valle del río Arlanza. Ofrece la ruta senderista del Sendero del Buen Conde, caminatas hacia las ruinas del Monasterio de San Pedro de Arlanza (rodeado de inmensos bosques de encinas y sabinas de roca), senderos cicloturistas de llanura alta y paseos de interpretación agrícola.') WHERE codigo_ine = '09113';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casonas hidalgas fortificadas y palacios rurales de sillería gruesa, posadas de montaña orientadas a montañeros y cabañas pasiegas-burgalesas en las pedanías del norte. | Comarca de Las Merindades, frontera con los Valles Pasiegos. Destaca por el Monumento Natural de Ojo Guareña (colosal complejo de cuevas kársticas con ermita rupestre). Ofrece rutas de alta montaña hacia Castro Valnera, senderos bajo hayedos de las faldas cantábricas, y raquetas de nieve en invierno.') WHERE codigo_ine = '09124';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de montaña de piedra roja caliza y teja curva tradicionales de la sierra alta, apartamentos rústicos con chimenea de leña y albergues de naturaleza. | Corazón de la Sierra de la Demanda. Nudo de la Vía Verde de la Demanda (antiguo trazado ferroviario minero ideal para senderistas y cicloturistas). Rutas de ascensión alpina al Pico Mencilla y al San Millán (techo de Burgos con 2.131 metros), senderos rodeados de acebales protegidos, robledales centenarios y el embalse del Arlanzón.') WHERE codigo_ine = '09266';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de turismo rural intramuros con patios de mampostería antigua, apartamentos turísticos integrados en el casco histórico señorial. | Eje del Parque Natural de Montes Obarenes. Sede del Sendero del Desfiladero de la Horadada (colosal garganta cortada por el río Oca). Ofrece rutas de senderismo botánico entre encinares atlánticos y mediterráneos mixtos, paseos fluviales por canales medievales de agua y micología forestal de otoño.') WHERE codigo_ine = '09238';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Posadas de alta montaña construidas con vigas de pino de la Demanda y piedra caliza, casas rurales unifamiliares de pinar aisladas. | Custodia el Parque Natural de las Lagunas Glaciares de Neila. Espectaculares rutas de senderismo de alta montaña que recorren el borde de los circos glaciares (Laguna Negra, Laguna Larga, Cascada), senderos micológicos de pinar húmedo alto (boletus), observación astronómica certificada Starlight y senderos de pastores.') WHERE codigo_ine = '09232';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Parador nacional en el colosal Palacio Ducal herreriano, posadas castellanas con patios porticados rústicos, casas rurales de campiña. | Ribera del río Arlanza medio. Rutas que conectan con senderos de cañadas reales ganaderas, caminatas llanas ideales para cicloturismo familiar entre dehesas agrarias de encinas y cultivos, y rutas enológicas en la Denominación de Origen Arlanza.') WHERE codigo_ine = '09194';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hostales rurales especializados en micología y turismo activo, cabañas de madera forestales y grandes casas de piedra de cantería burgalesa. | Comarca de Pinares, falda meridional de la Demanda. Rutas de senderismo al comunero de Revenga (necrópolis medieval tallada en roca rodeada de robles centenarios), caminatas hacia las Lagunas de Neila, recolección masiva de hongos boletus y níscalos en pinares silvestres infinitos y senderos fluviales del Arlanzón joven.') WHERE codigo_ine = '09289';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas solariegas de turismo rural amplias, hoteles boutique de interior con encanto medieval en el casco antiguo. | Valle de Tobalina alto, Las Merindades. Rutas de senderismo suave que bordean el río Trueba, paseos cicloturistas llanos de gran recorrido por el antiguo trazado del Santander-Mediterráneo, y punto base para explorar los cañones de caliza circundantes.') WHERE codigo_ine = '09209';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales vinculadas al patrimonio industrial textil del siglo XIX (antiguas fábricas e hilaturas reconvertidas), apartamentos rústicos. | Sierra de la Demanda húmeda. Sede de la ruta de senderismo de la Senda de los Cascajales, caminatas bajo la umbría de densos hayedos calcícolas del río Oropesa, senderos micológicos micológicos de pinar y quejigal y paseos fotográficos fluviales de montaña.') WHERE codigo_ine = '09274';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hoteles de campo y casas de turismo rural integrados en bodegas subterráneas de la Ribera del Duero, fincas vinícolas tradicionales. | Comarca de la Ribera del Duero. Rutas de senderismo suave entre viñedos centenarios de uva tempranillo, paseos cicloturistas llanos por los caminos de sirga del canal del Duero, turismo gastronómico-rural de asados y enoturismo de primer nivel mundial.') WHERE codigo_ine = '09256';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de labranza castellanas tradicionales de anchos muros de tapial y piedra caliza blanca con patios de carruajes, posadas rurales. | Llanura cerealista de la comarca de Odra-Pisuerga. Cruzado por el Camino de Santiago de la Meseta. Rutas de senderismo plano de interpretación histórica que siguen las calzadas romanas locales (Segisama), caminatas tranquilas de dehesa agraria y avistamiento de avifauna esteparia.') WHERE codigo_ine = '09363';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Alojamientos rurales unifamiliares en el casco fortificado de piedra y caliza, apartamentos rústicos de montaña. | Borde del Páramo de Masa y cuna de Félix Rodríguez de la Fuente. Cuenta con el espectacular diapiro salino (fenómeno geológico único visible desde el espacio). Rutas de senderismo por las antiguas Salinas romanas de evaporación, caminatas de ascensión al castillo calizo sobre el abismo y rutas ornitológicas de grandes rapaces de roca.') WHERE codigo_ine = '09272';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Palacetes rurales renacentistas con patios porticados rústicos, posadas de turismo rural medievales con vistas al castillo calizo alto. | Ribera del Duero oriental. Rutas de senderismo histórico que rodean su torre del homenaje del siglo X, caminatas agrícolas entre viñedos de cepa vieja, y senderos llanos fluviales que siguen el curso del río Arandilla.') WHERE codigo_ine = '09261';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Albergues y casonas de turismo de interior vinculados al Camino de Santiago Francés, casas de labranza riojano-burgalesas. | Comarca de la Riojilla Burgalesa, falda norte de la Demanda. Rutas del Camino de Santiago, senderismo hacia las cuevas eremíticas paleocristianas talladas en las colinas de arcilla linderas, paseos por las riberas del río Tirón y rutas cicloturistas de dehesa.') WHERE codigo_ine = '09048';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales cueva bioclimáticas (viviendas excavadas directamente en la arcilla del risco de la montaña), hoteles de campo orientados al ecoturismo de llanura y apartamentos rurales familiares. | Puerta de entrada oficial al Parque Natural y Reserva de la Biosfera de las Bardenas Reales. Ofrece una experiencia única de turismo rural en un paisaje semidesértico. Destaca por las rutas de cicloturismo de montaña (BTT) bordeando formaciones como Castildetierra, senderismo geológico por barrancos de yeso y observación de aves esteparias y rapaces de desierto.') WHERE codigo_ine = '31032';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Caseríos aislados de piedra y pradera ganadera de la comarca de Xareta, apartamentos rústicos familiares e íntimos rodeados de bosques mágicos. | Célebre por su monumental Cueva de las Brujas (Sorginen Lezea), un colosal túnel kárstico natural horadado por el regato del Infierno. Destaca por el Sendero de las Cuevas (que conecta peatonalmente con Urdax y las cuevas de Sara en Francia mediante un camino marcado por un caballo azul), senderismo de castañares y mitología.') WHERE codigo_ine = '31264';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales y caseríos típicos del Valle de Larraun con grandes solanas de madera orientadas al sur, hoteles de montaña especializados en cicloturismo. | Falda de la impresionante Sierra de Aralar. Eje central de la Vía Verde del Plazaola (antiguo trazado de tren reconvertido para caminantes y ciclistas). Rutas de senderismo forestal hacia el Nacedero del río Iribas, caminatas micológicas entre hayedos brumosos y cuevas calizas como Mendukilo.') WHERE codigo_ine = '33009';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hoteles rurales de fachada histórica monumental, posadas castellano-navarras de sillería gruesa junto al río Ega y apartamentos rústicos. | Nudo logístico monumental del Camino de Santiago. Ofrece la espectacular ruta de senderismo del Cañón del río Urederra en la cercana Sierra de Urbasa (famoso por sus pozas naturales e increíbles cascadas de aguas de color azul turquesa cristalino), paseos de ribera fluvial y cicloturismo de carretera.') WHERE codigo_ine = '33007';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hoteles e instalaciones balnearias históricas de interior integradas en entornos de roca de arenisca rojiza, posadas rurales de la Ribera alta. | Extremo sur de Navarra, cuenca del río Alhama. Rutas de senderismo hacia el Macizo de la Atalaya y la formación del Macizo de Roscas (espectaculares agujas de roca caliza y arenisca esculpidas por la erosión). Rutas que recorren cuevas eremíticas ocultas, senderos de matorral mediterráneo y paseos de huerta.') WHERE codigo_ine = '31105';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de campo agrícolas tradicionales vinculadas al agroturismo de la Vega del Ebro, pequeños hoteles boutique de interior en el casco histórico. | Valle del Ebro y Ribera navarra. Rutas de senderismo plano por los senderos fluviales de los meandros del río Ebro, caminos que conectan con los regadíos e infraestructuras agrarias de sus famosas huertas tradicionales, cicloturismo familiar de llanura y base sur para expediciones a las Bardenas Reales. PROVINCIA: PONTEVEDRA (Texto Plano Limpio)') WHERE codigo_ine = '31232';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casonas de piedra mariñanas restauradas, hoteles rurales de costa orientados al turismo de relax marino, apartamentos rústicos con vistas a las marismas y alojamientos de agroturismo tradicional. | Ubicado plenamente en el complejo intermareal Umia-O Grove (sitio Ramsar de alta protección). Destaca por la espectacular ruta de senderismo costero de las Pedras Negras en San Vicente do Mar (pasarelas de madera sobre formaciones caprichosas de granito frente al Atlántico), observación ornitológica masiva de aves acuáticas, playas salvajes de dunas protegidas como Lanzada, y kayak de mar.') WHERE codigo_ine = '36009';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Colosales pazos gallegos señoriales con portalones heráldicos y hórreos gigantes, casas rectorales restauradas en valles fluviales de interior y granjas escuela de agroturismo ganadero. | En el interior de la comarca del Deza, rodeado de frondosos bosques gallegos autóctonos. Destaca por el Monumento Natural de la Fraga de Catasós (un bosque mágico con los castaños y robles de mayor altura de Europa central), rutas de senderismo fluvial a lo largo del río Asneiro, senderos micológicos otoñales extremos y senderos del Camino de Santiago de Invierno.') WHERE codigo_ine = '36024';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hoteles palacio históricos vinculados al termalismo señorial del siglo XIX, casas de turismo rural integradas en aldeas tradicionales de montaña y apartamentos rústicos junto al río Tea. | Cuenca del río Tea (Espacio Protegido de la Red Natura). Destaca por la Senda Fluvial del Río Tea (recorrido de senderismo plano bajo bosques de galería autóctonos tupidos de alisos e higueras), playas fluviales de interior de aguas medicinales y limpias, ascensiones de media montaña a los montes de la Paradanta y rutas cicloturistas.') WHERE codigo_ine = '36031';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Pazos de turismo rural vinculados a la viticultura heroica y bodegas solariegas, casas de piedra tradicionales integradas en el conjunto histórico y apartamentos litorales de ría. | Corazón de la Comarca del Salnés, bañado por la Ría de Arousa. Ofrece rutas que conectan senderos agrícolas entre interminables viñedos de uva albariño emparrados sobre granito, paseos llanos por las marismas del río Umia (ornitología de primer nivel de ánades y flamencos), y rutas ecuestres de costa.') WHERE codigo_ine = '36004';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Parador nacional emplazado en la imponente fortaleza amurallada de Monterreal sobre el mar, casonas rurales de costa y apartamentos rústicos en parroquias interiores. | Ría de Vigo meridional y faldas de la Sierra de la Groba. Ofrece rutas de senderismo de media montaña que exploran la Sierra de la Groba (donde pastan manadas de caballos salvajes Garranos en libertad), miradores hacia las Islas Cíes, senderos fluviales del río Fraga con molinos hidráulicos antiguos restaurados y paseos litorales.') WHERE codigo_ine = '36002';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Alojamientos rurales unifamiliares dentro del casco histórico fortificado de granito, antiguos conventos y rectorales adaptadas, y casas de turismo rural a orillas del río Miño. | Custodia la entrada al Parque Natural del Monte Aloia (la montaña mítica gallega). Espectaculares rutas de senderismo de montaña y botánicas entre masas arbóreas maduras con miradores que divisan todo el estuario del río Miño y Portugal, tramos iniciales gallegos del Camino de Santiago Portugués y rutas fluviales en kayak.') WHERE codigo_ine = '36014';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de campo agrícolas y de dehesa bajas de sillería de granito independientes de interior, antiguos palacetes hortícolas con encanto rústico. | Cuenca baja de la ribera del río Miño fronterizo. Rutas de senderismo plano fluviales que siguen el curso del río, senderos que suben hacia el espectacular mirador del Monte Goián con defensas históricas enterradas en el bosque, senderos de viveros botánicos y kayak fluvial.') WHERE codigo_ine = '36054';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Complejos de turismo de interior integrados en antiguas moles molineras, casas rurales tradicionales con parcelas amplias y viñedos. | Valle del Salnés de interior. Sede de la espectacular ruta de senderismo de la Ruta de la Piedra y del Agua (Senda da Pedra e da Auga, un recorrido bajo túneles vegetales umbríos jalonado por decenas de molinos de agua de granito tradicionales restaurados que sube al Monasterio de Armenteira), y cicloturismo de montaña.') WHERE codigo_ine = '36028';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de labranza tradicionales de piedra con fincas ganaderas, apartamentos rurales rústicos con chimeneas de leña ideales para familias. | Comarca del Deza interior. Rutas de senderismo que conectan con el Monasterio románico de San Lorenzo de Carboeiro (enclavado de forma espectacular en un meandro cerrado del río Deza rodeado de bosque autóctono cerrado), caminatas hacia las cascadas fluviales y senderos micológicos.') WHERE codigo_ine = '36052';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Cortijos alpujarreños independientes construidos con piedra y vigas de castaño, complejos rústicos con piscina rodeados de olivares milenarios, y alojamientos eco-sostenibles de interior. | Capital y puerta natural de la Alpujarra, a los pies de Sierra Nevada y la Sierra de Lújar. Destaca por el sendero GR-7, rutas de senderismo fluvial a lo largo del cauce del río Guadalfeo, rutas cicloturistas de montaña (BTT), paseos botánicos entre plantaciones de cítricos y olivos de montaña, y senderos micológicos en las umbrías.') WHERE codigo_ine = '18147';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas cueva excavadas directamente en la arcilla (alojamientos bioclimáticos subterráneos tradicionales con chimeneas encaladas exteriores), palacetes señoriales andaluces rústicos en el casco histórico y cortijos agrícolas aislados en la hoya. | Integrado en el Geoparque de Granada (UNESCO). Ofrece una experiencia única de turismo rural en un paisaje de \"badlands\" o cárcavas arcillosas de aspecto lunar. Rutas de senderismo geológico por los cañones del desierto de Gorafe, cicloturismo por pistas arcillosas, rutas fotográficas al atardecer en el mirador del Fin del Mundo y cercanía al Parque Natural de la Sierra de Baza.') WHERE codigo_ine = '18089';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hoteles de alta montaña de estilo alpujarreño, grandes casonas de piedra de alquiler íntegro con chimeneas tradicionales de leña y hostales para montañeros. | El municipio más alto del Barranco de Poqueira, dentro del Parque Nacional de Sierra Nevada. Punto de partida logístico principal para la ascensión a pie a las cumbres del Mulhacén (techo de la península ibérica con 3.479 metros) y el Veleta. Senderismo de alta dificultad por las lagunas glaciares de Sierra Nevada, rutas ecuestres alpinas y avistamiento de cabra montés.') WHERE codigo_ine = '18042';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de campo tradicionales granadinas con huerto, hoteles de montaña rústicos y alojamientos de esquí en los núcleos altos de su término municipal. | Estribaciones occidentales de Sierra Nevada. Sede de una de las rutas de senderismo de aventura más espectaculares y transitadas de Andalucía: Los Cahorros del Río Monachil (desfiladero calizo angosto transitable mediante colosales puentes colgantes, cascadas y pasos de roca estrechos). Escalada deportiva vertical en caliza, senderos de robledales y cicloturismo de carretera exigente.') WHERE codigo_ine = '18134';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Posadas y hoteles rurales vinculados al termalismo histórico y medicinal, casas de pueblo tradicionales andaluzas con fuentes de agua fresca en sus patios rústicos y apartamentos de montaña. | Puerta occidental de la Alpujarra alta y Parque Natural de Sierra Nevada. Destaca por la ruta senderista del Sendero de los Pescadores, caminatas fluviales junto al río Lanjarón, paseos botánicos por el Parque del Salado y el Bosque de Tello (repleto de castaños e hilos de agua de deshielo), rutas micológicas y senderos ecuestres.') WHERE codigo_ine = '18116';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hoteles palacio rurales barrocos, casas de turismo rural cimentadas sobre el acantilado y alojamientos rústicos vinculados a sus baños árabes termales históricos. | Entorno de la Sierra de Tejeda y Almijara. Sede de la espectacular ruta senderista de los Tajos de Alhama (un colosal cañón calizo con paredes verticales de más de 50 metros esculpidas por el río Alhama justo a los pies del pueblo). Caminatas de interpretación botánica por el desfiladero, senderos que bordean el Pantano de los Bermejales (kayak, piragüismo) y paseos ornitológicos.') WHERE codigo_ine = '19001';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casonas tradicionales alpujarreñas de mampostería gruesa y launa adaptadas con porches de madera, apartamentos rústicos de alta montaña con chimeneas de leña ideales para el invierno. | Municipio célebre por situarse a 1.476 metros de altitud en pleno Parque Nacional de Sierra Nevada. Destaca por las rutas de senderismo de alta montaña que ascienden a la mítica Siete Lagunas (valle de origen glaciar espectacular), senderos fluviales por el curso alto del río Trevélez (pesca truchera limpia), turismo gastronómico-rural vinculado al curado del jamón de Trevélez y avistamiento de fauna de cumbre.') WHERE codigo_ine = '18180';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Cabañas de madera forestales rústicas, apartamentos de montaña independientes rodeados de castañares viejos y complejos de ecoturismo rural junto al río Genil. | Vertiente norte de Sierra Nevada alta, cabecera del río Genil. Destaca por la famosa ruta senderista del Tranvía de la Sierra (itinerario plano que aprovecha el antiguo trazado ferroviario minero cruzando túneles en la roca y puentes sobre el río), acceso norte al sendero alpino Vereda de la Estrella bajo las caras norte de los tres miles, senderos de castaños milenarios y micología.') WHERE codigo_ine = '18094';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales andaluzas de cal blanca de alquiler íntegro integradas a las faldas de la peña, apartamentos rústicos pequeños de montaña. | Custodia el Parque Natural de la Sierra de Castril. Sede de la célebre ruta de senderismo de las Pasarelas del Río Castril (un espectacular sendero de pasarelas de madera ancladas sobre la pared de roca caliza del desfiladero fluvial). Caminatas exigentes hacia el nacimiento del río Castril, exploración de cuevas kársticas como la cueva del Doncel, y avistamiento de buitres leonados y quebrantahuesos.') WHERE codigo_ine = '18046';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Cortijos andaluces señoriales con amplias fincas arboladas rústicas, casas cueva turísticas rehabilitadas en sus pedanías y hostales de campo de interior. | Entrada al Parque Natural de la Sierra de Baza. Ofrece rutas de senderismo de montaña por los prados altos y pinares béticos de la sierra, caminatas hacia el pico Santa Bárbara (2.269 metros), senderos botánicos entre pinos carrascos y encinares centenarios, rutas de micología forestal de otoño y dehesas de ganado extensivo.') WHERE codigo_ine = '18023';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Complejos trogloditas turísticos (barrios de casas cueva tradicionales excavadas en badlands con calados subterráneos rústicos). | Geoparque de Granada. Destaca por las rutas de senderismo geológico e interpretativo que recorren el paisaje arcilloso rojizo de las cárcavas, caminatas hacia los yacimientos arqueológicos de dehesas prehistóricas, rutas cicloturistas llanas de desierto y paseos fotográficos por formaciones de erosión.') WHERE codigo_ine = '18167';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales de piedra tradicionales calizas del prepirineo penibético, apartamentos rústicos pequeños en valles de pinos resineros. | Vertiente norte del Parque Natural de las Sierras de Tejeda, Almijara y Alhama. Rutas de senderismo forestal por el sendero del río Bacal, caminatas de media montaña que exploran densos pinares de repoblación viejos, senderos micológicos de otoño (recogida de níscalos) y rutas cicloturistas de montaña (BTT).') WHERE codigo_ine = '18107';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Palacetes rurales renacentistas con portadas de piedra de sillería dorada, casas de turismo rural cueva independientes y fincas agrícolas de agroturismo ganadero. | Extremo norte de la provincia, comarca de Huéscar. Destaca por el paraje natural de los Rodríguez (bosque con ejemplares monumentales de Secuoyas Gigantes plantadas en el siglo XIX). Rutas de senderismo que ascienden a la imponente mole caliza de la Sierra de la Sagra (2.383 metros, el pico más alto del altiplano), y senderos de pastores de cordero segureño.') WHERE codigo_ine = '18098';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de pueblo tradicionales alpujarreñas de mampostería estrecha, apartamentos rurales acogedores con chimenea para familias y senderistas. | Alpujarra Oriental, Parque Natural de Sierra Nevada bajo. Ofrece la ruta de senderismo del Sendero del agua y de la seda, caminatas por los antiguos caminos medievales de herradura que cruzan castañares y dehesas de secano, paseos fluviales por el río Válor y rutas micológicas en bosques de encinas viejas.') WHERE codigo_ine = '19028';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Alojamientos rurales unifamiliares con muros anchos de piedra oscura de pizarra, apartamentos de montaña de la cara norte de Sierra Nevada. | Marquesado de Zenete, cara norte alpina. Famoso por albergar la Ruta Solidaria del Avión (itinerario de senderismo de media-alta montaña que asciende hasta los restos de un avión militar norteamericano estrellado en los años 60 en la sierra). Senderos forestales entre pinos silvestres, castaños y antiguas explotaciones mineras de hierro romanas.') WHERE codigo_ine = '18108';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hoteles de alta montaña construidos con sillería caliza y madera de roble, apartamentos rústicos con vistas a los macizos calcáreos y cabañas tradicionales de montaña. Cuenta con la mayor concentración de hórreos leoneses de tipo leonés y asturiano de la provincia. | En el corazón del Parque Nacional de los Picos de Europa (Vertiente Leonesa). Punto de partida oficial para la exigente y mítica vertiente leonesa de la Ruta del Cares. Destaca por el senderismo al Mirador del Tombo, ascensiones alpinas a las cumbres del Macizo Occidental (Torre de Santa María), paseos por el hayedo de Asotín y raquetas de nieve invernales.') WHERE codigo_ine = '24116';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Palacetes rurales barrocos e históricos vinculados a la nobleza berciana, hostales señoriales de paso para peregrinos del Camino de Santiago y casas de labranza entre viñedos de uva mencía. | Hito principal del Camino de Santiago Francés en León. Confluencia de los ríos Burbia y Valcarce. Ofrece rutas de senderismo fluvial, caminatas que ascienden hacia los sotos de castaños milenarios de Corullón, cicloturismo de carretera sin tráfico y paseos arqueológicos hacia el Castro celta de la Ventosa.') WHERE codigo_ine = '24209';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hoteles de montaña con amplias cristaleras y vistas al lago de interior, apartamentos rústicos optimizados para montañeros y escaladores, y albergues fluviales. | Parque Regional de la Montaña de Riaño y Mampodre. Famoso por sus paisajes calcáreos que emulan los fiordos noruegos. Rutas de senderismo alpino de ascensión al Pico Gilbo (el Cervino leonés) y al Yordas, paseos náuticos y rutas de kayak en el Embalse de Riaño, avistamiento guiado de fauna ibérica salvaje (lobo ibérico, cabra montés, ciervos) y rutas de raquetas de nieve.') WHERE codigo_ine = '24130';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hostales de alta montaña y apartamentos rústicos orientados al turismo de nieve e invernal, casas rurales de piedra y madera de pinar. | Parque Regional de la Montaña de Riaño, falda de la estación invernal de San Isidro. Destaca por el Monumento Natural de la Pinar de Lillo (uno de los pocos bosques relictos autóctonos de pino silvestre de la cordillera). Rutas de senderismo hacia el Lago Ausente, senderos micológicos en temporada de otoño y esquí alpino.') WHERE codigo_ine = '24121';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales integradas en antiguas colonias e instalaciones mineras industriales del siglo XIX rehabilitadas, apartamentos rústicos para turismo activo. | Valle del río Esla medio. El mayor hub de turismo activo y aguas bravas de la provincia; destaca por el Canal de Aguas Bravas de Sabero (sede de campeonatos de kayak y rafting). Rutas de senderismo por la Senda de las Minas, caminatas exigentes hacia las cumbres calizas de la Peña de la Valdoré, vías ferratas verticales y escalada deportiva en roca.') WHERE codigo_ine = '24137';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Confortables casonas de piedra con corredores tradicionales bercianos, albergues con encanto y apartamentos rurales de paso jacobeo. | Entrada al Bierzo desde los Montes de León, bañado por el río Meruelo. Ofrece el Camino de Santiago Francés. Destaca por su monumental playa fluvial natural integrada en el puente romano del pueblo ideal para el baño en verano, rutas de senderismo hacia las Fragas del río Meruelo bajo bosques de castaños y robles, y rutas cicloturistas.') WHERE codigo_ine = '24100';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales de piedra de mampostería tradicional serrana leonesa, apartamentos rústicos pequeños orientados al turismo activo de montaña. | Custodia el Monumento Natural de las Hoces de Vegacervera. Espectaculares rutas de senderismo vertical que transitan entre paredes calizas verticales de más de 100 metros esculpidas por el río Torío, caminatas que ascienden a los altos de las muelas calcáreas, escalada clásica en roca caliza de primer nivel, pesca y rutas micológicas.') WHERE codigo_ine = '24194';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de campo agrícolas tradicionales bajas independientes de la ribera del río Esla, pequeños hoteles de interior de paso en el casco fortificado de adobe. | Llanura y ribera del río Esla bajo, Camino de Santiago Francés. Rutas de senderismo plano por los senderos fluviales de las dehesas del Esla, caminatas agrícolas llanas ideales para cicloturismo familiar de relax por las cañadas reales de la meseta leonesa, pesca fluvial y ornitología en tablas de agua. PROVINCIA: GIRONA (Texto Plano Limpio)') WHERE codigo_ine = '26011';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hoteles de montaña de estética alpina, chalets rústicos de piedra y madera, y casas de turismo rural de alquiler íntegro con chimenea en valles verdes. | Eje principal del Valle de Camprodon en el Pirineo Oriental. Punto de partida para el senderismo de alta montaña y alpinismo (ascensión al pico Costabona), rutas botánicas entre frondosos robledales, rutas de raquetas de nieve e invernales en la estación de Vallter 2000, y senderos micológicos de Pirineo.') WHERE codigo_ine = '18004';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Auténticas casas de payés vinculadas al agroturismo tradicional, alojamientos rurales familiares con huerto ecológico y granjas rodeadas de campos volcánicos. | En el corazón del Parque Natural de la Zona Volcánica de la Garrotxa. Sede de rutas senderistas directas al Volcán de Santa Margarida (con su ermita en el centro del cráter) y al Volcán del Croscat. Ofrece paseos icónicos en carruaje por el hayedo de la Fageda d''en Jordà (crecido de forma única sobre una colada de lava) y micología.') WHERE codigo_ine = '17184';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hoteles boutique de ambientación medieval integrados en el casco histórico de piedra, posadas con encanto de cara al río Fluvià y masías aisladas. | Entrada oriental a la comarca de La Garrotxa. Ofrece rutas de senderismo fluvial a lo largo del cauce del río Fluvià, caminos tradicionales de herradura que conectan con dehesas y colinas boscosas, y paseos de interpretación botánica y patrimonial románica.') WHERE codigo_ine = '18002';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hoteles boutique rurales en antiguas casas de indios coloniales, apartamentos rústicos de costa y masías de piedra reformadas rodeadas de pinos. | Combinación de turismo costero, forestal y rural en el Macizo de Begur. Sede de los senderos litorales de los Caminos de Ronda (Camins de Ronda), caminatas que cruzan densos bosques de pinos piñoneros piñoneros que mueren en calas salvajes (Sa Riera, Aiguablava), snorkel y kayak de mar en la reserva marina de Ses Negres.') WHERE codigo_ine = '18001';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hostales tradicionales de alta montaña de piedra vista y madera caliza, casas rústicas de alquiler íntegro con grandes chimeneas. | Pueblo pirenaico de alta montaña. Destaca por la exigente ruta de senderismo hacia el nacimiento del río Ter en el circo glaciar de Ulldeter, caminatas alpinas fronterizas con Francia, turismo de nieve invernal y recolección micológica extrema en bosques de pino negro.') WHERE codigo_ine = '18015';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de pescadores encaladas rehabilitadas como hoteles con encanto mediterráneo, y masías rústicas aisladas en campos de olivos. | En el interior del Parque Natural del Cap de Creus. Rutas de senderismo indómito entre acantilados de pizarra negra esculpidos por el viento de Tramontana, caminos de piedra seca tradicionales que conducen al Faro de Cap de Creus, observación de geología pura y kayak de mar en calas rocosas vírgenes.') WHERE codigo_ine = '17032';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Grandes masías señoriales solariegas de agroturismo en la periferia, y hoteles de naturaleza de interior con certificación eco-sostenible. | Capital de La Garrotxa rodeada por cuatro volcanes extintos. Ofrece el inicio de las Vías Verdes cicloturistas (Ruta del Carrilet), paseos de interpretación ecológica por los humedales boscosos de la Moixina, rutas botánicas por el Volcán Montsacopa y senderos micológicos.') WHERE codigo_ine = '17114';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales integradas en un casco histórico gótico medieval de piedra dorada intacto, posadas agrícolas de campiña. | Comarca del Baix Empordà. Rutas de senderismo plano y cicloturismo familiar a lo largo de las dehesas agrícolas de los arrozales de Pals, paseos botánicos por las dunas protegidas y pinares de la playa de Pals, y ornitología en los humedales linderos del río Ter.') WHERE codigo_ine = '17124';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hoteles de montaña rústicos de piedra y madera, casas de pueblo tradicional andaluz con chimeneas de leña encaladas y complejos de turismo activo a las faldas del castillo de la Yedra. | Puerta natural del Parque Natural de las Sierras de Cazorla, Segura y Las Villas. Destaca por el sendero circular del río Cerezuelo, la proximidad al Nacimiento del Río Guadalquivir en la Cañada de las Fuentes, senderismo de alta montaña en el entorno del Gilillo y rutas de avistamiento de grandes ungulados y aves rapaces.') WHERE codigo_ine = '23028';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de turismo rural intramuros enclavadas en un casco histórico medieval empinado intacto, apartamentos rústicos con vistas panorámicas al mar de olivos y cabañas de alta montaña. | Municipio enriscado a más de 1.100 metros de altitud en la Sierra de Segura profunda. Destaca por las rutas de senderismo hacia el Yelmo (epicentro nacional del vuelo libre en parapente), paseos micológicos en los frondosos pinares laricios de alta montaña, senderos ecuestres e interpretación de la fauna silvestre.') WHERE codigo_ine = '23081';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hoteles rurales con encanto rústico colgados de los riscos calizos, chalets de montaña independientes con piscina y alojamientos integrados en las pedanías del corazón del Parque (como Arroyo Frío o Burunchel). | Custodia los espectaculares cortados donde se asienta su fotogénico castillo templario. Sede de la gran ruta de senderismo de la Cerrada del Utrero (espectacular cañón calizo del río Guadalquivir joven con cascadas de toba), la ruta del río Borosa (desfiladero fluvial con pasarelas de madera y pozas turquesas como el Charco de la Cuna) y piragüismo en el embalse del Tranco.') WHERE codigo_ine = '23047';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Grandes cortijos ganaderos y agrícolas con encanto andaluz serrano, fincas de montería con picaderos de caballos y casas de campo independientes rodeadas de pinos piñoneros. | En el corazón del Parque Natural de la Sierra de Andújar. La meca internacional absoluta para el rastreo guiado y avistamiento fotográfico del Lince Ibérico en libertad. Ofrece la ruta senderista del Santuario de la Virgen de la Cabeza, paseos fluviales por las dehesas de encinas maduras del río Jándula y observación del águila imperial ibérica.') WHERE codigo_ine = '24005';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de labranza tradicionales de piedra de cantería con patios andaluces rústicos, palacetes de interior con encanto y apartamentos rurales de campiña alta. | Estribaciones de Sierra Morena, a las orillas del Embalse de Rumblar. Ofrece rutas de senderismo arqueológico hacia el yacimiento de la Edad del Bronce de Peñalosa, paseos llanos que rodean su imponente castillo omeya del siglo X (el más antiguo conservado de Europa), kayak de interior en el embalse, y observación del cielo negro Starlight.') WHERE codigo_ine = '24012';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de pastores de alta montaña de piedra gruesa con chimeneas rústicas de suelo, pequeños hostales de montaña aislados de la civilización y alojamientos de ecoturismo ganadero. | Altiplano y cañones de la Sierra de Segura alta, uno de los municipios más extensos y despoblados. Sede de la espectacular ruta senderista del Nacimiento del Río Segura (donde brota el agua a presión desde una colosal gruta kárstica inundada), senderismo hacia los campos de Hernán Perea (estepa alpina caliza única en el sur peninsular), y senderos pastoriles de trashumancia.') WHERE codigo_ine = '23904';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales andaluzas de cal blanca de alquiler íntegro vinculadas al agroturismo olivarero, apartamentos rústicos de montaña. | Vertiente sur de la Sierra de Cazorla. Custodia el Monumento Natural de la Cueva del Agua de Tíscar (colosal gruta caliza natural donde el río se desborda en cascadas interiores rugientes). Rutas de senderismo hacia el santuario de Tíscar, paseos botánicos entre olivares de sierra y dehesas mediterráneas viejas de encina.') WHERE codigo_ine = '23073';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Apartamentos tradicionales de montaña con acabados en madera de pino, casas rurales familiares independientes junto a riachuelos trucheros limpias y cabañas de pinar. | Extremo norte de la Sierra de Segura, frontera con Albacete. Rutas de senderismo hacia el paraje de la Peña del Olivar, caminatas exigentes de ascensión a la Cambrón, senderos micológicos otoñales extremos bajo densos bosques de pino negral y paseos fluviales por el río Guadalimar joven.') WHERE codigo_ine = '23082';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales de pueblo tradicionales de interior, apartamentos rústicos acogedores para familias y grupos pequeños y alojamientos vinculados a huertos. | Piedemonte de la Sierra de Segura. Rutas de senderismo que siguen la Senda del río Beas bajo túneles vegetales umbríos de alisos, caminatas micológicas por las lomas linderas forestales, paseos fotográficos de olivares de campiña y cicloturismo de carretera sin tráfico.') WHERE codigo_ine = '24013';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Cabañas forestales integradas bajo encinares, hostales rurales especializados en turismo de paso e histórico y apartamentos rústicos de pinar. | Custodia el Parque Natural de Despeñaperros. Sede de las colosales formaciones geológicas de \"Los Órganos de Despeñaperros\" (paredes verticales de cuarcita espectaculares cortadas por la fractura de la falla). Rutas de senderismo hacia el barranco de la Valdeazores, senderos hacia las pinturas rupestres prehistóricas del Collado de los Jardines y avistamiento de ciervos.') WHERE codigo_ine = '23076';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de labranza tradicionales de campiña baja de mampostería estrecha, posadas con encanto rural andaluz e interior. | Falda norte de Sierra Mágina y vega del río Guadalquivir medio. Rutas de senderismo hacia el paraje natural de los espartales de Jódar, caminatas de interpretación etnográfica e histórica rodeando su torre de la Alhabia del siglo XIII, paseos fluviales por el río Jandulilla y senderos entre olivares de pendiente.') WHERE codigo_ine = '23053';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de campo agrícolas y de dehesa bajas de interior independientes, apartamentos rurales sencillos junto a zonas fluviales. | Entorno de la confluencia de los ríos Guadalén y Guarrizas, y rodeado por tres embalses (Guadalén, Giribaile y La Fernandina). Rutas de senderismo plano de ribera fluvial, dehesas agrarias donde pasta el ganado, paseos en piragua o kayak náutico de interior, pesca deportiva y observación ornitológica de aves acuáticas en tablas de agua. PROVINCIA: MÁLAGA (Texto Plano Limpio)') WHERE codigo_ine = '23094';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Cortijos andaluces señoriales rodeados de olivares y viñedos, hoteles rurales boutique en fincas de agroturismo y antiguas casas de piedra de la serranía rehabilitadas con chimenea de leña. | Centro logístico y natural de la Serranía de Ronda y nexo con la Sierra de las Nieves. Destaca por las rutas de senderismo que descienden al fondo del Tajo de Ronda siguiendo el río Guadalevín, vías ferratas verticales en las paredes del desfiladero, senderos que cruzan encinares maduros de la comarca y rutas enológicas en sus bodegas de interior.') WHERE codigo_ine = '29084';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales integradas en fincas de cítricos y olivos, complejos orientados al turismo activo y de escalada y apartamentos rústicos con vistas a los cañones fluviales. | Entorno del Paraje Natural Desfiladero de los Gaitanes. Co-propietario de la entrada al célebre sendero del Caminito del Rey (espectacular pasarela aérea de madera anclada a 100 metros de altura sobre las paredes verticales del cañón del río Guadalhorce). Destaca por el senderismo geológico, escalada deportiva de primer nivel en El Chorro y kayak en los embalses linderos de Guadalteba.') WHERE codigo_ine = '32025';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Haciendas agrícolas tradicionales andaluzas de gran porte, antiguos molinos de aceite reconvertidos en hoteles con encanto y casas de campo de llanura alta con amplios porches rústicos. | Custodia el espectacular Paraje Natural de El Torcal de Antequera (Patrimonio de la Humanidad por la UNESCO), uno de los paisajes kársticos de roca caliza más impresionantes y fotogénicos de Europa. Rutas senderistas señalizadas (Ruta Verde y Amarilla) entre callejones y figuras de piedra modeladas por la erosión, observación de cabra montés, avistamiento ornitológico de rapaces y rutas históricas hacia los Dólmenes prehistóricos de Antequera.') WHERE codigo_ine = '32002';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hoteles y posadas rurales vinculados al termalismo histórico de su balneario, casas tradicionales blancas de pueblo serrano con patios y apartamentos de montaña independientes. | Puerta de entrada oficial al Parque Nacional Sierra de las Nieves. Sede de rutas de senderismo alpino de alta exigencia que ascienden al pico Torrecilla (el techo del parque con 1.919 metros de altitud). Ofrece paseos botánicos únicos por los misteriosos bosques relictos de Pinsapos (abetos de la era glaciar), caminatas por el sendero de las Cascadas y rutas de observación de fauna de alta montaña.') WHERE codigo_ine = '29090';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de pueblo andalusí de cal impecable con azulejos y macetas de flores, pequeños apartamentos rurales de colina con vistas a la sierra y el mar mediterráneo lejano. | En el interior del Parque Natural de las Sierras de Tejeda, Almijara y Alhama. Sede de la espectacular ruta de senderismo del Río Chíllar (caminata fluvial que transita por el cauce del agua dentro de estrechos cañones calizos conocidos como \"Cahorros\"), senderos micológicos de pinar y quejigal alto en la Axarquía, y rutas ecuestres de montaña.') WHERE codigo_ine = '29053';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Complejos de cabañas forestales de madera, apartamentos rurales adaptados para familias y deportistas de aventura, y casas rurales aisladas junto a pinares. | Entorno de los Embalses del Guadalhorce y el Desfiladero de los Gaitanes. Nudo de acceso principal al recorrido del Caminito del Rey. Destaca por el senderismo botánico por la dehesa de Ardales, caminatas arqueológicas hacia la Cueva de Ardales (pinturas rupestres prehistóricas integradas en la naturaleza), piragüismo, vela y deportes náuticos sin motor en el embalse del Conde de Guadalhorce.') WHERE codigo_ine = '32004';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de labranza tradicionales serranas vinculadas al agroturismo de castaños y vides, posadas con chimeneas rústicas y apartamentos turísticos de alta montaña. | En pleno Parque Nacional Sierra de las Nieves. Destaca por albergar el mirador de Luis Ceballos. Rutas de senderismo bajo inmensos bosques de pinsapos y densos castañares que tiñen el paisaje en otoño, caminatas que conectan con los senderos que suben a la meseta caliza alta de Quejigales y observación astronómica de cielos negros certificados.') WHERE codigo_ine = '29100';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Villas rurales independientes colgadas de lomas escarpadas con piscinas, casas tradicionales de la Axarquía encaladas y hostales orientados al turismo de caminata internacional. | Parque Natural de las Sierras de Tejeda, Almijara y Alhama, en la Axarquía montañosa. Punto de partida principal para la exigente ascensión a pie al pico de La Maroma (techo de la provincia de Málaga con 2.066 metros de altitud). Senderos de interpretación geológica entre lapiaces calizos secos, rutas de cicloturismo de carretera de gran pendiente y turismo gastronómico-rural vinculado a sus viñedos de uva moscatel emparrados.') WHERE codigo_ine = '29045';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de campo de piedra y teja rodeadas de encinares maduros, apartamentos rurales unifamiliares con porche de leña y hostales de montaña. | Valle del río Guadiaro, enclavado entre el Parque Natural de Los Alcornocales y Grazalema. Destaca por las rutas de senderismo del Cañón de las Buitreras (un colosal y estrecho Monumento Natural fluvial con paredes verticales de roca donde anida una inmensa colonia de buitres leonados), senderos bajo densos alcornocales húmedos y paseos micológicos otoñales.') WHERE codigo_ine = '29046';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Eco-lodges de diseño sostenible integrados en la dehesa mediterránea, casas rurales unifamiliares tranquilas y pequeños hoteles con encanto rústico. | Vertiente sur de la Sierra de las Nieves (Sierra Blanca). Ofrece la ruta de senderismo del Sendero de Juanar, caminatas botánicas bajo frondosos alcornocales y olivares de montaña, paseos hacia el Refugio de Juanar, observación de fauna ibérica (cabra montés) y rutas cicloturistas de montaña (BTT).') WHERE codigo_ine = '29076';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Fincas ganaderas andaluzas con casas de labranza tradicionales encaladas, apartamentos rústicos a la sombra de su castillo enriscado y alojamientos con encanto. | Paraje Natural de Sierra Crestellina y transición al Campo de Gibraltar. Destaca por el sendero de los Arroyos, caminatas de observación ornitológica de grandes aves rapaces (colonia protegida de buitre leonado anidando frente a la costa del Mediterráneo), senderos geológicos en riscos calizos y baños de agua dulce mineromedicinal en los Baños de la Hedionda (baños romanos al aire libre).') WHERE codigo_ine = '29041';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Cortijos andaluces señoriales con amplias fincas olivareras, casas de labranza tradicionales de campiña alta con patios interiores de vigas y azulejos. | Comarca de Nororma, entorno de las lagunas de Archidona. Ofrece las rutas de senderismo que suben a la Ermita de la Virgen de Gracia (santuario rodeado de pinares de repoblación viejos y restos de murallas islámicas), paseos de observación ornitológica en la Reserva Natural de las Lagunas de Archidona, y senderos llanos de cicloturismo de campiña.') WHERE codigo_ine = '32003';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Apartamentos tradicionales de la serranía de Ronda con acabados en madera de castaño, casas rurales pequeñas e independientes junto a la estación de tren rural y cabañas de madera forestales. | Valle del río Guadiaro, Parque Natural de Grazalema bajo. Destaca por el Sendero del Guadiaro (itinerario de senderismo fluvial paralelo a la vía del ferrocarril que conecta con Benaoján), piragüismo fluvial, kayak y descenso de ríos en aguas limpias de montaña, y senderos micológicos de encinar húmedo.') WHERE codigo_ine = '29063';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de pueblo tradicionales serranas de mampostería estrecha, apartamentos rústicos acogedores para familias y espeleólogos cerca de las estaciones fluviales. | Serranía de Ronda kárstica. Custodia la imponente Cueva del Gato (Monumento Natural célebre por su colosal boca de roca de la que brota un río de agua helada y cristalina en forma de cascada y poza natural apta para el baño veraniego) y la Cueva de la Pileta (pinturas rupestres prehistóricas). Rutas senderistas de montaña y paseos fluviales por el Guadiaro.') WHERE codigo_ine = '29028';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casonas serranas heráldicas cuidadas con miradores que divisan el Estrecho de Gibraltar, casas de cal de pueblo andaluz independientes y apartamentos rurales de montaña. | Crestas de la Serranía de Ronda, bajo el castillo del Águila. Espectaculares rutas de senderismo que descienden hacia el cañón del río Genal, caminatas por densos alcornocales y dehesas de monte mediterráneo, vías ferratas de montaña de gran dificultad para escaladores y observación astronómica de cielos negros.') WHERE codigo_ine = '29056';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas tradicionales alpujarreñoserranas de mampostería gruesa y cal de aislamiento de montaña, apartamentos rurales pequeños integrados en un pueblo-museo. | En el corazón del indómito y frondoso Valle del Genal. El municipio destaca por fusionar el senderismo con el arte moderno al aire libre (esculturas contemporáneas integradas en los callejones e itinerarios de naturaleza del pueblo). Rutas por el sendero del río Genal cruzando pasarelas fluviales, caminatas bajo castañares centenarios y senderos micológicos.') WHERE codigo_ine = '29057';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de campo agrícolas y de dehesa bajas de interior independientes, apartamentos rurales sencillos en el llano de la cuenca. | Entorno de la Reserva Natural de las Lagunas de Campillos. Rutas de senderismo plano de alta observación ornitológica de aves acuáticas y palustres (flamencos, cigüeñuelas) en su complejo endorreico de lagunas estacionales, senderos llanos de cicloturismo familiar de relax por las cañadas reales de campiña alta, y cercanía al embalse de Guadalhorce. PROVINCIA: CÁCERES (Texto Plano Limpio)') WHERE codigo_ine = '29032';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Parador nacional en antiguo hospital medieval, hospederías reales de paso históricas, casas de turismo rural de arquitectura tradicional serrana con soportales de madera y piedra caliza. | En el corazón del Geoparque Villuercas-Ibores-Jara. Destaca por la ruta de senderismo del Desfiladero del Río Ruecas, la ascensión al pico de Las Villuercas (vistas de pájaro de las rañas geológicas), paseos botánicos por el Castañar de la Vizcaína con ejemplares centenarios protegidos y senderos micológicos de montaña.') WHERE codigo_ine = '10087';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Palacios rurales reconvertidos en hoteles boutique dentro del recinto amurallado, antiguas casas señoriales hidalgas y fincas de dehesa extremeña destinadas al agroturismo ganadero. | Entorno de la penillanura trucocacereña y transición a Monfragüe. Ofrece rutas de senderismo plano y cicloturismo por los Berrocales de Trujillo (espectacular paisaje de colosales bolas de granito), paseos de interpretación ambiental por encinares maduros donde se cría el cerdo ibérico, y observación de avifauna esteparia.') WHERE codigo_ine = '10195';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de pueblo tradicionales de dehesa de alquiler íntegro con chimeneas rústicas, apartamentos de turismo de interior y alojamientos ecoturísticos rurales de aislamiento. | En el interior del Parque Nacional de Monfragüe y Reserva de la Biosfera. La meca europea absoluta para el turismo ornitológico y observación fotográfica de aves rapaces calcícolas y forestales. Ofrece rutas de senderismo hacia el imponente Salto del Gitano (colosal farallón de roca cuarcita cortado sobre el río Tajo donde anida el buitre negro, águila imperial y cigüeña negra) y paseos fluviales por el Jaráiz.') WHERE codigo_ine = '10175';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Cortijos extremeños señoriales con amplias fincas arboladas rústicas, chozos tradicionales de pastores circulares de piedra adaptados para pernocta de lujo, y casas de campo independientes. | Sierra de San Pedro meridional, frontera con Portugal. Posee uno de los conjuntos megalíticos prehistóricos más importantes de Europa. Rutas de senderismo de la Senda de los Dólmenes (recorrido que visita decenas de dólmenes de granito bien conservados integrados en dehesas), caminatas por alcornocales maduros, senderos micológicos y observación de la berrea del ciervo.') WHERE codigo_ine = '10203';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de campo de penillanura independientes rústicas, antiguos alojamientos agrícolas bajos rehabilitados con patios extremeños de cal. | Custodia el Monumento Natural de Los Barruecos. Espectacular y singular paisaje granítico de grandes charcas de agua dulce rodeadas de colosales y caprichosas peñas de granito lisas erosionadas por el agua y el viento (famosas por albergar una de las mayores colonias de cigüeña blanca de Europa que anida sobre las rocas desnudas), rutas senderistas geológicas e interpretativas y paseos fotográficos.') WHERE codigo_ine = '10115';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de montaña enriscadas en una colina cónica escarpada con arquitectura tradicional de pizarra y mampostería, apartamentos rústicos de aislamiento. | Geoparque Villuercas-Ibores-Jara alto. Rutas de senderismo de ascensión vertical hacia las ruinas de su castillo medieval encaramado en una peña caliza (vistas espectaculares de los valles de fractura del sinclinal), observación ornitológica de buitres leonados y alimoches anidando en los cortados rocosos y senderos botánicos de quejigales.') WHERE codigo_ine = '10033';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de campo agrícolas y de dehesa bajas de interior independientes, apartamentos rurales sencillos junto al parque fluvial. | Extremo occidental de Cáceres, enclavado en la confluencia de los ríos Tajo y Sever dentro del Parque Natural Tajo Internacional. Rutas de senderismo plano de alta protección ecológica entre marismas de interior y riberas abruptas de río, paseos fluviales en barcos turísticos transfronterizos, cicloturismo de llanura por cañadas reales ganaderas y observación ornitológica de aves rapaces raras (águila perdicera). PROVINCIA: OURENSE (Texto Plano Limpio)') WHERE codigo_ine = '10062';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casonas solariegas de cantería integradas dentro de un casco histórico medieval fortificado intacto (Conjunto Histórico), hostales rústicos de montaña con chimeneas tradicionales y casas de alquiler íntegro. | Vertiente sur de la Ribeira Sacra alta, vigilado por su imponente fortaleza del siglo XIV. Destaca por las rutas de senderismo de los Bosques de Caldelas (itinerarios que transitan bajo sotos mágicos de castaños y robles autóctonos), paseos fluviales por el sendero del río Edo, senderos micológicos de primer nivel y punto de partida hacia los catamaranes que navegan las aguas interiores del Sil.') WHERE codigo_ine = '34003';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hoteles boutique rurales en antiguas fábricas de curtidos restauradas junto al cauce, casonas hidalgas gallegas con patios empedrados y apartamentos rústicos con encanto arquitectónico. | Bañado por el río Arnoia (Reserva de la Biosfera de las Áreas de Allariz). Sede del sendero fluvial del Arnoia, un bosque de galería impecable con molinos harineros y aceñas medievales de granito. Ofrece rutas de senderismo ecológico hacia el Eco-espacio de O Rexo (diseñado por Agustín Ibarrola fusionando arte y naturaleza en el campo), senderos tradicionales ganaderos y cicloturismo de baja dificultad.') WHERE codigo_ine = '34002';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Pazos de turismo rural vinculados a la viticultura tradicional de la Comarca del Ribeiro, casas de piedra en el casco histórico judío y fincas agrícolas con encanto. | Confluencia de los ríos Avia y Miño. Sede de rutas que conectan senderos agrícolas entre viñedos de uva treixadura cultivados en bancales escarpados de interior. Destaca por las Pozas termales de Prexigueiro (instalaciones termales rodeadas de densos bosques caducifolios), paseos ornitológicos en el embalse de Castrelo de Miño (piragüismo, kayak de interior) y caminatas fluviales. [1]') WHERE codigo_ine = '32069';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Parador de turismo de lujo emplazado de forma monumental en el Monasterio de Santo Estevo de Ribas de Sil, casas de aldea tradicionales y apartamentos turísticos rurales. | Ribeira Sacra noroccidental. Alberga el colosal desfiladero del río Sil. Rutas de senderismo que descienden a los embarcaderos fluviales cruzando bosques atlánticos cerrados de castaños, paseos hacia miradores colgados en la roca caliza como los de Vilouxe o Cabezoá, y rutas de interpretación de monumentos románicos integrados en plena naturaleza forestal.') WHERE codigo_ine = '32052';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hoteles de campo y posadas de turismo interior articulados en torno al patrimonio termal tradicional del Gran Balneario, casonas gallegas con amplios jardines históricos. | Valle del río Arenteiro. Destaca por las rutas de senderismo plano por el Parque Municipal (un colosal bosque botánico maduro a orillas del río de más de 30 hectáreas), paseos fluviales de ribera que visitan antiguas fábricas de papel de granito devoradas por la hiedra y la vegetación de ribera, y senderos micológicos. [1, 2]') WHERE codigo_ine = '34007';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Pallozas tradicionales gallegas rehabilitadas (viviendas de piedra con techumbre circular de paja de centeno), casonas de montaña construidas en mampostería gruesa de pizarra y albergues históricos de paso jacobeo. | Entrada oficial del Camino de Santiago Francés en Galicia, a más de 1.300 metros de altitud en la frontera natural con León. Destaca por el senderismo de alta montaña que conecta con la Sierra de los Ancares, caminatas de interpretación de la arquitectura tradicional pirenaico-gallega, senderos bajo bosques autóctonos de acebos y robles en la umbría, y rutas invernales con raquetas de nieve.') WHERE codigo_ine = '28009';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hoteles boutique rurales en espectaculares monasterios medievales y conventos rehabilitados, casas rurales vinculadas a la viticultura heroica y bodegas de interior, y pazos de granito con amplias fincas agrícolas de frutales. | Vertiente lucense de la Ribeira Sacra baja, confluencia de los ríos Miño, Sil y Cabe. Sede de rutas que conectan senderos entre viñedos escarpados cultivados en bancales verticales. Destaca por las rutas de senderismo que visitan el Monasterio de San Vicente de Pombeiro, cascadas naturales de montaña ocultas en la fronda (Fervenza de Augacaída) y paseos fluviales de ribera.') WHERE codigo_ine = '27041';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Palacetes de interior con fachadas monumentales y escudos heráldicos de piedra, posadas de turismo rural tradicionales vinculadas al Camino de Santiago del Norte y casonas de labranza en las parroquias rurales de su término municipal. | Valle del río Masma, a las faldas de la Sierra de la Toxiza. Ofrece rutas de senderismo kárstico e histórico hacia la espectacular Cova del Rei Cintolo (la cueva más grande de Galicia con galerías de estalactitas y río subterráneo activo, transitable con visitas guiadas de aventura), caminatas botánicas bajo bosques de robles en el paraje de Os Remedios, senderos fluviales y cicloturismo de carretera.') WHERE codigo_ine = '27030';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Pazos de turismo rural de sillería de granito con hórreos tradicionales, casas de labranza bajas vinculadas al agroturismo vinícola de interior y apartamentos rústicos con vistas directas al cañón fluvial. | Orilla occidental del río Miño en la Ribeira Sacra lucense. Sede de una de las estampas de naturaleza e interior más fotogénicas de Galicia: el Cabo do Mundo (colosal meandro cerrado del río Miño rodeado de viñedos en terrazas empinadas). Rutas de senderismo fluvial por el río Asma, paseos botánicos por sotos de castaños centenarios y cicloturismo entre dehesas tradicionales gallegas.') WHERE codigo_ine = '27016';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de piedra tradicionales de mampostería oscura con cubiertas de pizarra, apartamentos rústicos de alta montaña con porche de leña e instalaciones unifamiliares en valles cerrados aislados. | Parque Natural y Reserva de la Biosfera de Os Ancares. Bañado por el río Navia alto. Ofrece rutas de senderismo exigentes de media-alta montaña que exploran bosques atlánticos cerrados y vírgenes de robles rebollos y abedules, caminatas que cruzan su imponente puente medieval de piedra sobre el río caudaloso, pesca truchera tradicional de río limpio y senderos micológicos de otoño.') WHERE codigo_ine = '27034';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de campo agrícolas tradicionales de sillería de granito independientes de interior de viñedo, pazos rurales boutique y pequeños apartamentos turísticos rurales con porche. | En el interior de la Ribeira Sacra lucense meridional, flanqueado por los cañones profundos del río Sil. Sede de rutas de senderismo vertical exigente que transitan hacia miradores colgados literalmente sobre el abismo de roca caliza y granito, como el mirador de Caxide o del Duque. Paseos en los catamaranes que navegan las aguas del cañón fluvial del Sil, caminatas agrícolas y enoturismo.') WHERE codigo_ine = '27059';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de turismo rural intramuros de mampostería medieval, hoteles boutique integrados en antiguos palacetes señoriales del Maestrazgo con vistas al castillo y masías aisladas en la periferia forestal. | Capital de la indómita comarca de Els Ports. Destaca por las rutas de senderismo que bordean sus kilométricas murallas medievales, paseos arqueológicos hacia las pinturas rupestres prehistóricas de Morella la Vella (Patrimonio de la Humanidad), exigentes circuitos de cicloturismo de montaña (BTT), senderos de micología en otoño y observación astronómica con cielos limpios certificados.') WHERE codigo_ine = '12080';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hoteles de interior y posadas rurales fuertemente vinculados al patrimonio termal tradicional de su balneario, apartamentos turísticos orientados al turismo activo y de aventura y casas de pueblo rústicas junto al cauce. | Cañón fluvial del Alto Mijares. Célebre a nivel europeo por la espectacular surgencia de agua termal de la Fuente de los Baños (una poza natural turquesa donde brota el agua a unos constantes 25 °C todo el año apta para el baño medicinal). Ofrece la espectacular ruta de senderismo de los Estrechos del Río Mijares (desfiladero angosto con paredes verticales de roca de más de 100 metros), escalada deportiva vertical en caliza de primer nivel mundial y kayak de aguas bravas.') WHERE codigo_ine = '12079';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de piedra tradicionales de montaña colgadas literalmente en terrazas sobre el risco, pequeños hostales de montaña con chimeneas de campana y viviendas rurales con espectaculares miradores al barranco. | Encaramado de forma inverosímil a una colosal muela de roca caliza a 1.195 metros de altitud. Ofrece rutas de senderismo geológico por los barrancos de la Mola d''Ares, caminatas hacia el Barranc dels Horts (un paraje natural sagrado con un bosque de robles y quejigos centenarios monumentales único en el levante peninsular), observación de grandes colonias de buitre leonado y cabra montés, y senderos micológicos.') WHERE codigo_ine = '11002';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casonas señoriales palaciegas de sillería reconvertidas en hoteles de campo, casas rurales de labranza tradicionales de vega con amplios patios interiores de azulejos y apartamentos rurales familiares. | Valle del río Palancia, encajonado de forma espectacular entre el Parque Natural de la Sierra de Espadán y la Sierra Calderona. Nudo de conexión central con la Vía Verde de Ojos Negros (la vía verde más larga de España, ideal para senderistas y cicloturistas). Ofrece la ruta del paraje natural del Manantial de la Esperanza, paseos fluviales por el cauce del Palancia, caminatas de interpretación botánica y turismo gastronómico-rural.') WHERE codigo_ine = '12104';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales de piedra medieval rehabilitada en un casco histórico galardonado, masías de agroturismo ganadero independientes en el altiplano y apartamentos rústicos con porche. | Comarca del Alt Maestrat montañoso. Ofrece paseos etnográficos de aislamiento absoluto, rutas de senderismo exigentes hacia el barranco del río Monleón, caminatas para ver el colosal \"Carrasca de Culla\" (una encina monumental milenaria protegida bajo cuya copa se cobijaban ejércitos), observación astronómica en su observatorio turístico del Astromestrat con cielos negros certificados, y micología.') WHERE codigo_ine = '12051';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Palacetes rurales burgueses del siglo XIX con espectaculares jardines y huertos tradicionales señoriales, apartamentos rústicos de ribera y casas de pueblo familiares. | Valle del río Palancia. Sede de una de las estampas de agua dulce más famosas del levante: el paraje de El Salto de la Novia (espectacular e imponente cascada natural de más de 60 metros de altura en caída libre sobre el río Palancia encajonada entre paredes calizas). Rutas de senderismo plano de ribera, caminatas botánicas que visitan el \"Olmo de Navajas\" (árbol monumental plantado en el siglo XVII), y cicloturismo por la Vía Verde de Ojos Negros.') WHERE codigo_ine = '12081';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de montaña de piedra caliza tradicionales con muros anchos aislantes, apartamentos rústicos en valles cerrados de frutales de montaña junto a arroyos trucheros limpios. | Alto Palancia, estribaciones de la Sierra de El Toro y Peña Santa María. Rutas de senderismo hacia el Nacimiento del Río Palancia (Los Cloticos), caminatas de interpretación botánica por dehesas de sabinas y pinos silvestres, senderos micológicos otoñales extremos (recogida de níscalos), ríos de montaña con piscinas naturales de aguas cristalinas ideales para el descanso veraniego y paseos arqueológicos hacia su acueducto romano protegido.') WHERE codigo_ine = '12022';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hoteles boutique rurales en conventos del siglo XVII rehabilitados, cortijos tradicionales andaluces rodeados de dehesas de encinas y casas de cal con teja árabe y chimeneas de leña a los pies de las ruinas de su castillo templario. | Capital y centro neurálgico del Parque Natural Sierra de Aracena y Picos de Aroche. Custodia la impresionante Gruta de las Maravillas (colosal cueva kárstica subterránea de estalactitas, estalagmitas y lagos interiores de agua turquesa cristalina en pleno casco urbano, transitable con visitas guiadas de aventura). Destaca por el sendero hacia Linares de la Sierra, paseos botánicos por el castañar alto, avistamiento ornitológico y micología extrema de otoño.') WHERE codigo_ine = '22004';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de turismo de aldea de piedra blanqueada andaluza, apartamentos rústicos con vigas de castaño e históricas posadas con patios empedrados y fuentes de agua viva. | En el interior de la sierra profunda húmeda, declarado Conjunto Histórico. Custodia el espectacular y místico paraje natural de la Peña de Arias Montano (colosal afloramiento de roca caliza rodeado de cuevas naturales y manantiales sagrados que domina todo el valle). Ofrece la ruta de senderismo circular Alájar-Linares de la Sierra a través de caminos tradicionales empedrados entre muros de piedra seca, paseos bajo densos alcornocales y quejigales, y micología.') WHERE codigo_ine = '22003';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales andaluzas de cal blanca de alquiler íntegro con grandes porches, apartamentos rústicos de montaña orientados al turismo activo y fincas de agroturismo ganadero destinadas a la cría tradicional del cerdo ibérico. | Sierra de Huelva occidental, vigilado de forma monumental por su imponente y fotogénico castillo medieval del siglo XIII intacto. Destaca por las rutas de senderismo de los Senderos del Chanza (itinerarios fluviales que siguen el curso joven del río), caminatas bajo sotos umbríos de castaños viejos, senderos micológicos otoñales de primer nivel (especializados en la seta del gurumelo) y dehesas ganaderas.') WHERE codigo_ine = '21025';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casonas de labranza tradicionales de sillería blanqueada y madera, hostales con encanto rústico junto a campos de frutales de montaña y fincas de agroturismo aisladas de la civilización. | En el corazón geográfico y más lluvioso de la sierra baja. Célebre por albergar la Fuente de los Doce Caños en pleno centro del pueblo, de donde brota un colosal manantial vivo de agua pura de deshielo del río Múrtigas. Ofrece la espectacular ruta de senderismo del Sendero de los Llanos (caminata plana bajo túneles vegetales umbríos de castaños y huertas antiguas), senderos forestales de alcornoques y quejigos, y rutas micológicas otoñales.') WHERE codigo_ine = '21033';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de pueblo tradicionales con fachadas de mampostería antigua y calles empedradas rústicas, apartamentos boutique rurales con encanto en el casco medieval y posadas rurales. | Faldas del cerro de San Cristóbal. Alberga la única mezquita rural del siglo X conservada casi intacta en España, erigida de forma espectacular sobre las ruinas de un castillo en plena cumbre boscosa. Ofrece la ruta de senderismo de ascensión al Pico de San Cristóbal (techo de la zona con miradores panorámicos), paseos botánicos por el sendero del arroyo de la Acebuche, caminatas de dehesa agraria y avistamiento de aves rapaces (colonia de buitre negro).') WHERE codigo_ine = '22001';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casonas señoriales andaluzas de gran porte convertidas en hoteles de campo, casas rurales de labranza tradicionales de vega con amplios patios interiores de cal y apartamentos rurales familiares. | Extremo occidental de la sierra alta, frontera con Portugal y bañado por el río Chanza. Ofrece las rutas de senderismo arqueológico e histórico hacia el yacimiento de la ciudad romana de Turóbriga y la ermita medieval de San Mamés (rodeada de dehesas vírgenes), caminatas geológicas interpretativas por los lapiaces calcáreos de los llanos de Aroche, senderos micológicos de encinar y cicloturismo de carretera sin tráfico.') WHERE codigo_ine = '22005';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de labranza tradicionales de la sierra alta con huertos integrados, apartamentos rústicos con chimeneas de piedra de suelo y alojamientos ecoturísticos rurales de aislamiento fluvial. | Valle del río Múrtigas, en una zona de humedad extrema. Sede de la espectacular y mítica ruta de senderismo del Ribera del Múrtigas (un recorrido plano bajo un bosque de galería atlántico denso y cerrado de alisos, sauces y chopos monumentales que emula el norte peninsular). Caminatas por sotos de castaños centenarios, paseos fotográficos de naturaleza interior y senderos ganaderos tradicionales de montaña.') WHERE codigo_ine = '21034';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Alojamientos rurales unifamiliares con portadas tradicionales adornadas con \"llanos\" (espectaculares alfombras de piedras empedradas artísticas bicolores en el suelo de entrada), apartamentos rústicos pequeños. | Enclavado en un valle cerrado profundo de colinas ganaderas. Ofrece paseos de aislamiento absoluto y silencio rural, rutas de senderismo plano de baja dificultad que recorren el Sendero de las Suertes, caminatas micológicas otoñales extremas en los bosques de encinas viejas de los alrededores y paseos fotográficos de interpretación etnográfica urbana.') WHERE codigo_ine = '21045';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de campo de penillanura independientes rústicas, antiguos alojamientos agrícolas de dehesa bajos rehabilitados y hostales de interior dedicados al agroturismo gastronómico. | La meca internacional absoluta de la cultura del cerdo ibérico de bellota y la dehesa madura. Ofrece rutas de senderismo de interpretación ambiental por sus interminables campos adehesados de encinas y alcornoques centenarios donde pasta el ganado porcino en libertad (Senda de la Dehesa de Jabugo), paseos fluviales por las riberas linderas del Múrtigas alto, senderos micológicos y observación de estrellas (cielos negros Starlight). PROVINCIA: LLEIDA (Texto Plano Limpio)') WHERE codigo_ine = '21043';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hoteles tradicionales de alta montaña construidos con sillería de piedra oscura y cubiertas de pizarra, apartamentos alpinos rústicos con chimeneas de leña y bordas pirenaicas restauradas para alquiler íntegro. | Puerta de entrada oriental principal al Parque Nacional de Aigüestortes y Estany de Sant Maurici. Sede de la mítica ruta senderista que asciende al fotogénico Estany de Sant Maurici vigilado por las colosales agujas de roca caliza de Els Encantats. Destaca por el senderismo de alta montaña (red de refugios Carros de Foc), el ascenso al pico Peguera, rutas invernales de esquí y raquetas de nieve, y avistamiento de fauna alpina (rebecos, urogallos).') WHERE codigo_ine = '25082';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de turismo rural (casas de payés) integradas en pequeñas aldeas tradicionales de montaña, hoteles boutique rurales a orillas del río y alojamientos de ecoturismo orientados a los deportes de aventura. | Capital del Pallars Sobirà, bañado por el río Noguera Pallaresa. La meca internacional absoluta del turismo activo de aguas bravas en España; destaca por la práctica de rafting, hidrospeed, descenso de cañones y kayak fluvial de nivel extremo. Ofrece rutas de senderismo hacia el Parque Natural del Alt Pirineu, caminatas por el Valle de Àssua siguiendo itinerarios pastoriles literarios y senderos micológicos en sus frondosos abetales y pinares de pino negro.') WHERE codigo_ine = '25209';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Antiguas masías fortificadas aisladas en el llano de la cuenca caliza, campamentos ecoturísticos rurales de diseño bioclimático y apartamentos para deportistas de aventura e investigadores del cielo. | Al pie de la Sierra del Montsec. Nudo de acceso principal al colosal y vertiginoso Congost de Montrebei (un impresionante y angosto desfiladero calizo transitable a pie mediante pasarelas excavadas en acantilados verticales de roca sobre el río Noguera Ribagorzana). Destaca por el kayak fluvial de cañón y piragüismo, rutas cicloturistas y es el epicentro nacional del astroturismo y la observación de estrellas al contar con el Parque Astronómico del Montsec (Reserva y Destino Turístico Starlight de máxima pureza).') WHERE codigo_ine = '27015';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hostales tradicionales pirenaicos de mampostería oscura de río a los pies de grandes farallones calcáreos, apartamentos rústicos pequeños optimizados para deportistas náuticos de río y casas rurales de montaña. | Confluencia del río Noguera Pallaresa y el río de Santa Magdalena. El mayor punto de embarque para el rafting y el descenso de ríos alpinos en la provincia. Ofrece espectaculares rutas de senderismo hacia el Valle de Cardós y la Coma de Burg dentro del Parque Natural del Alt Pirineu, caminatas fluviales entre sauces y chopos, senderos micológicos otoñales extremos y rutas de aislamiento geológico puro.') WHERE codigo_ine = '25126';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de campo tradicionales de sillería de piedra con amplias fincas ganaderas, apartamentos rurales rústicos con chimeneas de leña ideales para familias y pequeños hostales pirenaicos de interior. | Valle del río Noguera Pallaresa medio, falda de la estación invernal y de montaña de Port Ainé. Rutas de senderismo que conectan con los senderos que rodean el Parque Natural del Alt Pirineu occidental, caminatas por el fondo del valle boscoso, paseos llanos fluviales y cicloturismo, pesca deportiva truchera limpia en ríos vírgenes de montaña y deportes de nieve en invierno.') WHERE codigo_ine = '25183';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Posadas reales en impresionantes casonas pinariegas de sillería de piedra de los siglos XVI al XVIII, hoteles de montaña rústicos con acabados en madera de pino de Soria y casas de alquiler íntegro con chimeneas de granito. | En el corazón de la comarca de Pinares y a los pies del Parque Natural de la Laguna Negra y los Circos Glaciares de Urbión. Sede del acceso principal a la legendaria y fotogénica Laguna Negra de Urbión, un lago de origen glaciar encajonado entre colosales paredes verticales de roca y pinos silvestres. Ofrece rutas de senderismo de alta montaña que ascienden al Pico Urbión (nacimiento del río Duero), paseos botánicos por los pinares continuos más extensos de España, turismo micológico extremo (boletus) y deportes de nieve. [1, 2]') WHERE codigo_ine = '42215';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Grandes chalets rústicos de montaña independientes integrados bajo la sombra forestal, complejos de cabañas de madera pinariegas y apartamentos para montañeros y recolectores con cocinas integradas. | Flanqueado por la Sierra de Urbión y bañado por el curso más joven e indómito del río Duero. Destaca por sus puentes medievales de piedra perfectamente integrados en la naturaleza fluvial. Ofrece exigentes rutas de senderismo de alta montaña hacia los circos glaciares, la ruta de los Senderos del Duero joven entre saltos de agua y rocas musgosas, y es uno de los mayores centros nacionales de micología para la recolección regulada de níscalos y hongos boletus.') WHERE codigo_ine = '42069';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Palacetes rurales barrocos con portadas heráldicas de sillería dorada dentro de un casco histórico monumental amurallado, posadas con encanto de interior y casas de cal de dehesa. | Encaramado sobre un cerro estratégico que domina el Valle del Jalón. Ofrece rutas de senderismo histórico que rodean su monumental arco de triunfo romano de tres vanos, caminatas botánicas por los páramos calizos y dehesas de encinas y sabinas que lo circundan, cicloturismo de carretera sin tráfico y cercanía al nacimiento del río Jalón. [1]') WHERE codigo_ine = '42113';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Posadas reales castellanas integradas en palacios renacentistas y conventos restaurados, casas de turismo rural a la sombra de su colosal castillo fortificado y apartamentos rurales familiares. | Tierra de Frontera de la meseta del Duero. Destaca por albergar en su término la espectacular Ermita de San Baudelio de Berlanga (joya mozárabe aislada en pleno paisaje agrario árido y dehesa caliza). Ofrece rutas de senderismo fluvial por el río Escalote, caminatas hacia las dehesas de encinas centenarias del cañón del Duero meridional, observación astronómica nocturna y ornitología. [1]') WHERE codigo_ine = '42035';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales tradicionales pinariegas construidas con mampostería oscura y piedra arenisca, apartamentos rústicos de alta montaña con chimeneas de leña y albergues forestales. | El municipio situado a mayor altitud de la vertiente soriana de Urbión. Custodia el espectacular paraje natural de Castroviejo (un laberinto geológico de colosales rocas areniscas esculpidas de forma caprichosa por la erosión en mitad de un bosque cerrado). Rutas de senderismo que ascienden al Nacimiento del Río Duero y a la cascada de la Cueva de la Serra, vías ferratas de montaña de aventura y micología de boletus. [1]') WHERE codigo_ine = '42078';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de turismo rural puras que conservan la arquitectura popular medieval intacta de la provincia (muros de mampostería caliza, entramados de madera de enebro o sabina, barro y chimeneas cónicas de cesto tradicionales), posadas con encanto sobre el risco. | Conjunto Histórico colgado sobre un cerro calizo escarpado que mira al Valle de la Sangre. Custodia la Reserva Natural del Sabinar de Calatañazor (el bosque de Sabinas Albares más denso, maduro y mejor conservado del planeta, con ejemplares milenarios gigantescos de hasta 14 metros de altura). Ofrece la ruta de senderismo del cañón del río Milanos, caminatas geológicas interpretativas y observación ornitológica de rapaces de roca. [1]') WHERE codigo_ine = '42046';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales unifamiliares con porches de roca caliza en pequeños núcleos agrícolas puros aislados en valles de pinos y sabinas, apartamentos rústicos pequeños. | Entorno de pinares y sabinares del interior soriano central. Es el primer municipio de la provincia reconocido a nivel mundial como Destino Turístico y Cielo Starlight por la absoluta ausencia de contaminación lumínica y la máxima nitidez para la observación de estrellas en la naturaleza. Rutas de senderismo micológico otoñal, caminatas hacia el Manantial de la Fuentona cercano y senderos forestales llanos. [1]') WHERE codigo_ine = '42125';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas tradicionales sorianas rehabilitadas de mampostería de río y madera, apartamentos rurales pequeños para familias y espeleólogos cerca del cauce fluvial. | Custodia el Monumento Natural de La Fuentona de Muriel (conocido como el Ojo de Mar, una espectacular y colosal surgencia kárstica natural o pozo de agua dulce turquesa profunda y cristalina de la que nace el río Abión). Rutas senderistas señalizadas que transitan por la hoz caliza calcárea de la Fuentona bajo sabinas centenarias y nidos de buitres, paseos botánicos y cuevas kársticas con ríos subterráneos activos. PROVINCIA: ÁVILA (Texto Plano Limpio)') WHERE codigo_ine = '42124';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hostales de alta montaña especializados en montañeros, hoteles rurales premium construidos en piedra de granito y grandes ventanales de cristal, y cabañas alpinas independientes con chimenea de leña. | El principal centro logístico y de acceso al Parque Regional de la Sierra de Gredos. Custodia el punto de partida de la Plataforma de Gredos, de donde nace la mítica ruta senderista que asciende al Circo de Gredos y a la Laguna Grande bajo la silueta del Pico Almanzor (2.592 metros). Destaca por el avistamiento de la cabra montés de Gredos, rutas de raquetas de nieve, zonas de baño en las pozas del río Tormes y certificación astronómica Starlight.') WHERE codigo_ine = '05105';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hoteles de campo y fincas rústicas rodeadas de campos de frutales e higueras, casas de piedra de la vertiente sur con amplios porches y apartamentos de turismo activo a las faldas del castillo de Don Álvaro de Luna. | Capital de la vertiente sur de la Sierra de Gredos (el Valle del Tiétar). Custodia las impresionantes Cuevas del Águila (colosal formación geológica subterránea de estalactitas y estalagmitas gigantes iluminadas, transitable con visitas guiadas). Ofrece rutas de senderismo fluvial por las piscinas naturales del río Arenal, caminatas por densos castañares y dehesas mediterráneas, y ascensiones a los Galayos (meca de la escalada clásica en roca).') WHERE codigo_ine = '51001';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casonas solariegas de sillería de granito con corredores de madera, hoteles rurales de ribera junto al río Tormes, antiguas fábricas de luz reconvertidas en alojamientos rústicos y casas de labranza tradicionales. | Nudo estratégico occidental del Valle del Tormes y el Aravalle, a los pies de Gredos. Ofrece las rutas de senderismo fluvial del río Tormes cruzando su monumental puente románico, caminatas de media montaña que se adentran en el Valle del Jerte colindante, senderos micológicos de robledal, paseos a caballo y agroturismo enfocado en la cultura agrícola tradicional del judión del Barco.') WHERE codigo_ine = '51009';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Fincas de agroturismo de gran extensión con microclima mediterráneo, casas rurales de diseño exclusivo aisladas entre gargantas y pequeños apartamentos tradicionales de fachadas blancas de entramado de madera. | Vertiente sur extrema de Gredos, resguardada de los vientos del norte y abierta al Embalse de Rosarito. Destaca por la espectacular ruta de senderismo de la Garganta de Santa María con pozas naturales de agua cristalina aptas para el baño veraniego. Ofrece rutas arqueológicas hacia el Castro Celta de El Raso rodeado de robles, cicloturismo de carretera, y observación ornitológica de grullas y aves acuáticas en el embalse.') WHERE codigo_ine = '05047';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Alberga el primer Parador de Turismo histórico de España, hoteles forestales perfectamente mimetizados entre el pinar, casas de aldea tradicionales de cantería y chalets rústicos de montaña. | Cabecera alta del Valle del Tormes, a más de 1.500 metros de altitud. Destaca por albergar el Nacimiento del Río Tormes en el paraje de las Chorreras. Ofrece la ruta de senderismo del Pinar de Navarredonda (un inmenso bosque de pino silvestre autóctono), caminatas ecuestres de montaña alta, senderos micológicos otoñales y es un punto de referencia para el turismo de observación de estrellas en cielos oscuros certificados (Starlight).') WHERE codigo_ine = '05165';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales de campo independientes con amplias parcelas forestales, chalets de montaña tradicionales de piedra caliza y apartamentos rústicos de fin de semana adaptados para familias. | Cuenca del Alberche bajo, flanqueado por la Sierra de Guadarrama occidental. Custodia el espectacular e imponente Castañar de El Tiemblo (un bosque mágico con castaños milenarios gigantescos, como \"El Abuelo\", único en el Sistema Central). Ofrece rutas de senderismo hacia la Reserva Natural del Valle de Iruelas, paseos náuticos de interior (kayak, piragüismo, vela) en el Embalse de El Burguillo, y caminatas arqueológicas hacia los Toros de Guisando.') WHERE codigo_ine = '05241';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Posadas señoriales de estilo barroco francés en el casco monumental, casas rurales integradas en antiguas dependencias del Palacio de los Duques de Alba y apartamentos de turismo activo orientados a deportistas de aventura. | En el corazón del idílico Valle del Corneja. Capital mundial y referente absoluto de los deportes de vuelo libre (parapente y ala delta) gracias a las corrientes térmicas de su Puerto de Peña Negra. Ofrece rutas de senderismo de media montaña por la Sierra de Villafranca, caminatas llanas que siguen las riberas del río Corneja entre molinos harineros antiguos, y cicloturismo de carretera de gran pendiente.') WHERE codigo_ine = '05186';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Grandes complejos de casas rurales de alquiler íntegro con barbacoas y zonas recreativas a orillas del agua, apartamentos rústicos fluviales y casas de pueblo tradicionales. | En pleno Valle del río Alberche medio, rodeado de huertos de melocotoneros. Destaca por albergar un entramado de pozas y playas fluviales naturales de aguas cristalinas ideales para el baño y el descanso veraniego. Ofrece rutas de senderismo de media montaña que ascienden hacia la Sierra de la Paramera, senderos micológicos de robledal, caminatas agrícolas y rutas cicloturistas llanas.') WHERE codigo_ine = '05041';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de pueblo tradicionales andaluzas-extremeñas de cal blanca con balconadas de madera colgadas del risco (Conjunto Histórico), apartamentos rústicos pequeños con chimenea de piedra de suelo. | Enriscado en un anfiteatro natural espectacular bajo los colosales picachos calizos de Los Galayos. Sede de rutas de senderismo de alta montaña y escalada clásica, caminatas botánicas que recorren la Garganta de los Pelayos entre piscinas naturales de montaña limpia, senderos micológicos en sus frondosos pinares silvestres y avistamiento de aves rapaces de roca. PROVINCIA: SEGOVIA (Texto Plano Limpio)') WHERE codigo_ine = '05089';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hoteles rurales premium con instalaciones de spa, antiguas casonas señoriales castellanas de sillería dorada, posadas de piedra con grandes chimeneas tradicionales de leña y apartamentos rústicos de cara al abismo. | El principal centro logístico y de acceso al Parque Natural de las Hoces del Río Duratón. Sede del inicio de la espectacular ruta de senderismo de la Senda de los Dos Ríos, caminatas hacia la Ermita de San Frutos colgada sobre el abismo del cañón, y es la meca nacional para el piragüismo y rutas en kayak fluvial por las aguas calmadas del meandro. Destaca por el turismo de avistamiento ornitológico (la mayor colonia europea de buitre leonado en roca) y senderos micológicos.') WHERE codigo_ine = '40195';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Palacetes medievales y renacentistas de alquiler exclusivo dentro de una villa amurallada intacta (Conjunto Histórico), hospederías boutique reales con encanto rústico, patios empedrados de sillería y habitaciones con vigas de sabina centenarias. | Estribaciones septentrionales de la Sierra de Guadarrama. Ofrece rutas de senderismo histórico y natural que rodean sus kilométricas murallas calcáreas y su castillo del siglo XIII, caminatas de dehesa agraria entre robles y encinas centenarias donde pasta el ganado, senderos tradicionales ganaderos y cicloturismo de carretera de colinas suaves.') WHERE codigo_ine = '40156';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casonas porticadas tradicionales con solanas de madera que miran a la plaza elíptica, chalets de montaña independientes con chimenea de leña, y hoteles rurales de campo adaptados para familias y deportistas de nieve. | Piedemonte de la Sierra de Ayllón y nexo con la estación de esquí de La Pinilla. Custodia el espectacular Hayedo de la Pedrosa (uno de los hayedos más meridionales y protegidos de la península). Ofrece la ruta de las dehesas de robles melojos, caminatas botánicas otoñales de gran valor fotográfico, rutas de agroturismo hacia los célebres Pueblos Negros y Amarillos (como Madriguera o Alquite) integrados en su término, y micología de boletus.') WHERE codigo_ine = '40170';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Posadas reales de piedra y caliza integradas en palacios renacentistas con patios porticados rústicos, antiguas casas de labranza rehabilitadas con chimeneas de campana y apartamentos turísticos rurales. | Comarca de la Sierra de Ayllón oriental, bañado por el río Aguisejo. Ofrece paseos etnográficos e históricos que rodean su torre fortificada de \"La Martina\" del siglo XI en la cumbre, caminatas por el desfiladero calizo del río Aguisejo entre túneles de sauces y chopos, senderos geológicos en páramos áridos calizos, cicloturismo de carretera sin tráfico y rutas micológicas de otoño.') WHERE codigo_ine = '40024';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de turismo de interior colgadas literalmente sobre el risco medieval amurallado, posadas con encanto rústico con vistas panorámicas al agua y apartamentos rurales para amantes del silencio. | Custodia la entrada occidental al Parque Natural de las Hoces del Río Riaza y está bañado por el Embalse de Linares del Arroyo. Ofrece rutas de senderismo geológico y ornitológico bordeando el profundo desfiladero calizo (Refugio de Rapaces de Montejo), piragüismo, vela y deportes náuticos sin motor en el embalse, paseos botánicos por sabinares centenarios y observación astronómica de cielos negros.') WHERE codigo_ine = '40115';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de piedra de pastores de la sierra tradicionales rehabilitadas con muros anchos aislantes, apartamentos rústicos forestales e instalaciones ligadas al turismo micológico. | Falda norte de la Sierra de Guadarrama y Somosierra. Custodia la Cueva de los Enebralejos (colosal cueva de estalactitas con necrópolis prehistórica integrada, transitable con visitas guiadas) y el Acebal de Prádena (el bosque de acebos autóctono más grande e importante del Sistema Central). Rutas de senderismo botánico bajo los acebos mágicos repletos de frutos rojos en invierno, caminatas ganaderas y recolección micológica.') WHERE codigo_ine = '40162';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Complejos de cabañas de madera forestales mimetizadas bajo el pinar, apartamentos rústicos con porche de leña junto a arroyos trucheros y casas rurales de mampostería tradicional. | Valle del río Cega, falda del Puerto de Navafría. Alberga el espectacular paraje natural de El Chorro de Navafría (una imponente cascada natural de montaña de más de 20 metros de altura rodeada de inmensos pinos silvestres) y sus piscinas naturales fluviales de agua de deshielo ideales para el verano. Rutas de senderismo de alta montaña que ascienden al puerto, senderos micológicos extremos de níscalos y boletus en otoño, y esquí de fondo. PROVINCIA: GIRONA (Texto Plano Limpio)') WHERE codigo_ine = '40139';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hoteles de montaña de estética alpina, chalets rústicos de piedra y madera, y casas de turismo rural de alquiler íntegro con chimenea en valles verdes. | Eje principal del Valle de Camprodon en el Pirineo Oriental. Punto de partida para el senderismo de alta montaña y alpinismo (ascensión al pico Costabona), rutas botánicas entre frondosos robledales, rutas de raquetas de nieve e invernales en la estación de Vallter 2000, y senderos micológicos de Pirineo.') WHERE codigo_ine = '18004';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Auténticas casas de payés vinculadas al agroturismo tradicional, alojamientos rurales familiares con huerto ecológico y granjas rodeadas de campos volcánicos. | En el corazón del Parque Natural de la Zona Volcánica de la Garrotxa. Sede de rutas de senderistas directas al Volcán de Santa Margarida (con su ermita en el centro del cráter) y al Volcán del Croscat. Ofrece paseos icónicos en carruaje por el hayedo de la Fageda d''en Jordà (crecido de forma única sobre una colada de lava) y micología.') WHERE codigo_ine = '17184';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hoteles boutique de ambientación medieval integrados en el casco histórico de piedra, posadas con encanto de cara al río Fluvià y masías aisladas. | Entrada oriental a la comarca de La Garrotxa. Ofrece rutas de senderismo fluvial a lo largo del cauce del río Fluvià, caminos tradicionales de herradura que conectan con dehesas y colinas boscosas, y paseos de interpretación botánica y patrimonial románica.') WHERE codigo_ine = '18002';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hoteles boutique rurales en antiguas casas de indios coloniales, apartamentos rústicos de costa y masías de piedra reformadas rodeadas de pinos. | Combinación de turismo costero, forestal y rural en el Macizo de Begur. Sede de los senderos litorales de los Caminos de Ronda (Camins de Ronda), caminatas que cruzan densos bosques de pinos piñoneros que mueren en calas salvajes (Sa Riera, Aiguablava), snorkel y kayak de mar en la reserva marina de Ses Negres.') WHERE codigo_ine = '18001';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hostales tradicionales de alta montaña de piedra vista y madera caliza, casas rústicas de alquiler íntegro con grandes chimeneas. | Pueblo pirenaico de alta montaña. Destaca por la exigente ruta de senderismo hacia el nacimiento del río Ter en el circo glaciar de Ulldeter, caminatas alpinas fronterizas con Francia, turismo de nieve invernal y recolección micológica extrema en bosques de pino negro.') WHERE codigo_ine = '18015';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de pescadores encaladas rehabilitadas como hoteles con encanto mediterráneo, y masías rústicas aisladas en campos de olivos. | En el interior del Parque Natural del Cap de Creus. Rutas de senderismo indómito entre acantilados de pizarra negra esculpidos por el viento de Tramontana, caminos de piedra seca tradicionales que conducen al Faro de Cap de Creus, observación de geología pura y kayak de mar en calas rocosas vírgenes.') WHERE codigo_ine = '17032';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Grandes masías señoriales solariegas de agroturismo en la periferia, y hoteles de naturaleza de interior con certificación eco-sostenible. | Ciudad rodeada de cuatro volcanes extintos. Ofrece el inicio de las Vías Verdes cicloturistas (Ruta del Carrilet), paseos de interpretación ecológica por los humedales boscosos de la Moixina, rutas botánicas por el Volcán Montsacopa y senderos micológicos.') WHERE codigo_ine = '17114';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales integradas en un casco histórico gótico medieval de piedra dorada intacto, posadas agrícolas de campiña. | Comarca del Baix Empordà. Rutas de senderismo plano y cicloturismo familiar a lo largo de las dehesas agrícolas de los arrozales de Pals, paseos botánicos por las dunas protegidas y pinares de la playa de Pals, y ornitología en los humedales linderos del río Ter.') WHERE codigo_ine = '17124';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casonas de piedra tradicionales lebaniegas, hosterías de montaña con acabados en madera de roble y castaño, posadas rurales con chimenea y apartamentos rústicos. | Centro geográfico y nexo logístico del Valle de Liébana y del acceso oriental al Parque Nacional de los Picos de Europa. Destaca por el senderismo histórico del Camino Lebaniego hacia el Monasterio de Santo Toribio de Liébana, rutas micológicas, y proximidad directa al Teleférico de Fuente Dé (ascenso vertical al circo glaciar y la alta montaña alpina).') WHERE codigo_ine = '39055';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Posadas cántabras con balconadas de madera señoriales y escudos heráldicos, hoteles palacio barrocos e históricas casonas montañesas con corraladas de sillería. | Entorno litoral mixto y praderas verdes. Rutas de senderismo suave por los acantilados de Ubiarco, paseos cicloturistas costeros, senderos de interpretación botánica en el entorno rupestre de Altamira y rutas a caballo en dehesas rurales linderas.') WHERE codigo_ine = '39076';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Cabañas de madera forestales mimetizadas en la montaña, apartamentos alpinos rústicos para montañeros y hoteles de montaña con vistas a las cumbres calizas. | Alberga el circo glaciar de Fuente Dé dentro del Parque Nacional de los Picos de Europa. Rutas de senderismo de alta dificultad como la Canal de la Jenduda, el ascenso a los prados altos de Áliva, senderos bajo hayedos y robledales centenarios y rutas invernales con raquetas de nieve.') WHERE codigo_ine = '39015';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casonas montañesas de piedra tradicionales, palacetes agrícolas señoriales y posadas rurales integradas en valles de prados verdes siempre llanos. | Incluye gran parte del Parque Natural de Oyambre y el monte Corona. Destaca por el sendero forestal entre Secuoyas Gigantes del monte Cabezón (Monumento Natural), paseos fluviales por el estuario, rutas ornitológicas en marismas y senderos entre robledales antiguos.') WHERE codigo_ine = '39091';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Posadas de costa con encanto cántabro, apartamentos rurales con vistas a las marismas y la ría, y casas de aldea tradicionales mariñanas. | Corazón del Parque Natural de Oyambre. Ofrece tramos del Camino de Santiago del Norte, rutas de observación de aves acuáticas en las marismas de Rubín y Pombo, paseos por las dunas protegidas de Oyambre y Merón, y surf en playas salvajes rodeadas de acantilados.') WHERE codigo_ine = '39080';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Cabañas pasiegas auténticas rehabilitadas (antiguos establos de piedra caliza, vigas de roble y pradera vallada independiente), posadas rústicas del valle. | Comarca de los Valles Pasiegos. Ofrece un paisaje etnográfico único modelado por la ganadería tradicional. Rutas de senderismo de media montaña siguiendo el curso alto del río Pas, túneles ferroviarios abandonados de la Engaña integrados en la naturaleza y senderos micológicos.') WHERE codigo_ine = '39097';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Apartamentos rurales litorales, hoteles boutique rurales con encanto junto al mar y pequeñas villas rústicas con fincas verdes. | Parque Natural de las Marismas de Santoña, Victoria y Joyel. Es un punto clave del norte de España para el turismo ornitológico de aves acuáticas migratorias. Rutas por el sendero costero de la Punta del Brusco y acantilados vírgenes de caliza.') WHERE codigo_ine = '39047';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Posadas rurales protegidas, casonas montañesas con solanas orientadas al sur y casas integradas en conjuntos históricos tradicionales. | Reserva Nacional de Caza del Saja. Incluye la joya medieval de Bárcena Mayor. Rutas de senderismo por la Senda de los Senderos, caminatas fluviales junto al río Argoza, bosques de hayas primigenios y observación de fauna ibérica.') WHERE codigo_ine = '39014';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de piedra y madera para turismo activo, apartamentos de interior con vistas a colosales moles calizas y dehesas. | Valle del Asón. Capital de la espeleología y del turismo de aventura en Cantabria por su colosal subsuelo kárstico. Rutas de senderismo a cuevas con arte rupestre (Covalanas), vías ferratas de montaña con puentes colgantes y escalada deportiva vertical.') WHERE codigo_ine = '39057';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Cabañas rurales integradas en verdes laderas escarpadas, casonas señoriales del valle y posadas de montaña aisladas. | Alberga el Parque Natural de los Collados de Asón. Rutas senderistas espectaculares hacia el Nacimiento del Río Asón (colosal cascada en forma de cola de caballo de más de 70 metros brotando del risco), senderismo de alta montaña y exploración de grandes simas y lapiaces.') WHERE codigo_ine = '39083';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casonas de indianos singulares del modernismo, hoteles rurales burgueses con amplios jardines históricos y posadas de costa. | Costa occidental cántabra. Paseos por el Parque de la Estatua, rutas a pie hacia el monte Corona, senderos litorales que cruzan acantilados de caliza y la ría de la Rabia, hábitat protegido de aves palustres y acuáticas.') WHERE codigo_ine = '39024';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Posadas reales neoclásicas vinculadas al termalismo histórico de su balneario, casas rurales de piedra junto al río Miera. | Comarca de Trasmiera, falda de las \"Tetas de Liérganes\". Senderismo fluvial junto al río Miera, rutas botánicas, paseos ecológicos hacia el Balneario y caminatas de media montaña a picos calizos limítrofes.') WHERE codigo_ine = '39037';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Apartamentos rústicos de madera de castaño, casas rurales con porche integradas en dehesas y viñedos lebaniegos de colina. | Entrada norte al Valle de Liébana a través del espectacular Desfiladero de la Hermida. Senderismo por la canal de Urdón hacia el pueblo colgado de Tresviso, rutas cicloturistas de montaña y castañares centenarios protegidos.') WHERE codigo_ine = '39022';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Posadas de diseño surfero y ecológico, apartamentos rurales costeros rodeados de amplias praderas verdes siempre ganaderas. | Primera Reserva de Surf de España. Destaca por el espectacular sendero costero de los acantilados que conecta Loredo con Langre, rutas litorales a pie por las dunas del Puntal e islas protegidas de la Bahía de Santander.') WHERE codigo_ine = '39061';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Antiguas casas de labranza castellano-cántabras de sillería gruesa, posadas rurales de interior con chimenea y fragua rústica. | Sur de Cantabria (valles altos del río Camesa). Posee la mayor concentración de menhires prehistóricos del país. Rutas de senderismo de la Senda de los Menhires, senderos por formaciones kársticas y valles de llanura cerealista.') WHERE codigo_ine = '39092';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hoteles de montaña de piedra y madera, antiguas bordas ganaderas reconvertidas en viviendas turísticas rústicas y albergues pirenaicos. | Puerta de acceso principal al Parque Nacional de Ordesa y Monte Perdido (Patrimonio de la Humanidad). Destaca por la emblemática ruta de senderismo a la cascada de la Cola de Caballo, las Gradas de Soaso, las ascensiones de alta montaña, el barranquismo en el valle de Bujaruelo y las rutas de raquetas de nieve.') WHERE codigo_ine = '22230';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales de piedra medieval rehabilitada, hoteles boutique en el casco histórico amurallado y apartamentos rurales con huerto. | Confluencia de los ríos Cinca y Ara, en la Comarca del Sobrarbe. Sede mundial del ciclismo de montaña (Centro BTT Zona Zero). Ofrece rutas de senderismo hacia el Cañón de Añisclo, piragüismo y kayak en el Embalse de Mediano (con su famoso campanario sumergido) y senderos micológicos.') WHERE codigo_ine = '22907';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hoteles de montaña premium con instalaciones de spa alpino, refugios de alta montaña, apartamentos rústicos e históricos palacios aragoneses rehabilitados. | Corazón del Parque Natural de Posets-Maladeta. Punto de partida para la ascensión al Pico Aneto (techo de los Pirineos) y al Posets. Destaca por el senderismo al Forau de Aigualluts (espectacular sumidero kárstico), esquí de fondo en los Llanos de Hospital y escalada clásica.') WHERE codigo_ine = '22054';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Chalets de montaña independientes, apartamentos rústicos a pie de pista invernal y hoteles pirenaicos con chimenea. | Cabecera del Valle de Tena, bajo la imponente Peña Foratata. Rutas de senderismo de alta dificultad hacia los ibones (lagos glaciares) de Anayet y Respomuso, paseos náuticos en el Embalse de Lanuza, deportes de nieve en FormigalPanticosa y senderos transfronterizos.') WHERE codigo_ine = '22204';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Grandes hoteles balneario de montaña decimonónicos, apartamentos de turismo alpino y casas rurales tradicionales pirenaicas. | Entorno del Balneario de Panticosa a 1.630 metros de altitud. Destaca por la vertiginosa ruta de senderismo de las Pasarelas de Panticosa sobre el río Caldarés, excursiones de montaña hacia el Ibón de Baños, esquí alpino y escalada en vías ferratas calizas.') WHERE codigo_ine = '22170';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales de piedra maciza y pizarra, parador de turismo de montaña en el valle, y albergues para excursionistas. | Acceso directo al Valle de Pineta dentro del Parque Nacional de Ordesa. Ofrece las rutas de senderismo de ascensión al Balcón de Pineta y al Lago de Marboré, caminatas bajo cascadas espectaculares, senderos forestales alpinos y conexión a Francia mediante túnel.') WHERE codigo_ine = '22057';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales familiares integradas en el núcleo del pueblo, apartamentos rústicos con vistas fluviales y posadas pirenaicas. | Bañado por el río Ara (único gran río virgen sin presas del Pirineo). Ofrece la espectacular ruta de la Cascada de Sorrosal, su famosa vía ferrata vertical apta para escaladores, senderismo por el Valle de Ordesa meridional y rafting fluvial en aguas bravas.') WHERE codigo_ine = '22069';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casonas infanzonas de sillería convertidas en hoteles rurales, complejos de apartamentos rústicos con jardín y casas de pueblo de alquiler íntegro. | Nudo estratégico entre el Valle de Tena y el Serrablo. Rutas de senderismo hacia el recóndito Ermita de Santa Elena en un estrecho desfiladero, parques de aventura forestal en tirolinas, cicloturismo de carretera y senderos de interpretación botánica.') WHERE codigo_ine = '22059';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de turismo rural con una de las arquitecturas de piedra mejor conservadas del Pirineo, alojamientos con suelos de losa tradicional. | Parque Natural de los Valles Occidentales. Destaca por la ruta senderista del Valle de Zuriza, caminatas de alta montaña en el entorno kárstico de Linza, senderos botánicos entre abetales salvajes y territorio histórico de los últimos osos autóctonos.') WHERE codigo_ine = '22028';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hoteles rurales en las pedanías y pueblos rurales de su término, apartamentos de montaña tradicionales y pensiones para peregrinos. | Valle del Aragón y pie de monte del Pirineo. Camino de Santiago Aragonés. Ofrece senderismo de ascensión a la Peña Oroel (símbolo del valle), rutas geológicas integradas, cicloturismo de montaña por los antiguos caminos tradicionales y turismo de nieve cercano en Astún y Candanchú.') WHERE codigo_ine = '22130';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales de arquitectura tradicional serrana con muros gruesos de mampostería y vigas de roble, antiguos palacetes burgueses reconvertidos en hoteles boutique con encanto y apartamentos de montaña a las faldas de la sierra. | En el Alto Valle del río Oja, rodeado por las cumbres de la Sierra de la Demanda. Nudo logístico principal de montaña en la región. Destaca por las rutas de senderismo hacia el pico San Lorenzo (el techo de La Rioja con 2.271 metros), paseos botánicos por el hayedo de la dehesa de Ezcaray, cicloturismo por la Vía Verde del Oja, turismo de nieve invernal en la estación de Valdezcaray y micología extrema de boletus. [1, 2]') WHERE codigo_ine = '26061';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Alojamientos rurales integrados en antiguas edificaciones monacales o rectorales recuperadas con amplias huertas de frutales, hostales de montaña para senderistas y casas de pueblo tradicionales con grandes chimeneas de leña. | Valle del río Cárdenas, cuna del castellano y custodio de los Monasterios de Suso y Yuso (Patrimonio de la Humanidad por la UNESCO). Ofrece espectaculares rutas de senderismo de media y alta montaña que ascienden hacia los Montes Distercios, caminatas botánicas bajo frondosos hayedos y robledales del barranco de San Millán, senderos micológicos otoñales y dehesas de ganado extensivo.') WHERE codigo_ine = '26130';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hoteles de campo premium integrados en antiguos conventos del siglo XIV y palacios señoriales con espectaculares bodegas subterráneas (calados medievales), y casonas de turismo de interior vinculadas a la viticultura tradicional. | Capital del vino de la Rioja Alta, meandro del río Ebro y los Montes Obarenes. Ofrece rutas que conectan senderos agrícolas entre interminables mares de viñedos viejos, paseos cicloturistas llanos de gran recorrido siguiendo las dehesas del río Ebro, piragüismo y kayak fluvial de baja dificultad, y paseos fotográficos de interpretación del paisaje del viñedo. [1]') WHERE codigo_ine = '26071';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de piedra tradicionales del Cidacos de mampostería oscura y tejados de losa caliza, apartamentos rústicos pequeños con porche de leña e instalaciones unifamiliares en pequeños pueblos de montaña aislados de la civilización. | Alto Valle del río Cidacos, enclavado en una zona montañosa agreste. Posee una de las mayores y más espectaculares concentraciones de huellas de dinosaurio (icnitas) del mundo. Rutas de senderismo paleontológico y al aire libre que visitan decenas de yacimientos (como el yacimiento de la Virgen del Campo o de Valdecevillo) con reproducciones a escala real, caminatas geológicas por barrancos calizos y senderos micológicos. [1]') WHERE codigo_ine = '26058';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casonas de piedra de pastores de los Cameros tradicionales rehabilitadas con muros anchos aislantes, hostales de alta montaña especializados en montañeros y albergues de naturaleza forestal. | El principal nexo logístico y de acceso al Parque Natural de la Sierra de Cebollera. Ofrece la espectacular ruta de senderismo de las Cascadas de Puente Rá, caminatas que ascienden hacia los circos glaciares del pico Cebollera (2.141 metros), senderos botánicos bajo inmensos bosques de pinos silvestres, hayedos y acebedas, observación astronómica de cielos negros certificados (Starlight) y micología de otoño. [1]') WHERE codigo_ine = '26177';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Apartamentos tradicionales de montaña con acabados en madera de pino y castaño, casas de pueblo tradicionales enriscadas en una colina caliza y cabañas de madera forestales. | Comarca de Camero Nuevo, bañado por el río Alberco alto y lindando con el Embalse de González Lacasa. Custodia las impresionantes Cuevas de Ortigosa (colosales galerías kársticas de estalactitas y estalagmitas abiertas en el interior del monte calcáreo de la Viña, transitables con visitas guiadas de aventura). Rutas senderistas que cruzan su imponente puente de hormigón sobre el abismo y dehesas forestales linderas.') WHERE codigo_ine = '26112';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Palacetes de turismo de interior integrados en casonas nobiliarias señoriales del siglo XVI y XVII de sillería dorada con escudos heráldicos, apartamentos rústicos con encanto arquitectónico gótico en el casco viejo y posadas. | Asentado de forma espectacular sobre un cerro que vigila un meandro cerrado del río Ebro en la Rioja Alta (Conjunto Histórico). Ofrece paseos fotográficos de interpretación del paisaje y dehesas de viñedos, rutas de senderismo agrícola entre calados tradicionales, cicloturismo de carretera familiar sin tráfico y turismo gastronómico-rural. [1]') WHERE codigo_ine = '26034';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Parador nacional emplazado en un antiguo hospital de peregrinos del siglo XII, albergues de paso históricos y casonas castellano-riojanas tradicionales de labranza en las llanuras agrícolas de su término. | Valle del río Oja medio, hito monumental central del Camino de Santiago Francés. Rutas de senderismo plano de interpretación histórica que siguen las calzadas y dehesas agrarias de la llanura cerealista, paseos fluviales por el sendero del río Oja bajo bosques de galería, cicloturismo de paseo familiar por cañadas reales ganaderas y dehesas agrícolas de cultivos. PROVINCIA: SALAMANCA (Texto Plano Limpio)') WHERE codigo_ine = '26138';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de turismo rural de arquitectura popular serrana (entramados de madera, piedras de granito y balcones volados), hoteles de montaña rústicos con encanto y apartamentos rurales con chimenea encalada. | En el corazón del Parque Natural de Las Batuecas-Sierra de Francia (Reserva de la Biosfera). Destaca por las rutas de senderismo hacia el Valle de Las Batuecas (Senda del río Batuecas hasta las pinturas rupestres prehistóricas del neolítico y el Monasterio del desierto carmelita), ascensiones a la mítica Peña de Francia (1.727 metros de altitud) y el sendero etnográfico del Camino de las Raíces bajo castaños centenarios.') WHERE codigo_ine = '37005';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casonas de labranza tradicionales de los Arribes construidas en piedra de granito con patios castellano-leoneses, apartamentos rústicos y posadas de turismo activo orientadas al senderismo fluvial. | Pleno Parque Natural de Arribes del Duero. Sede de la espectacular ruta de senderismo hacia el Pozo de los Humos (imponente e histórica cascada del río Uces en caída libre de más de 50 metros rodeada de encinares y cortados calizos). Ofrece paseos por los cañones fluviales del río Duero, senderos que visitan viñedos escarpados en bancales tradicionales y observación ornitológica de primer nivel (cigüeña negra, buitre leonado y águila real).') WHERE codigo_ine = '37250';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de montaña tradicionales de sillería de granito gruesa con batipuertas (típicas medias puertas de madera), galerías de leña abiertas y posadas de alta montaña con chimeneas de piedra para el invierno. | Enclavado en la Sierra de Candelario (Sierra de Béjar alta). Destaca por su trazado urbano con regaderas de agua cristalina de deshielo vivas. Ofrece exigentes rutas de senderismo alpino de alta montaña hacia el pico Calvitero (2.425 metros de altitud, el techo de Salamanca) y los circos glaciares de la Hoya Moros, rutas con raquetas de nieve, senderos micológicos de otoño y densos robledales.') WHERE codigo_ine = '37078';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hoteles boutique rurales en antiguas casas señoriales, viviendas de turismo rural empedradas con entramados de madera oscura que lucen retratos pintados de sus antiguos habitantes en las fachadas, y hostales con chimeneas de leña rústicas. | Conjunto Histórico en el corazón de la Sierra de Francia profunda. Sede de la famosa y fotogénica ruta de senderismo del Camino del Agua (un sendero circular homologado que fusiona esculturas de autores contemporáneos al aire libre con la fronda del bosque mediterráneo). Ofrece caminatas bajo sotos umbríos de castaños viejos, rutas micológicas otoñales y paseos fluviales por arroyos de montaña de aguas limpias.') WHERE codigo_ine = '37194';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Alojamientos rurales intramuros dentro de una villa medieval amurallada sobre una colina escarpada, castillos medievales reconvertidos parcialmente para pernocta de lujo, posadas serranas y apartamentos rústicos familiares. | Confluencia de los ríos Francia y San Benito, en la Sierra de Francia. Sede de la ruta de senderismo del Camino de los Prodigios (itinerario artístico-natural entre robledales y viñedos viejos). Ofrece paseos por las dehesas tradicionales salmantinas, caminatas por los profundos valles forestales húmedos que cobijan líquenes y setas en temporada, y avistamiento de aves rapaces de bosque.') WHERE codigo_ine = '37193';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de piedra tradicionales de mampostería antigua de grano granítico, apartamentos rústicos acogedores en el casco fortificado a la sombra del castillo de don Dionís de Portugal y posadas de campiña alta. | Comarca de El Abadengo, en los límites de Arribes del Duero meridional. Rutas de senderismo de interpretación etnográfica e histórica (Ruta de las Fortificaciones de Frontera), caminatas hacia el cañón del río Águeda inferior, senderos micológicos de monte bajo y dehesa, y paseos agrícolas entre olivares centenarios y almendros que florecen de forma espectacular en invierno.') WHERE codigo_ine = '37285';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Posadas reales neoclásicas en antiguas casonas de cantería, casas de labranza tradicionales salmantinas con amplios patios de carruajes, y apartamentos rurales familiares de interior. | Asentado de forma monumental sobre un meandro de roca granítica del río Tormes bajo (Conjunto Histórico). Ofrece la Senda Fluvial del río Tormes, un tramo de bosque de galería maduro e islas protegidas. Rutas de senderismo hacia los campos de dehesa del Campo Charro norte, paseos de interpretación botánica entre encinas viejas y canchales de granito liso, y rutas micológicas otoñales. PROVINCIA: MURCIA (Texto Plano Limpio)') WHERE codigo_ine = '37170';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Cortijos tradicionales de montaña construidos en sillería de piedra caliza con chimeneas de leña, complejos rústicos de cabañas de madera forestales y casas de cal de pueblo serrano enclavadas bajo su imponente castillo de la Orden de Santiago. | En el corazón del interior montañoso más abrupto e indómito de la región. Custodia el paraje natural de los Calares de la Santa y la Sierra de Mojantes. Destaca por el sendero fluvial de La Puerta (espectacular caminata sombría por el cauce del río Alhárabe entre estrechos cañones de roca caliza y pozas de agua cristalina aptas para el baño veraniego), rutas de senderismo de alta montaña que ascienden al pico Revolcadores (techo de la región con 2.014 metros de altitud), senderos micológicos otoñales y arte rupestre (Patrimonio de la Humanidad).') WHERE codigo_ine = '30028';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales integradas en fincas forestales y de agricultura de colina, complejos orientados al turismo activo y la escalada deportiva, hostales de montaña a las faldas del Parque y apartamentos rústicos. | Principal nudo logístico y de acceso al Parque Natural de Sierra Espuña. Ofrece las rutas de senderismo que recorren el Valle de Leiva, la Senda del Dinosaurio con puentes colgantes, y caminatas geológicas interpretativas por los espectaculares Pozos de la Nieve del siglo XVI integrados en las cumbres alpinas. Destaca por las dehesas forestales de pino carrasco y laricio más densas del levante, y es un destino con certificación Starlight por la excelente calidad de sus cielos nocturnos para la observación astronómica.') WHERE codigo_ine = '30008';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Palacetes de turismo de interior integrados en casonas nobiliarias de sillería dorada con escudos heráldicos en el casco histórico medieval, fincas de agroturismo ganadero y apartamentos rurales familiares con amplios porches rústicos. | Nudo monumental del Noroeste murciano flanqueado por las Sierras de la Sagra y de las Cabras. Custodia el idílico paraje natural de las Fuentes del Marqués (un oasis botánico espectacular repleto de manantiales caudalosos de agua pura de deshielo, riachuelos y cuevas artificiales en mitad de un bosque maduro de encinas y quejigos). Ofrece rutas de senderismo por la Vía Verde del Noroeste (antiguo trazado de tren ideal para familias y cicloturismo), caminatas de media montaña y paseos fotográficos.') WHERE codigo_ine = '30015';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de campo tradicionales de labranza vinculadas al agroturismo arrocero a orillas del agua, apartamentos rústicos con porche de leña y hostales de cañón orientados a los deportes de aventura y aguas bravas. | Bañado por el curso alto del río Segura y su confluencia con el río Mundo. Alberga el Monumento Natural del Cañón de Almadenes (espectacular desfiladero kárstico angosto de paredes de roca caliza verticales de más de 100 metros de altura sobre el Segura). El mayor hub de turismo activo de la región; destaca por la práctica de rafting, hidrospeed y kayak en aguas bravas. Rutas de senderismo ecológico que visitan el Santuario de la Virgen de la Esperanza (excavado directamente en la roca de la gruta caliza fluvial) y paseos ornitológicos en arrozales.') WHERE codigo_ine = '30013';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Alojamientos rurales unifamiliares integrados en antiguas casas de labranza tradicionales con almazaras de aceite recuperadas, fincas rústicas de frutales y apartamentos de montaña en las pedanías del Parque (como La Santa). | Vertiente sur de la Sierra de Espuña caliza, resguardada de los vientos del norte. Ofrece la espectacular ruta de senderismo del Barranco de Gebas, un paisaje geológico único de \"badlands\" o cárcavas arcillosas de aspecto lunar que mueren en las aguas de color azul turquesa del Embalse de Algeciras. Caminatas hacia el Santuario de Santa Eulalia rodeado de pinares viejos de repoblación, rutas de cicloturismo de montaña (BTT) de alto nivel y visitas al yacimiento argárico de La Bastida en plena naturaleza.') WHERE codigo_ine = '30039';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de campo señoriales de interior con anchos muros de mampostería integradas en bodegas tradicionales y viñedos de altura, posadas de interior rústicas y apartamentos rurales familiares. | Altiplano murciano septentrional, rodeado por el espacio protegido de la Sierra del Carche. Ofrece rutas que conectan senderos agrícolas entre interminables campos de cepas viejas de uva monastrell cultivadas en colinas áridas, caminatas de media montaña que ascienden hacia el pico de la Madama (1.371 metros) entre pinares silvestres y dehesas calizas secas, senderos botánicos, cicloturismo de carretera sin tráfico y enoturismo de primer nivel.') WHERE codigo_ine = '30022';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de cal de pueblo andalusí de alquiler íntegro con chimeneas rústicas, apartamentos rústicos pequeños vinculados al agroturismo de almendros y frutales de hueso, y posadas de interior. | Cuenca del río Mula y falda septentrional de Sierra Espuña. Célebre por el espectáculo botánico primaveral de la floración masiva del almendro que tiñe sus campos de tonos blancos y rosados. Rutas de senderismo hacia el paraje de Fuente Caputa (un entramado de pozas naturales de agua cristalina y manantiales en mitad de un cañón calizo rústico ideales para el baño en verano), cicloturismo por la Vía Verde del Noroeste y senderos históricos que rodean su castillo del siglo XVI alto.') WHERE codigo_ine = '30029';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casonas solariegas de sillería de piedra caliza con espectaculares balconadas de forja tradicional en un casco histórico medieval galardonado (Conjunto Histórico), apartamentos rústicos de montaña unifamiliares con jardín y barbacoa. | Comarca del Noroeste de interior. Ofrece paseos etnográficos de aislamiento y caminatas botánicas, rutas de senderismo que recorren la Sierra de la Peña Rubia con escuelas de escalada clásica y deportiva en paredes de roca, caminatas llanas fluviales por el sendero del río Argos bajo túneles vegetales umbríos de alisos y chopos, y rutas cicloturistas de montaña (BTT). PROVINCIA: TERUEL (Texto Plano Limpio)') WHERE codigo_ine = '30017';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Posadas medievales integradas en murallas de yeso rojizo, casonas tradicionales de la serranía con entramados de madera de enebro y galerías de forja, hoteles boutique de naturaleza con vistas al cañón y apartamentos rústicos. | Capital de la Sierra de Albarracín. Custodia el Paisaje Protegido de los Pinares de Rodeno. Destaca por las rutas de senderismo hacia las pinturas rupestres prehistóricas levantinas, el sendero fluvial adaptado de las riberas del río Guadalaviar que rodea el casco monumental, una de las mayores mecas mundiales de la escalada en bloque (búlder) bajo el bosque y senderos micológicos de primer nivel (boletus).') WHERE codigo_ine = '43001';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Antiguas masías agrícolas fortificadas de piedra dorada aisladas entre olivares y almendros, hoteles de campo boutique con criterios de diseño eco-sostenible y casas rurales de piedra gótica rehabilitadas en el casco viejo amurallado. | Capital de la Comarca del Matarraña (bautizada como la Toscana española). Ofrece paseos fotográficos y rutas cicloturistas a lo largo de las riberas del río Matarraña, conexiones directas con la Vía Verde de la Val de Zafán (cicloturismo de túneles y viaductos espectaculares), caminatas botánicas por valles mediterráneos de colinas suaves y senderos micológicos de encinar.') WHERE codigo_ine = '44246';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casonas de piedra señoriales del Maestrazgo, antiguos cuarteles y hosterías carlistas rehabilitadas con grandes chimeneas rústicas de campana, y apartamentos rurales familiares orientados al montañismo de aislamiento. | Encaramado de forma vertiginosa a un impresionante risco calizo a 1.300 metros de altitud en el Maestrazgo salvaje. Rutas de senderismo de los Miradores del Maestrazgo, caminatas por las hoces y muelas calcáreas talladas por el río Cantavieja, senderos de interpretación de la arquitectura tradicional de piedra seca (Patrimonio de la Humanidad por la UNESCO) y avistamiento de buitres leonados y cabra montés.') WHERE codigo_ine = '44059';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Palacetes rurales renacentistas de sillería dorada con balcones de forja tradicional en un casco urbano de piedra protegido, casas de turismo rural independientes y apartamentos boutique de interior. | Comarca del Matarraña alto, rodeado de lomas olivareras. Destaca por las rutas de senderismo arqueológico hacia el poblado íbero de San Antonio integrado de forma virgen en el monte, caminatas tranquilas entre campos de olivos milenarios y viñedos, cicloturismo de carretera familiar sin tráfico y paseos botánicos por bosques mediterráneos de pino carrasco.') WHERE codigo_ine = '44049';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hoteles rurales de montaña de carácter familiar orientados al turismo de nieve, casas rurales de alquiler íntegro con chimeneas de piedra caliza y antiguos caseríos ganaderos mimetizados en la falda de la sierra. | Comarca de Gúdar-Javalambre. Rutas senderistas bajo frondosos bosques boreales de pino negro de alta montaña, turismo micológico de primer nivel mundial (epicentro de la recolección regulada de la Trufa Negra de Teruel y robellones en otoño), cercanía inmediata a la estación de esquí de Valdelinares y cicloturismo de montaña por los Altos de Gúdar.') WHERE codigo_ine = '44158';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de labranza tradicionales con espectaculares aleros de madera tallada a mano, hoteles boutique rurales con patios interiores ajardinados y posadas medievales de piedra (Premio Europa Nostra por su conservación). | Piedemonte de la Sierra de Gúdar. Ofrece la ruta senderista del río Mijares, senderos de interpretación botánica por dehesas mixtas de sabinas y encinas viejas, rutas ecuestres de montaña y es una de las zonas de máxima nitidez nacional para la observación de estrellas al contar con certificación Starlight de cielos negros limpios.') WHERE codigo_ine = '44201';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de turismo rural intramuros integradas en un conjunto arquitectónico medieval gótico intacto y protegido, y palacetes de la Orden del Temple habilitados para pernocta rústica. | Corazón del Maestrazgo profundo. Ofrece paseos etnográficos de aislamiento absoluto, rutas de senderismo hacia el cercano Monumento Natural de las Cuevas de Cañart, caminos tradicionales de herradura delimitados por interminables muros de piedra seca y caminatas por riberas de montaña calizas secas.') WHERE codigo_ine = '44149';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Apartamentos rústicos de alta montaña aislados, casas de piedra de cantería con ventanas saeteras tradicionales y chimeneas de campana bajo las murallas de su castillo. | Enclavado en el Parque Cultural del Maestrazgo, a las faldas de la Sierra de Gúdar. Impresionantes rutas de senderismo hacia el cañón salvaje del río Monleón, caminatas exigentes entre pinares silvestres alpinos, senderos de interpretación micológica otoñal (níscalos) y cascadas ocultas de deshielo.') WHERE codigo_ine = '44193';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hoteles de naturaleza de lujo orientados al ecoturismo y la gastronomía micológica de kilómetro cero, masías unifamiliares rodeadas de pinares. | Matarraña montañoso occidental, lindando con la provincia de Castellón. Destaca por las rutas de senderismo que ascienden a las Peñas de Masmut (colosales farallones verticales de roca caliza rosada), avistamiento ornitológico de buitres leonados, rutas de recolección de setas en sus pinares húmedos de altura y circuitos BTT.') WHERE codigo_ine = '44154';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales unifamiliares con porches de roca, apartamentos rústicos al pie de imponentes peñascos calizos y castillos templarios enriscados. | Maestrazgo septentrional. Alberga el Monumento Natural del Puente de Fonseca (espectacular formación kárstica natural con tobas calizas y túneles de musgo sobre el río Guadalope). Destaca por la ruta senderista que cruza las hoces y el túnel excavado en la roca del embalse de Santolea y senderos micológicos de monte bajo.') WHERE codigo_ine = '44071';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Alojamientos rurales de gran nivel integrados en antiguas casas señoriales medievales con bodegas de vino antiguas, masías rurales con encanto en los campos linderos del llano. | Comarca del Matarraña. Cruce de caminos central de la Vía Verde de la Val de Zafán (cicloturismo de túneles y viaductos espectaculares). Rutas senderistas de arte rupestre en el barranco del Calapatá, paseos llanos fotográficos y senderos agrícolas de olivares y almendros.') WHERE codigo_ine = '44086';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de pueblo tradicionales de mampostería estrecha de piedra, apartamentos rurales acogedores para familias y espeleólogos a pie de montaña. | Maestrazgo kárstico. Alberga el Monumento Natural de las Grutas de Cristal (colosal e imponente joya espeleológica mundial de estalactitas y estalagmitas excéntricas). Rutas de senderismo por el espectacular cañón del río Guadalopillo, caminatas geológicas interpretativas y senderos entre huertos tradicionales.') WHERE codigo_ine = '44151';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales de alta montaña de piedra caliza con aislamiento reforzado, apartamentos rústicos forestales pegados a la espesura del bosque. | Sierra de Albarracín, a más de 1.500 metros de altitud. Uno de los mayores pulmones continuos de pinares de pino silvestre de España. Destaca por el senderismo micológico extremo (paraíso de la recolección del hongo boletus), rutas botánicas de las fuentes de Bronchales, avistamiento de ciervos y corzos en libertad y aire puro de altitud.') WHERE codigo_ine = '44045';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Chalets alpinos rústicos de alta montaña tradicionales, apartamentos de turismo de nieve a pie de laderas forestales y pinadas. | El municipio situado a mayor altitud de la península ibérica considerando su núcleo urbano (1.692 metros), en la Sierra de Gúdar alta. Rutas de senderismo de alta montaña entre pinares boreales de pino negro autóctono, caminatas hacia los cortados de las umbrías, raquetas de nieve invernales y esquí alpino.') WHERE codigo_ine = '44244';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de piedra tradicionales de montaña con muros anchos aislantes, apartamentos rústicos en valles cerrados de frutales de montaña junto a arroyos trucheros. | Valle del río Pau, Sierra de Gúdar. Rutas de senderismo hacia el Monumento Natural del Pino del Escbón (abeto-pino monumental centenario protegido), paseos de interpretación fluvial, senderos ganaderos que suben a brañas de altura y turismo micológico.') WHERE codigo_ine = '44137';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Palacetes rurales de piedra caliza con espectaculares arcos, posadas de turismo de interior con encanto del Matarraña y masías. | Cuenta con la tirolina en posición tumbada más larga de Europa (casi 2 km cruzando un valle de montaña). Rutas de senderismo hacia el Covavina, caminatas que miran a los Puertos de Beceite, senderos botánicos entre encinas y olivares rústicos de ladera.') WHERE codigo_ine = '44114';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casonas rurales serranas de piedra con forja tradicional, apartamentos de montaña independientes rodeados de dehesas ganaderas. | Extremo norte de la Sierra de Albarracín. Destaca por los singulares \"Ríos de Piedra\" (colosales acumulaciones geológicas de bloques de cuarcita de origen periglaciar únicos en Europa). Rutas de senderismo hacia el pico Caimodorro, paseos por melojares (robledales) y recolección de setas.') WHERE codigo_ine = '44174';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de pastores de la alta sierra tradicionales, apartamentos rústicos orientados al turismo etnográfico y de aislamiento. | Muela de San Juan, nacimiento del río Guadalaviar/Turia. Capital histórica de la transhumancia ganadera. Rutas de senderismo hacia los nacimientos fluviales, paseos por inmensos pastizales alpinos de alta montaña, senderos micológicos de otoño y avistamiento de fauna ibérica de monte alto.') WHERE codigo_ine = '44120';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Alojamientos rurales unifamiliares con chimenea central, apartamentos de montaña construidos en mampostería de roca y albergues alpinos. | El segundo pueblo más alto de España, en la falda de la Muela de San Juan. Rutas de senderismo arqueológico hacia las dehesas celtíberas del llano, caminatas de invierno con raquetas de nieve, pistas de esquí de fondo forestales de naturaleza y miradores hacia valles de origen glaciar.') WHERE codigo_ine = '44119';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de campo tradicionales de la cuenca minera y agrícola del río Alfambra, pequeños hostales rurales sencillos. | Uno de los yacimientos paleontológicos de dinosaurios más importantes de Europa. Rutas de senderismo e interpretación al aire libre que siguen reproducciones de dinosaurios a escala real integradas en riberas fluviales arcillosas, y senderos geológicos singulares de badlands aragonesas. PROVINCIA: GUADALAJARA (Texto Plano Limpio)') WHERE codigo_ine = '44115';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casonas solariegas de sillería dorada de la nobleza molinesa con amplios patios interiores rústicos, hoteles de montaña de piedra y madera, y apartamentos rurales con vistas directas a su colosal alcázar medieval. | Eje logístico y natural del Geoparque Mundial de la UNESCO de la Comarca de Molina-Alto Tajo. Destaca por la emblemática ruta de senderismo del Barranco de la Hoz (un desfiladero espectacular de areniscas rojizas esculpido por el río Gallo con agujas de roca caprichosas), senderos que se adentran en el Parque Natural del Alto Tajo, micología otoñal y es una zona de máxima pureza para la observación astronómica nocturna con certificación Starlight.') WHERE codigo_ine = '19190';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Parador de turismo nacional emplazado de forma monumental en el imponente castillo medieval fortificado, casonas nobiliarias señoriales reconvertidas en hoteles boutique en el casco histórico e históricas fincas de labranza. | Valle del río Henares y nexo de acceso al Parque Natural del Barranco del Río Dulce. Ofrece la espectacular ruta de senderismo del río Dulce (caminata plana por el fondo de un angosto cañón calizo bajo cortados donde anidan grandes rapaces y que aloja el mirador de Félix Rodríguez de la Fuente), senderos botánicos entre sabinares y quejigales centenarios, y cicloturismo de carretera familiar.') WHERE codigo_ine = '19257';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Complejos de cabañas forestales de madera mimetizadas bajo el pinar, hostales de alta montaña especializados en pescadores y montañeros, y casas rurales de piedra junto al río con chimeneas rústicas de campana. | En el interior del Parque Natural del Alto Tajo profundo. Sede de rutas de senderismo fluvial escarpadas y espectaculares que transitan entre estrechos cañones calizos, pozas de agua helada turquesa cristalina ideales para el baño y el descanso estival en la Laguna de Taravilla o el Salto de Poveda. Pesca deportiva de trucha con mosca sin muerte en ríos vírgenes limpios, piragüismo y senderos micológicos extremos.') WHERE codigo_ine = '19216';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Posadas de turismo de interior integradas en conventos franciscanos y palacios del siglo XVI y XVII de sillería dorada con escudos heráldicos, apartamentos con encanto arquitectónico en el casco medieval y casas de labranza de la Alcarria. | Comarca de La Alcarria meridional, valle de los ríos Arlés y Guadiela. Ofrece rutas que conectan con senderos agrícolas entre colinas de monte bajo mediterráneo aromático (tomillo, espliego, romero), caminatas tranquilas de dehesa agraria e interpretación apícola (rutas de la miel de la Alcarria), cicloturismo de carretera familiar sin tráfico y paseos fotográficos.') WHERE codigo_ine = '19212';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de montaña de piedra caliza tradicionales con muros anchos aislantes, apartamentos rústicos forestales integrados en pequeños núcleos del valle y albergues de naturaleza fluvial. | Centro geográfico y de interpretación del Parque Natural del Alto Tajo. Alberga el espectacular paraje de la Escaleruela y el Mirador de Zaorejas colgado sobre un meandro vertical cerrado con caídas de roca de más de 150 metros. Rutas de senderismo de cañón de río bajo túneles vegetales umbríos de pinos laricios, quejigos y tejos salvajes, caminatas micológicas y observación astronómica (cielos negros certificados Starlight).') WHERE codigo_ine = '19333';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Palacetes de turismo de interior vinculados al agroturismo vitivinícola, casas de labranza tradicionales de campiña alta con patios de carruajes y apartamentos rurales de cara a su plaza porticada medieval. | Piedemonte de la Sierra de Ayllón occidental, bañado por el río Aliendre. Ofrece las rutas de senderismo que suben a las ruinas de su castillo del siglo IX alto, caminatas agrícolas entre dehesas tradicionales y campos de viñedos viejos de altura, cicloturismo de carretera, turismo gastronómico-rural y base sur de acceso a los cañones de la Sierra Norte.') WHERE codigo_ine = '19092';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de aldea de mampostería de piedra tradicionales de montaña alta de aislamiento, apartamentos rústicos pequeños con chimenea de piedra de suelo y albergues forestales de paso. | Límite noroccidental de la Sierra Norte alta, frontera con Segovia. Custodia el Parque Natural del Hayedo de Tejera Negra (el bosque de hayas más meridional de Europa central, Patrimonio de la Humanidad por la UNESCO). Espectaculares y protegidas rutas de senderismo botánico otoñal de gran valor fotográfico (Senda de las Carretas) bajo las hayas centenarias mezcladas con tejos, abedules y acebos mágicos, senderos pastoriles de montaña, ríos trucheros limpios (río Lillas) y recolección micológica.') WHERE codigo_ine = '19065';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hoteles de campo y posadas de turismo interior articulados en torno al patrimonio termal tradicional de su Real Balneario de Carlos III, apartamentos de ribera y casas de cal con porche junto al río Cifuentes. | Confluencia de los ríos Tajo y Cifuentes, a los pies de las Tetas de Viana (muelas gemelas calizas singulares). Célebre por el espectacular paraje de las Cascadas del río Cifuentes (un torrente de agua que cae en cascadas y saltos de agua rústicos ruidosos en pleno casco urbano entre puentes y vegetación de ribera). Rutas de senderismo de ascensión a las Tetas de Viana (Monumento Natural), paseos fluviales por el Tajo, piragüismo y pesca deportiva. PROVINCIA: BURGOS (Texto Plano Limpio)') WHERE codigo_ine = '19291';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de turismo rural colgadas en el desfiladero, posadas medievales intramuros con entramados de madera y balconadas rústicas, y apartamentos con vistas al río Ebro. | Ubicado plenamente en el Parque Natural de Montes Obarenes-San Zadornil. Destaca por la ruta de senderismo del Desfiladero del río Purón (estrecho cañón fluvial espectacular), la senda del cañón del Ebro, paseos botánicos por el hayedo de San Zadornil (\"la Nueva York de los bosques\"), paseos fluviales por el puente románico fortificado y piragüismo de interior.') WHERE codigo_ine = '09134';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Posadas reales castellanas de anchos muros de sillería dorada, hoteles rurales con encanto histórico dentro de la villa y casas de pueblo independientes para grupos familiares. | Espacio Natural Protegido de Sabinares del Arlanza y de la Yecla. Alberga el Desfiladero de la Yecla (espectacular y angosta garganta kárstica transitable a pie mediante pasarelas colgantes sobre el río). Ofrece la ruta del Cementerio de Sad Hill (escenario cinematográfico de dehesa integrado en la naturaleza), y el sendero de los sabinares albares más antiguos de la península.') WHERE codigo_ine = '09358';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Palacetes rurales rústicos con fachadas de cal y vigas de madera vista, apartamentos rústicos acogedores y alojamientos de ribera junto al Arlanza. | Valle del río Arlanza. Ofrece la ruta senderista del Sendero del Buen Conde, caminatas hacia las ruinas del Monasterio de San Pedro de Arlanza (rodeado de inmensos bosques de encinas y sabinas de roca), senderos cicloturistas de llanura alta y paseos de interpretación del valle fluvial.') WHERE codigo_ine = '09113';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casonas hidalgas fortificadas y palacios rurales de sillería gruesa, posadas de montaña orientadas a montañeros y cabañas pasiegas-burgalesas en las pedanías del norte. | Comarca de Las Merindades, frontera con los Valles Pasiegos de Cantabria. Destaca por el Monumento Natural de Ojo Guareña (colosal complejo de cuevas kársticas subacuáticas y galerías con ermita rupestre). Ofrece rutas de alta montaña hacia Castro Valnera, senderos bajo hayedos de las faldas cantábricas, y raquetas de nieve en invierno.') WHERE codigo_ine = '09124';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de montaña de piedra roja caliza y teja curva tradicionales de la sierra alta, apartamentos rústicos con chimenea de leña y albergues de naturaleza forestal. | Corazón de la Sierra de la Demanda. Nudo de la Vía Verde de la Demanda (antiguo trazado ferroviario minero ideal para senderistas y cicloturistas). Rutas de ascensión alpina al Pico Mencilla y al San Millán (techo de Burgos con 2.131 metros), senderos rodeados de acebales protegidos, robledales centenarios y el embalse del Arlanzón.') WHERE codigo_ine = '09266';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de turismo rural intramuros con patios de mampostería antigua, apartamentos turísticos integrados en el casco histórico señorial. | Eje del Parque Natural de Montes Obarenes-San Zadornil. Sede del Sendero del Desfiladero de la Horadada (colosal garganta cortada por el río Oca). Ofrece rutas de senderismo botánico entre encinares atlánticos y mediterráneos mixtos, paseos fluviales por canales medievales de agua y micología forestal de otoño.') WHERE codigo_ine = '09238';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Posadas de alta montaña construidas con vigas de pino de la Demanda y piedra caliza, casas rurales unifamiliares de pinar aisladas en las alturas. | Custodia el Parque Natural de las Lagunas Glaciares de Neila. Espectaculares rutas de senderismo de alta montaña que recorren el borde de los circos glaciares (Laguna Negra, Laguna Larga, Laguna de la Cascada), senderos micológicos de pinar húmedo alto (boletus), observación astronómica certificada Starlight y senderos de pastores trashumantes.') WHERE codigo_ine = '09232';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hostales rurales especializados en micología y turismo activo, cabañas de madera forestales mimetizadas y grandes casas de piedra de cantería burgalesa. | Comarca de Pinares, falda meridional de la Sierra de la Demanda. Rutas de senderismo al Comunero de Revenga (necrópolis medieval tallada en roca rodeada de robles centenarios), caminatas hacia las Lagunas de Neila, recolección masiva de hongos boletus y níscalos en pinares silvestres infinitos y senderos fluviales del Arlanzón joven.') WHERE codigo_ine = '09289';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas solariegas de turismo rural amplias para grupos, hoteles boutique de interior con encanto medieval en el casco antiguo y fincas rurales. | Valle de Tobalina alto, comarca de Las Merindades. Rutas de senderismo suave que bordean las dehesas del río Trueba, paseos cicloturistas llanos de gran recorrido por la antigua línea del Santander-Mediterráneo, y punto base idóneo para explorar los cañones calizos de la zona norte.') WHERE codigo_ine = '09209';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales vinculadas al patrimonio industrial textil del siglo XIX (antiguas fábricas e hilaturas mecánicas reconvertidas en pernoctas), apartamentos rústicos. | Sierra de la Demanda húmeda. Sede de la ruta de senderismo de la Senda de los Cascajales, caminatas bajo la umbría de densos hayedos calcícolas del río Oropesa, senderos micológicos micológicos de pinar y quejigal y paseos fotográficos fluviales de montaña.') WHERE codigo_ine = '09274';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hoteles de campo y casas de turismo rural integrados en bodegas subterráneas tradicionales de la Ribera del Duero, fincas vinícolas tradicionales de agroturismo. | Comarca de la Ribera del Duero. Rutas de senderismo suave entre dehesas de viñedos centenarios de uva tempranillo, paseos cicloturistas llanos por los caminos de sirga del canal del Duero, turismo gastronómico-rural de asados y enoturismo de primer nivel mundial.') WHERE codigo_ine = '09256';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de labranza castellanas tradicionales de anchos muros de tapial y piedra caliza blanca con patios de carruajes, posadas rurales de campiña. | Llanura cerealista de la comarca de Odra-Pisuerga. Cruzado por el Camino de Santiago de la Meseta. Rutas de senderismo plano de interpretación histórica que siguen las calzadas romanas locales (Segisama), caminatas tranquilas de dehesa agraria y avistamiento de avifauna esteparia.') WHERE codigo_ine = '09363';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Alojamientos rurales unifamiliares en el casco fortificado de piedra y caliza, apartamentos rústicos de montaña. | Borde del Páramo de Masa y cuna de Félix Rodríguez de la Fuente. Cuenta con el espectacular diapiro salino (fenómeno geológico visible desde el espacio). Rutas de senderismo por las antiguas Salinas romanas de evaporación, caminatas de ascensión al castillo calizo sobre el abismo y rutas ornitológicas de grandes rapaces de roca.') WHERE codigo_ine = '09272';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Palacetes rurales renacentistas con patios porticados rústicos, posadas de turismo rural medievales con vistas al castillo calizo alto. | Ribera del Duero oriental. Rutas de senderismo histórico que rodean su torre del homenaje del siglo X, caminatas agrícolas entre viñedos de cepa vieja, y senderos llanos fluviales que siguen el curso del río Arandilla.') WHERE codigo_ine = '09261';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Albergues y casonas de turismo de interior vinculados al Camino de Santiago Francés, casas de labranza riojano-burgalesas. | Comarca de la Riojilla Burgalesa, falda norte de la Sierra de la Demanda. Rutas del Camino de Santiago, senderismo hacia las cuevas eremíticas paleocristianas talladas en las colinas de arcilla linderas, paseos por las riberas del río Tirón y rutas cicloturistas de dehesa.') WHERE codigo_ine = '09048';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de pueblo blanco andaluz de cal e impecable piedra caliza con chimeneas de leña, hoteles rurales boutique encaramados al risco medieval y apartamentos rústicos con vistas directas al cañón fluvial. | En el corazón del Parque Natural de las Sierras Subbéticas (Geoparque de la UNESCO). Destaca por la espectacular y mítica ruta de senderismo del Río Bailón (caminata que cruza profundos cañones y lapiaces calcáreos), la visita guiada a la Cueva de los Murciélagos (colosal yacimiento arqueológico del neolítico con pinturas rupestres integradas en la roca), paseos por la Vía Verde de la Subbética para cicloturismo y senderos micológicos.') WHERE codigo_ine = '14075';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Palacetes barrocos de interior en su histórico barrio de la Villa, casas de turismo de labranza vinculadas al agroturismo olivarero, cortijos tradicionales andaluces con patios de azulejos y fuentes de agua fresca. | Falda norte de las Sierras Subbéticas. Ofrece rutas de senderismo de alta montaña que ascienden al pico Tiñosa (techo de la provincia de Córdoba con 1.568 metros de altitud), paseos fotográficos de naturaleza entre olivares de pendiente extrema, caminatas botánicas que visitan el paraje del manantial de la Fuente del Rey, y cicloturismo de carretera sin tráfico.') WHERE codigo_ine = '14055';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Grandes cortijos ganaderos señoriales de sillería rústica Morena, fincas de montería con picaderos de caballos, complejos de cabañas de madera forestales y casas de campo aisladas de la civilización. | Custodia el Parque Natural de Sierra de Hornachuelos. Alberga uno de los bosques mediterráneos y dehesas de encinas y alcornoques mejor conservados del sur peninsular. Rutas de senderismo de aventura por el Sendero del Guadalora (bosque de galería fluvial denso y cerrado), caminatas hacia el embalse de Bembézar (kayak, piragüismo de interior), observación ornitológica de grandes rapaces (buitre negro, águila imperial) y dehesas de ganado extensivo.') WHERE codigo_ine = '14036';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casonas de labranza tradicionales de Los Pedroches construidas en piedra de grano granítico grueso con portalones rústicos, apartamentos turísticos de interior y alojamientos de agroturismo dedicados a la cría tradicional del cerdo ibérico de bellota. | Capital de la Comarca de Los Pedroches. Ofrece una experiencia única de turismo rural en un mar infinito de encinas centenarias. Rutas de senderismo de interpretación ambiental por la dehesa de Pozoblanco, caminatas llanas ideales para cicloturismo familiar de relax por las cañadas reales ganaderas, senderos micológicos otoñales y es una zona de máxima pureza para la observación astronómica nocturna al contar con certificación internacional Starlight.') WHERE codigo_ine = '14054';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de campo de interior unifamiliares con porches de roca caliza, hoteles rurales señoriales en el casco monumental e históricas posadas con patios andaluces rústicos llenos de macetas y hilos de agua. | Centro geográfico de las Sierras Subbéticas. Custodia el espectacular paraje natural del Picacho de la Sierra de Cabra (conocido como el \"Balcón de Andalucía\", una colosal muela calcárea con una ermita en su cumbre de más de 1.200 metros). Rutas de senderismo geológico por la Senda de la Fuente de las Piedras, caminatas kársticas por la sima de Cabra, y cicloturismo familiar por la Vía Verde del Aceite.') WHERE codigo_ine = '17006';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de pueblo tradicionales andaluzas de cal blanca de alquiler íntegro a los pies de su colosal e impecable castillo medieval de película, hostales de campo de interior y apartamentos rurales. | Vega del Guadalquivir medio, falda meridional de Sierra Morena y lindando con el Embalse de La Breña II. Ofrece rutas de senderismo que bordean el gran lago de interior, piragüismo, vela y kayak náutico, caminatas forestales bajo pinares de repoblación viejos y encinares de dehesa de Sierra Morena, y rutas de agroturismo.') WHERE codigo_ine = '17002';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales excavadas o asentadas sobre la roca de piedra moliz rojiza tradicional en el casco histórico colgado sobre el meandro, y fincas olivareras señoriales de campiña alta. | Bañado por un colosal y monumental meandro cerrado del río Guadalquivir (Monumento Natural). Ofrece rutas de senderismo fluvial por el sendero de las Aceñas, caminatas micológicas otoñales e interpretación ambiental por la dehesa del Parque Natural de Cardeña y Montoro norte, y rutas cicloturistas de carretera de colinas suaves.') WHERE codigo_ine = '14043';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casonas solariegas de granito de la comarca de Los Pedroches occidentales con patios de carruajes, posadas de turismo rural tradicionales de llanura alta y apartamentos rurales. | Entorno del altiplano ganadero de dehesas. Rutas de senderismo e interpretación etnográfica e histórica (Senda del Camino de Santiago Mozárabe), caminatas llanas ideales para cicloturismo de paseo entre encinares centenarios donde se observa fauna de dehesa, ornitología de aves esteparias y rapaces, y turismo astronómico nocturno con cielos limpios Starlight. PROVINCIA: GRANADA - ZONA NORTE Y ALTIPLANO (Texto Plano Limpio)') WHERE codigo_ine = '14035';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales andaluzas de cal blanca de alquiler íntegro integradas a las faldas de la peña, apartamentos rústicos de montaña con chimenea de leña y pequeños hostales rurales de turismo activo. | Custodia el Parque Natural de la Sierra de Castril. Sede de la célebre y fotogénica ruta de senderismo de las Pasarelas del Río Castril (un espectacular sendero de pasarelas de madera ancladas sobre la pared de roca caliza vertical del desfiladero fluvial). Ofrece caminatas exigentes hacia el Nacimiento del Río Castril, exploración de cuevas kársticas como la Cueva del Doncel, senderos micológicos en sus pinares de montaña y avistamiento de buitres leonados y quebrantahuesos.') WHERE codigo_ine = '18046';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas cueva auténticas excavadas directamente en la arcilla (alojamientos bioclimáticos subterráneos tradicionales con chimeneas blancas exteriores que mantienen temperatura constante todo el año), palacetes señoriales andaluces rústicos en el casco histórico y cortijos agrícolas aislados en la hoya. | Integrado en el Geoparque de Granada (UNESCO). Ofrece una experiencia única de turismo rural en un paisaje de cárcavas arcillosas de aspecto lunar. Rutas de senderismo geológico por los cañones de arcilla, cicloturismo por pistas áridas, rutas fotográficas al atardecer en el Mirador del Fin del Mundo y cercanía al Parque Natural de la Sierra de Baza.') WHERE codigo_ine = '18089';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Palacetes rurales renacentistas con portadas de piedra de sillería dorada, casas de turismo rural cueva independientes, fincas agrícolas de agroturismo ganadero y complejos de cabañas de montaña. | Extremo norte de la provincia, comarca de Huéscar. Destaca por el paraje natural de los Rodríguez, que alberga un bosque con ejemplares monumentales de Secuoyas Gigantes plantadas en el siglo XIX (las \"mariquitas\"). Rutas de senderismo de alta montaña que ascienden a la imponente mole caliza de la Sierra de la Sagra (2.383 metros de altitud, el pico más alto del altiplano), senderos de pastores de cordero segureño y rutas micológicas.') WHERE codigo_ine = '18098';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Cortijos andaluces señoriales con dehesas y amplias fincas arboladas rústicas, casas cueva turísticas rehabilitadas en sus pedanías de interior y hostales de campo. | Entrada central al Parque Natural de la Sierra de Baza. Ofrece rutas de senderismo de montaña por los prados altos y pinares béticos de la sierra, caminatas de ascensión hacia el pico Santa Bárbara (2.269 metros), senderos botánicos entre pinos carrascos y encinares centenarios, rutas de micología forestal de otoño y dehesas de ganado extensivo.') WHERE codigo_ine = '18023';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Complejos trogloditas turísticos (barrios de casas cueva tradicionales excavadas en badlands), y alojamientos de diseño bioclimático exóticos aislados en mitad del desierto. | Corazón del Geoparque de Granada. Custodia el Parque Megalítico de Gorafe (la mayor concentración de dólmenes prehistóricos de España, con más de 240 megalitos integrados en la dehesa árida). Rutas de senderismo geológico por el cañón del río Gor, caminatas fotográficas por el Desierto de Gorafe (paisaje de arcillas rojas brutales tipo Colorado), cicloturismo BTT y observación de estrellas con cielos limpios Starlight.') WHERE codigo_ine = '18086';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas cueva tradicionales excavadas en chimeneas de arcilla acondicionadas para pernocta rústica, y pequeños hostales de interior dedicados al agroturismo de la cerámica artesanal. | Geoparque de Granada, entorno de la Hoya de Guadix. Destaca por las rutas de senderismo geológico e interpretativo que recorren el paisaje arcilloso rojizo de las cárcavas, caminatas hacia los yacimientos arqueológicos de dehesas prehistóricas, rutas cicloturistas llanas de desierto y paseos fotográficos por formaciones de erosión caliza menores.') WHERE codigo_ine = '18167';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Alojamientos cueva tradicionales rehabilitados en barrios históricos colgados, apartamentos rústicos de interior y casas de campo de labranza tradicionales de la vega del río. | Altiplano granentino nororiental. Ofrece rutas de senderismo arqueológico de primer nivel hacia el yacimiento argárico de Castellón Alto (poblado de la Edad del Bronce excavado de forma virgen en la roca de la colina) y la necrópolis ibérica de Tútugi, senderos llanos de cicloturismo familiar entre badlands de yeso y observación astronómica nocturna.') WHERE codigo_ine = '18082';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas cueva de turismo rural unifamiliares con porches de cal, apartamentos rústicos pequeños en un casco histórico dominado por su alcazaba de los siete torreones y cortijos aislados en la dehesa. | Zona norte extrema del altiplano, cuna de los yacimientos paleontológicos clave del Pleistoceno inferior (Venta Micena, Fuente Nueva). Rutas de senderismo de interpretación paleontológica y arqueológica por la cuenca lacustre seca, paseos hacia la piscina natural de Fuencaliente (manantial vivo de agua templada constante todo el año donde nadan peces en libertad), y senderos ganaderos. PROVINCIA: LUGO (Texto Plano Limpio)') WHERE codigo_ine = '18146';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Pallozas tradicionales gallegas rehabilitadas (viviendas de piedra con techumbre circular de paja de centeno), casonas de montaña construidas en mampostería gruesa de pizarra y albergues históricos de paso jacobeo. | Entrada oficial del Camino de Santiago Francés en Galicia, a más de 1.300 metros de altitud en la frontera natural con León. Destaca por el senderismo de alta montaña que conecta con la Sierra de los Ancares, caminatas de interpretación de la arquitectura tradicional pirenaico-gallega, senderos bajo bosques autóctonos de acebos y robles en la umbría, y rutas invernales con raquetas de nieve.') WHERE codigo_ine = '28009';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hoteles boutique rurales en espectaculares monasterios medievales y conventos rehabilitados, casas rurales vinculadas a la viticultura heroica y bodegas de interior, y pazos de granito con amplias fincas agrícolas de frutales. | Vertiente lucense de la Ribeira Sacra baja, confluencia de los ríos Miño, Sil y Cabe. Sede de rutas que conectan senderos entre viñedos escarpados cultivados en bancales verticales. Destaca por las rutas de senderismo que visitan el Monasterio de San Vicente de Pombeiro, cascadas naturales de montaña ocultas en la fronda (Fervenza de Augacaída) y paseos fluviales de ribera.') WHERE codigo_ine = '27041';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Palacetes de interior con fachadas monumentales y escudos heráldicos de piedra, posadas de turismo rural tradicionales vinculadas al Camino de Santiago del Norte y casonas de labranza en las parroquias rurales de su término municipal. | Valle del río Masma, a las faldas de la Sierra de la Toxiza. Ofrece rutas de senderismo kárstico e histórico hacia la espectacular Cova del Rei Cintolo (la cueva más grande de Galicia con galerías de estalactitas y río subterráneo activo, transitable con visitas guiadas de aventura), caminatas botánicas bajo bosques de robles en el paraje de Os Remedios, senderos fluviales y cicloturismo de carretera.') WHERE codigo_ine = '27030';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Pazos de turismo rural de sillería de granito con hórreos tradicionales, casas de labranza bajas vinculadas al agroturismo vinícola de interior y apartamentos rústicos con vistas directas al cañón fluvial. | Orilla occidental del río Miño en la Ribeira Sacra lucense. Sede de una de las estampas de naturaleza e interior más fotogénicas de Galicia: el Cabo do Mundo (colosal meandro cerrado del río Miño rodeado de viñedos en terrazas empinadas). Rutas de senderismo fluvial por el río Asma, paseos botánicos por sotos de castaños centenarios y cicloturismo entre dehesas tradicionales gallegas.') WHERE codigo_ine = '27016';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de piedra tradicionales de mampostería oscura con cubiertas de pizarra, apartamentos rústicos de alta montaña con porche de leña e instalaciones unifamiliares en valles cerrados aislados. | Parque Natural y Reserva de la Biosfera de Os Ancares. Bañado por el río Navia alto. Ofrece rutas de senderismo exigentes de media-alta montaña que exploran bosques atlánticos cerrados y vírgenes de robles rebollos y abedules, caminatas que cruzan su imponente puente medieval de piedra sobre el río caudaloso, pesca truchera tradicional de río limpio y senderos micológicos de otoño.') WHERE codigo_ine = '27034';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de campo agrícolas tradicionales de sillería de granito independientes de interior de viñedo, pazos rurales boutique y pequeños apartamentos turísticos rurales con porche. | En el interior de la Ribeira Sacra lucense meridional, flanqueado por los cañones profundos del río Sil. Sede de rutas de senderismo vertical exigente que transitan hacia miradores colgados literalmente sobre el abismo de roca caliza y granito, como el mirador de Caxide o del Duque. Paseos en los catamaranes que navegan las aguas del cañón fluvial del Sil, caminatas agrícolas y enoturismo.') WHERE codigo_ine = '27059';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: El hotel rural pionero que inauguró el turismo verde en España, casas de aldea tradicionales con gruesos muros de piedra y tejados de pizarra negra, y antiguas rectorales rehabilitadas en mitad del pinar. | Cuna histórica del turismo rural español, integrado en la Reserva de la Biosfera del Río Eo, Oscos y Terras de Burón. Destaca por la emblemática Senda Verde y la Ruta del Agua (recorrido etnográfico que transita entre cascadas, molinos hidráulicos y el impresionante conjunto del mazo de Os Teixois). Ofrece senderos bajo bosques mágicos de robles y castaños, ríos salmoneros de aguas cristalinas y talleres artesanales vivos de cuchillería.') WHERE codigo_ine = '33071';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casonas e hidalguías tradicionales integradas en conjuntos etnográficos de pizarra, apartamentos rurales eco-bioclimáticos y casas de aldea unifamiliares con porches de madera rodeadas de prados verdes. | En el corazón de la comarca de Los Oscos. Un entorno de aislamiento geográfico y naturaleza atlántica virgen. Sede de la célebre ruta de senderismo de la Cascada de Seimeira (un espectacular salto de agua de más de 15 metros en caída libre escondido en un bosque de galería cerrado). Ofrece caminatas que visitan el conjunto etnográfico de Mazonovo, rutas micológicas otoñales, talleres de forja artesana tradicional de navajas y senderos pastoriles.') WHERE codigo_ine = '33062';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Albergues y casas de aldea construidas con la característica mampostería oscura y losas de pizarra, hostales rurales junto a la vía del Camino de Santiago y casonas rústicas de montaña. | Entorno alto del gran Embalse de Salime y cuenca del río Navia. Destaca por las rutas de senderismo fluvial y de media montaña que bordean el embalse, paseos de interpretación histórica y etnográfica (conectando con el Museo Etnográfico de Grandas), caminatas bajo bosques de castaños milenarios y quejigos, piragüismo de interior y rutas cicloturistas de carretera sin tráfico.') WHERE codigo_ine = '33027';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Antiguas casas rectorales recuperadas, casas de aldea unifamiliares con huerto e instalaciones que conservan los hornos tradicionales de piedra y los tejados de pizarra negra. | Integrado en la Reserva de la Biosfera de Los Oscos. Ofrece paseos etnográficos de aislamiento absoluto, rutas de senderismo de la Senda Verde del río Agüeira, caminatas boscosas por los robledales de Mon, rutas micológicas otoñales extremas en sus laderas umbrías y senderos de herradura históricos totalmente aislados del ruido urbano.') WHERE codigo_ine = '33061';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de turismo de aldea con muros anchos aislantes, apartamentos rústicos pequeños en pequeños núcleos de montaña y alojamientos vinculados al Monasterio de Santa María. | Los Oscos orientales, alta montaña asturiana. Destaca por la espectacular ruta de senderismo de la Senda de la Bobia (itinerario de media-alta montaña salpicado de túmulos y monumentos megalíticos prehistóricos integrados en las dehesas altas). Caminatas por el denso bosque atlántico de la Carballeira de Santa Eufemia, senderos micológicos en temporada de otoño y rutas ganaderas. PROVINCIA: HUESCA - COMPLEMENTO DE PIRINEOS (Texto Plano Limpio)') WHERE codigo_ine = '33075';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Palacetes rurales aragoneses con patios porticados rústicos, casas rurales familiares independientes de interior y apartamentos en el casco histórico de la Ribagorza. | Confluencia de los ríos Ésera e Isábena. Rutas de senderismo por los espectaculares estrechos del Congost de Olvena, caminatas hacia los lapiaces de la Sierra de la Puebla, dehesas y senderos micológicos en otoño, piragüismo, vela y deportes de remo en el Embalse de Barasona, y rutas cicloturistas de media montaña. [1]') WHERE codigo_ine = '22117';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hotel rural de lujo en un antiguo monasterio rehabilitado del siglo XVII, casas de turismo rural de mampostería antigua a la sombra del castillo y apartamentos rústicos de cara al río Ara. | Valle del río Ara medio, en la comarca del Sobrarbe. Destaca por las pozas naturales de La Gorga de Boltaña (ideales para el baño estival en aguas limpias de montaña), rutas senderistas que exploran los pueblos abandonados del viejo Sobrarbe y el pirineo meridional, y senderos micológicos otoñales.') WHERE codigo_ine = '22066';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hoteles históricos vinculados a la majestuosa estación internacional ferroviaria, apartamentos de montaña e instalaciones rústicas pirenaicas con estufas de leña. | Valle del Aragón alto, frontera con Francia y paso del Camino de Santiago Aragonés. Rutas de senderismo alpino de alta exigencia hacia el espectacular Ibón de Estanés, paseos de interpretación histórica por los búnkeres de la Línea P ocultos bajo los pinares silvestres, raquetas de nieve invernales y esquí en Astún y Candanchú.') WHERE codigo_ine = '22078';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Apartamentos rústicos orientados al deportista de montaña y aventura, y casas de piedra tradicionales con balcones volados sobre el valle del Ésera. | Valle de Benasque bajo. Capital nacional de los deportes de vuelo libre (parapente y ala delta) por sus corrientes térmicas. Rutas de senderismo por el Congosto de Ventamillo, senderos cicloturistas de montaña de descenso extremo (Enduro BTT), rafting y piragüismo fluvial de aguas bravas en el río Ésera, y senderos micológicos.') WHERE codigo_ine = '22084';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de labranza tradicionales de la Hoya de Huesca, apartamentos rústicos pequeños con vistas a las llanuras de la dehesa baja y posadas. | Faldas de la Sierra de Loarre. Destaca por las rutas de senderismo de corte medieval que rodean el colosal Castillo de Loarre (la fortaleza románica mejor conservada de Europa), senderos micológicos entre pinares silvestres de repoblación viejos, caminatas geológicas en los riscos y observación de aves rapaces.') WHERE codigo_ine = '22149';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales tradicionales con hileras de piedra caliza dorada, apartamentos rústicos adaptados con balcones sobre el valle del río Cinca. | Falda de la mítica peña de Monte Perdido meridional. Famoso por mantener la tradición etnográfica de las nabatas (antiguas almadías de transporte de madera por el río). Rutas de senderismo de media montaña, caminatas por el fondo del valle boscoso y senderos micológicos de pinar y encinar mixtos.') WHERE codigo_ine = '22144';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Pequeñas casas de aldea pirenaicas aisladas de la civilización urbana, y apartamentos rústicos de alta montaña con chimeneas de piedra. | Municipio colgado sobre riscos calizos del Sobrarbe alto. Destaca por la legendaria Ruta de las Ermitas de Tella (tres pequeños templos colgados sobre el vacío en un entorno de dehesas mágicas y misterios de brujería), senderos que ascienden a la Cueva del Oso de las Cavernas y caminatas por cañones calizos.') WHERE codigo_ine = '22227';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de piedra tradicionales de mampostería pirenaica compacta con cubiertas inclinadas de pizarra, y apartamentos rústicos de montaña. | Valle de Benasque medio. Acceso directo al espectacular Valle de Estós. Rutas senderistas de alta montaña que cruzan prados alpinos altos repletos de ganado, senderos que ascienden hacia el Ibón de Batisielles, caminatas micológicas y cascadas de deshielo de invierno. PROVINCIA: ALMERÍA (Texto Plano Limpio)') WHERE codigo_ine = '22200';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hoteles de montaña de estética alpujarreña, grandes villas rurales de alquiler íntegro con chimeneas de leña, complejos de cabañas de madera forestales y casas de turismo de aldea blanqueadas junto al río. | Capital y centro natural de la Alpujarra Almeriense, a las faldas del Parque Nacional de Sierra Nevada. Destaca por la ruta de senderismo de la Hidroeléctrica (espectacular e histórico itinerario llano que transita sobre un canal de agua excavado en los profundos riscos del río Andarax). Ofrece paseos botánicos por el paraje del Nacimiento, rutas de alta montaña alpina, senderos de castañares y quejigales, micología y turismo enológico de altura.') WHERE codigo_ine = '04057';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales de campo independientes aisladas en mitad del llano, apartamentos rústicos de diseño bioclimático orientados al aislamiento desértico, y cortijos agrícolas tradicionales de olivares. | Custodia el Paraje Natural del Desierto de Tabernas (el único desértico propiamente dicho de todo el continente europeo). Ofrece una experiencia única de turismo rural en un entorno de cárcavas y ramales arcillo-arenosos (badlands). Destaca por la ruta de senderismo del Cañón de Alfaro, caminatas geológicas interpretativas por los escenarios del spaghetti western, cicloturismo de desierto y es un destino con certificación Starlight por la nitidez extrema de sus cielos para la observación astronómica nocturna.') WHERE codigo_ine = '04088';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de pueblo tradicionales con fachadas escalonadas de mampostería blanca a la sombra de su castillo nazarí alto, apartamentos turísticos integrados en antiguas instalaciones y estaciones ferroviarias mineras restauradas, y posadas serranas. | Vertiente norte de la Sierra de los Filabres. Punto de partida neurálgico de la Vía Verde del Almanzora (antiguo trazado ferroviario minero ideal para familias y cicloturismo). Ofrece la espectacular ruta de senderismo del sendero de los mineros hacia el poblado abandonado de Las Menas en pleno bosque de montaña, caminatas bajo pinares silvestres silvestres viejos, senderos micológicos de otoño y turismo gastronómico de secaderos tradicionales.') WHERE codigo_ine = '04083';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casonas solariegas de sillería dorada con escudos heráldicos, palacetes de interior con encanto andaluz rústico a las faldas de su monumental castillo del siglo XVI, y cortijos ganaderos aislados en el altiplano. | Parque Natural de Sierra de MaríaLos Vélez. Ofrece espectaculares rutas de senderismo arqueológico hacia la Cueva de los Letreros (donde se descubrió el Índalo prehistórico, Patrimonio de la Humanidad por la UNESCO). Caminatas forestales de interpretación botánica entre inmensas masas boscosas de pinos carrascos y encinares centenarios maduros, senderos micológicos, rutas de raquetas de nieve invernales en las cumbres y dehesas ganaderas.') WHERE codigo_ine = '04098';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales unifamiliares con porches de roca, palacetes agrícolas tradicionales burgueses del siglo XVIII reconvertidos en hoteles de campo en el Valle de Laujar, y posadas alpujarreñas tradicionales. | Corazón de la Alpujarra almeriense, cuenca alta del río Andarax. Ofrece la ruta de senderismo de las Acequias del río, caminatas de media montaña por la Sierra de Gádor, paseos botánicos por dehesas de encinas viejas y almendros que tiñen el paisaje de tonos rosados durante la floración invernal, cicloturismo de carretera familiar y turismo gastronómico.') WHERE codigo_ine = '04046';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de piedra tradicionales de montaña con solanas rústicas de madera, hostales orientados a montañeros y escaladores, y apartamentos rurales pequeños cerca del río Segre. | Valle del río Segre medio, en las estribaciones de la Sierra de Boumort. Capital prepirenaica de la paleontología; destaca por albergar espectaculares yacimientos con nidos y huevos reales de dinosaurio fosilizados (visitas guiadas interpretativas en el paraje natural). Rutas de senderismo de montaña, escuelas de escalada clásica y deportiva en paredes de roca caliza vertical de primer nivel, y senderos micológicos.') WHERE codigo_ine = '25077';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Posadas castellanas integradas en antiguas casonas porticadas de sillería de los siglos XVII y XVIII, hoteles boutique rurales con vistas al casco monumental y apartamentos rústicos unifamiliares con chimenea junto al río Duero. | Centro neurálgico e histórico de la dehesa soriana meridional. Destaca por el sendero fluvial de las Riberas del Duero (caminata plana bajo un maduro bosque de galería de chopos y sauces), rutas de senderismo plano de largo recorrido (GR-14 Senda del Duero), paseos de observación ornitológica en dehesas mixtas de encinas y pinos piñoneros, cicloturismo familiar y micología.') WHERE codigo_ine = '42020';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de turismo rural que conservan la arquitectura popular renacentista y castellana (muros de piedra, entramados rústicos de madera y teja curva), y apartamentos rústicos pequeños que miran a su fotogénica plaza mayor señorial. | Entorno de la cuenca alta del río Morón. Ofrece tranquilas rutas de senderismo llano de interpretación paisajística entre campos de cereal y dehesas agrarias aisladas, caminatas botánicas hacia los encinares del entorno de la ermita, paseos fotográficos de arquitectura rural tradicional y cicloturismo de llanura alta por pistas vecinales sin tráfico.') WHERE codigo_ine = '42123';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de labranza tradicionales bajas de tapial y piedra caliza con corrales recuperados, apartamentos rústicos familiares e íntimos a la sombra de su palacio fortificado de los Mendoza y posadas rurales. | Extremo oriental meridional, bañado por el río Nágima y lindando con el Embalse de Monteagudo. Custodia la dehesa palustre del embalse, declarada Zona ZEPA y de máxima protección ecológica por ser un punto clave del interior peninsular para el turismo ornitológico de aves acuáticas migratorias (ánades, cigüeñuelas, garzas). Rutas de senderismo plano perimetral, caminatas de dehesa agraria y observación astronómica con cielos limpios nocturnos.') WHERE codigo_ine = '42119';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de piedra tradicionales de mampostería oscura con cubiertas de teja árabe vieja, hostales orientados al excursionismo rústico de aislamiento y apartamentos unifamiliares integrados en su casco amurallado de trazado islámico. | En la comarca de la Serranía soriana meridional, transición hacia la provincia de Guadalajara. Ofrece rutas de senderismo exigentes de media montaña que ascienden hacia los altos del cerro del Tarancón, caminatas por los cañones calizos excavados por el río Talegones joven, senderos micológicos de encinar húmedo y sabinares centenarios aislados del ruido urbano.') WHERE codigo_ine = '42155';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de campo agrícolas tradicionales independientes de interior con amplios patios de carruajes, y pequeños apartamentos rurales rústicos de fin de semana adaptados para familias junto al cauce fluvial. | Cuenca del río Duero medio, comarca de las dehesas agrícolas de Almazán. Ofrece rutas de senderismo suave que conectan con los senderos que bordean los pinares de repoblación viejos y dehesas de sabinas albares linderas, paseos de interpretación botánica y fluvial a orillas del Duero, pesca fluvial tradicional de río y cicloturismo de paseo. PROVINCIA: MURCIA - COMARCA DEL NOROESTE E INTERIOR MONTAÑOSO (Texto Plano Limpio)') WHERE codigo_ine = '42030';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Palacetes de turismo de interior integrados en antiguas casonas nobiliarias de sillería dorada con escudos heráldicos en el casco histórico medieval, fincas de agroturismo ganadero y apartamentos rurales familiares con amplios porches rústicos. | Nudo monumental del Noroeste murciano flanqueado por las Sierras de la Sagra y de las Cabras. Custodia el idílico paraje natural de las Fuentes del Marqués (un oasis botánico espectacular repleto de manantiales caudalosos de agua pura de deshielo, riachuelos y cuevas artificiales en mitad de un bosque maduro de encinas y quejigos). Ofrece rutas de senderismo por la Vía Verde del Noroeste (antiguo trazado de tren ideal para familias y cicloturismo), caminatas de media montaña y paseos fotográficos.') WHERE codigo_ine = '30015';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de campo tradicionales de labranza vinculadas al agroturismo arrocero a orillas del agua, apartamentos rústicos con porche de leña y hostales de cañón orientados a los deportes de aventura y aguas bravas. | Bañado por el curso alto del río Segura y su confluencia con el río Mundo. Alberga el Monumento Natural del Cañón de Almadenes (espectacular desfiladero kárstico angosto de paredes de roca caliza verticales de más de 100 metros de altura sobre el Segura). El mayor hub de turismo activo de la región; destaca por la práctica de rafting, hidrospeed y kayak en aguas bravas. Rutas de senderismo ecológico que visitan el Santuario de la Virgen de la Esperanza (excavado directamente en la roca de la gruta caliza fluvial) y paseos ornitológicos en arrozales.') WHERE codigo_ine = '30013';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casonas solariegas de sillería de piedra caliza con espectaculares balconadas de forja tradicional en un casco histórico medieval galardonado (Conjunto Histórico), apartamentos rústicos de montaña unifamiliares con jardín y barbacoa. | Comarca del Noroeste de interior. Ofrece paseos etnográficos de aislamiento y caminatas botánicas, rutas de senderismo que recorren la Sierra de la Peña Rubia con escuelas de escalada clásica y deportiva en paredes de roca, caminatas llanas fluviales por el sendero del río Argos bajo túneles vegetales umbríos de alisos y chopos, y rutas cicloturistas de montaña (BTT).') WHERE codigo_ine = '30017';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de turismo rural y de campo integradas en bodegas e infinitas dehesas vitivinícolas tradicionales, pequeños hostales de interior con encanto y apartamentos rústicos con chimeneas de leña. | Puerta natural del Noroeste, cabecera del río Mula. Destaca por el paraje natural del Salto del Usero (espectacular e imponente poza natural de agua turquesa excavada por la erosión fluvial en la roca caliza en forma de bóveda abierta ideal para el baño veraniego). Ofrece rutas de senderismo por la Sierra de la Silla, paseos agrícolas y enoturismo activo en bodegas amparadas por su Denominación de Origen.') WHERE codigo_ine = '30012';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de labranza tradicionales bajas de tapial y piedra caliza con huertos integrados de frutales de hueso, apartamentos rústicos familiares de fin de semana y alojamientos de montaña pegados al Parque. | Vertiente norte de la Sierra de Espuña caliza. Rutas de senderismo que se adentran en los densos pinares de repoblación viejos de Sierra Espuña, caminatas hacia el paraje de la Fuente de la Higuera, senderos históricos de interpretación del patrimonio morisco (como el castillo de las Paleras y su poblado fortificado enterrado en la naturaleza), y cicloturismo de carretera de gran pendiente. PROVINCIA: GUADALAJARA - SEÑORÍO DE MOLINA Y ALTO TAJO (Texto Plano Limpio)') WHERE codigo_ine = '30032';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casonas solariegas de sillería dorada de la nobleza molinesa con amplios patios interiores rústicos, hoteles de montaña de piedra y madera, y apartamentos rurales con vistas directas a su colosal alcázar medieval. | Eje logístico y natural del Geoparque Mundial de la UNESCO de la Comarca de Molina-Alto Tajo. Destaca por la emblemática ruta de senderismo del Barranco de la Hoz (un desfiladero espectacular de areniscas rojizas esculpido por el río Gallo con agujas de roca caprichosas), senderos que se adentran en el Parque Natural del Alto Tajo, micología otoñal y es una zona de máxima pureza para la observación astronómica nocturna con certificación Starlight.') WHERE codigo_ine = '19190';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Complejos de cabañas forestales de madera mimetizadas bajo el pinar, hostales de alta montaña especializados en pescadores y montañeros, y casas rurales de piedra junto al río con chimeneas rústicas de campana. | En el interior del Parque Natural del Alto Tajo profundo. Sede de rutas de senderismo fluvial escarpadas y espectaculares que transitan entre estrechos cañones calizos, pozas de agua helada turquesa cristalina ideales para el baño y el descanso estival en la Laguna de Taravilla o el Salto de Poveda. Pesca deportiva de trucha con mosca sin muerte en ríos vírgenes limpios, piragüismo y senderos micológicos extremos.') WHERE codigo_ine = '19216';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de montaña de piedra caliza tradicionales con muros anchos aislantes, apartamentos rústicos forestales integrados en pequeños núcleos del valle y albergues de naturaleza fluvial. | Centro geográfico y de interpretación del Parque Natural del Alto Tajo. Alberga el espectacular paraje de la Escaleruela y el Mirador de Zaorejas colgado sobre un meandro vertical cerrado con caídas de roca de más de 150 metros. Rutas de senderismo de cañón de río bajo túneles vegetales umbríos de pinos laricios, quejigos y tejos salvajes, caminatas micológicos y observación astronómica (cielos negros certificados Starlight).') WHERE codigo_ine = '19333';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de turismo rural unifamiliares con porches de roca caliza, apartamentos rústicos de montaña pequeños adaptados para el turismo activo y hostales de montaña. | Parque Natural del Alto Tajo. Custodia el espectacular paraje natural del Salto de Poveda (una imponente cascada natural originada por una antigua presa abandonada sobre el río Tajo rodeada de inmensos pinares silvestres y cortados calizos). Rutas de senderismo hacia el cañón del río Tajo superior, caminatas geológicas interpretativas por el sendero de la Laguna de Taravilla, pesca fluvial tradicional, piragüismo y rutas micológicas.') WHERE codigo_ine = '19223';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de piedra tradicionales de alta montaña con muros anchos aislantes, apartamentos rústicos en valles cerrados de frutales de montaña junto a arroyos trucheros limpios y antiguos pajares rehabilitados. | Alto Tajo oriental, falda del macizo de la Sierra de Albarracín. Destaca por el espectacular y singular paraje geológico de las \"Piedras Picadas\" y la Plaza de Toros Natural (colosales acumulaciones geológicas de formaciones de roca cuarcita esculpidas por el agua). Rutas de senderismo hacia las Aguaspeñas (monumentales formaciones de toba caliza rezumantes de agua cubiertas de musgo), caminatas por hayedos y pinares de pino silvestre, y micología de boletus.') WHERE codigo_ine = '19103';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales de alta montaña de piedra caliza con aislamiento reforzado para el invierno, apartamentos rústicos forestales pegados al bosque y albergues alpinos. | El municipio situado a mayor altitud de toda Castilla-La Mancha (núcleo urbano a casi 1.500 metros), en la Sierra de Albarracín alta y el Alto Tajo oriental. Rutas de senderismo de alta montaña entre pinares boreales de pino silvestre, caminatas hacia los cortados de las umbrías del río Cabrillas, paseos botánicos por el nacimiento de manantiales de agua limpia de montaña, y raquetas de nieve invernales. PROVINCIA: ZARAGOZA (Texto Plano Limpio)') WHERE codigo_ine = '19204';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales tradicionales aragonesas de piedra y adobe de alquiler íntegro con espectaculares porches, hoteles rústicos integrados en el entorno natural del cauce fluvial y apartamentos vacacionales con vistas a las muelas calizas. | Custodia el mundialmente célebre Parque Natural del Monasterio de Piedra y está bañado por el Embalse de La Tranquera. Sede de una de las rutas de senderismo botánico y acuático más espectaculares de Europa (recorrido jalonado por colosales cascadas naturales de agua de toba, como la Cola de Caballo de más de 50 metros, grutas kársticas como la Gruta Iris y lagos interiores de aguas turquesas). Ofrece deportes náuticos sin motor en el embalse (kayak, piragüismo), senderos por las hoces de roca caliza y rutas micológicas.') WHERE codigo_ine = '50192';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Parador de turismo nacional emplazado en un colosal palacio aragonés con fachada monumental de sillería dorada, casas de turismo rural intramuros empedradas con entramados de madera rústica y apartamentos boutique en el casco histórico medieval (Conjunto Histórico). | Comarca de las Cinco Villas septentrional, enclavado sobre una colina escarpada que mira a la Sierra de la Peña. Ofrece rutas de senderismo histórico y natural que rodean sus kilométricas murallas calizas y restos de fortificaciones de frontera, caminatas por los cañones y dehesas agrícolas del río Onsella, rutas cicloturistas de colinas suaves y observación ornitológica de rapaces calizas.') WHERE codigo_ine = '50248';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de campo de interior unifamiliares con porches de roca caliza, hostales rurales de montaña orientados al turismo activo y de aventura, y apartamentos optimizados para escaladores a orillas del río. | Cañón fluvial del río Jalón medio. Capital de la escalada deportiva en roca caliza de primer nivel en Aragón por sus colosales farallones de caliza verticales (como las paredes de Chodes). Sede de las espectaculares rutas de senderismo de las Hoces del Jalón (itinerarios que transitan por estrechos desfiladeros de roca caliza cortados por el río), caminatas geológicas interpretativas y senderos entre huertos tradicionales.') WHERE codigo_ine = '50175';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de turismo de interior integradas en el antiguo barrio alfarero de pescadores a orillas del agua, alojamientos rústicos con vistas directas al meandro fluvial y fincas de agroturismo agrícola de frutales. | Asentado sobre un espectacular giro cerrado del río Ebro bajo la silueta de su colosal castillo templario del siglo XII (el cual corona la roca). El mayor hub de turismo fluvial pasivo de la provincia; destaca por las rutas en kayak y piragüismo fluvial siguiendo el curso tranquilo de la Ribera de l''Ebre, paseos etnográficos para cruzar el río en el histórico \"Pas de Barca\" (transbordador tradicional de madera sin motor propulsado por la corriente), y caminatas de media montaña por la Sierra de Cardó.') WHERE codigo_ine = '43084';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casonas de piedra arenisca roja (pedra roja) tradicionales de montaña con cubiertas de losa, hostales rurales familiares con grandes chimeneas de piedra de leña y apartamentos forestales mimetizados bajo las pinadas. | Conocida como la \"Vila Vermella\", en el corazón del espacio protegido de las Montañas de Prades a casi 1.000 metros de altitud. Destaca por la ruta de senderismo hacia la Roca Foradada (un espectacular arco natural de roca arenisca en mitad del bosque), caminatas botánicas bajo frondosos castañares y robledales, senderos micológicos otoñales extremos (recogida de robellones), y es un destino con certificación astronómica internacional Starlight por la nitidez extrema de sus cielos nocturnos.') WHERE codigo_ine = '43116';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales de alta montaña caliza de la serranía con muros anchos aislantes, apartamentos rústicos forestales pegados al pie del risco de Montsant, y albergues de naturaleza. | Ubicado a las faldas de la espectacular e imponente pared rocosa del Parque Natural de la Sierra de Montsant. Nudo de acceso principal a los senderos históricos conocidos como \"Graus\" (pasos escarpados y estrechos excavados en la roca viva que suben a la alta meseta caliza del parque, como el Grau de la Grallera). Rutas de senderismo de alta dificultad, vías ferratas de montaña de aventura para escaladores, visitas arqueológico-naturales a la Cartuja de Escaladei (rodeada de cipreses centenarios) y observación de estrellas. PROVINCIA: ALBACETE (Texto Plano Limpio)') WHERE codigo_ine = '43096';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Cabañas forestales de madera y piedra perfectamente integradas en la vegetación serrana, casas rurales tradicionales de alta montaña con chimeneas de leña en el núcleo histórico de Riópar Viejo, y hostales de montaña para senderistas. | En el corazón del Parque Natural de los Calares del Mundo y de la Sima (Sierra de Alcaraz). Sede del acceso principal al Monumento Natural del Nacimiento del Río Mundo (célebre por \"Los Chorros\", una espectacular surgencia kárstica donde el agua brota a presión desde una colosal cueva caliza en una pared vertical y cae en cascadas de más de 80 metros). Ofrece senderismo de alta montaña por el Calar del Mundo, rutas micológicas otoñales, avistamiento de fauna y raquetas de nieve en invierno.') WHERE codigo_ine = '02067';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales cueva auténticas (viviendas excavadas directamente en el interior de la montaña caliza con chimeneas exteriores blancas), hoteles boutique rústicos con vistas panorámicas al desfiladero fluvial y apartamentos adaptados para el turismo activo. | Ubicado de forma espectacular en el cañón de la Hoz del Río Júcar. El mayor hub de turismo activo y de aventura de la provincia; destaca por la práctica de rafting, piragüismo, barranquismo, kayak de río y rutas en quads. Ofrece la ruta de senderismo del Sendero del Júcar (caminata plana que bordea el curso del agua bajo imponentes paredes de roca vertical), paseos fotográficos por sus callejones empinados y playas fluviales de agua dulce en verano.') WHERE codigo_ine = '02003';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Complejos de turismo rural de alquiler íntegro con barbacoas y piscinas a orillas del agua, casas rurales de piedra de mampostería tradicional serrana en sus pedanías aisladas y hostales de montaña a las faldas de su castillo medieval. | Valle del río Segura alto y el río Tus, a los pies del Parque Natural de la Sierra de Segura y los Calares. Sede de rutas de senderismo fluvial y de aventura hacia el Estrecho de los Infiernos o la Cerrada de tus (angostos desfiladeros de roca caliza con pasarelas de madera y pozas turquesas heladas aptas para el baño veraniego). Ofrece piragüismo en el Embalse de la Fuensanta, senderos hacia el Calar de la Sima, observación de grandes rapaces y micología.') WHERE codigo_ine = '02086';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Palacetes de turismo de interior integrados en casonas renacentistas de sillería con balcones de forja tradicional en su conjunto monumental, casas de labranza tradicionales con huertos y apartamentos rurales familiares. | Centro logístico e histórico de la Sierra de Alcaraz. Punto de inicio neurálgico de la Vía Verde de la Sierra de Alcaraz (antiguo trazado de tren acondicionado ideal para caminantes y cicloturistas). Ofrece rutas de senderismo hacia el paraje natural de los Estrechos del río Alcaraz, caminatas de interpretación botánica entre pinares y encinares centenarios de media montaña, y rutas gastronómico-rurales.') WHERE codigo_ine = '02004';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de pastores de la alta sierra tradicionales rehabilitadas con muros anchos aislantes, apartamentos rústicos de montaña aislados de la civilización urbana y dehesas de agroturismo ganadero. | Extremo sur de la provincia, enclavado en las estribaciones de la Sierra de las Cabras y la Sierra de Taibilla, lindando con Murcia y Andalucía. Custodia el conjunto de Pinturas Rupestres del Barranco de la Tóbola (Patrimonio de la Humanidad por la UNESCO). Ofrece la espectacular ruta de senderismo del Sendero de los Nogales Centenarios, caminatas de alta montaña hacia el pico Taibilla (2.081 metros, el techo de Albacete), senderos pastoriles trashumantes y observación de estrellas Starlight.') WHERE codigo_ine = '02055';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales unifamiliares integradas intramuros en el interior de una villa medieval fortificada colgada del meandro, y pequeños apartamentos rústicos con vistas directas a los cañones de caliza. | Asentado sobre un monumental y vertiginoso meandro cerrado del río Júcar inferior (el \"anfiteatro del Júcar\"). Ofrece rutas de senderismo fluvial por la Senda de las Huertas, caminatas geológicas interpretativas por los cortes calizos de las hoces que aíslan el pueblo, paseos tranquilos de agroturismo en sus terrazas de cultivo tradicionales, cicloturismo de carretera familiar y ornitología. PROVINCIA: LANZAROTE (Canarias - Datos Curados)') WHERE codigo_ine = '02041';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hoteles boutique rurales integrados en palacetes renacentistas dentro de una villa amurallada intacta, casas de turismo de interior vinculadas a bodegas subterráneas medievales (calados históricos), y fincas de agroturismo vitivinícola. | Capital de la Rioja Alavesa, a las faldas de la Sierra de Cantabria. Ofrece rutas que conectan senderos agrícolas entre interminables mares de viñedos viejos de colina, paseos de observación ornitológica en el Complejo Lagunar de Laguardia (humedales protegidos en zona árida), caminatas de dehesa caliza y senderos que suben a los altos de la sierra calcárea por pasos históricos.') WHERE codigo_ine = '01031';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casonas solariegas castellanas en el casco histórico de las tres culturas, hostales rurales especializados en montañeros y senderistas, y apartamentos rústicos con chimeneas de piedra. | \"La Villa de las Tres Culturas\", a las faldas de la vertiente soriana del Parque Natural del Moncayo. Destaca por la ruta de senderismo del Cañón del Río Val (un desfiladero calizo estrecho con túneles de sauces y cascadas naturales), caminatas botánicas que ascienden al pico de San Miguel (2.314 metros de altitud) entre dehesas altas y hayedos de umbría, rutas invernales de esquí de fondo y micología de boletus.') WHERE codigo_ine = '41011';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de piedra tradicionales de montaña con muros anchos aislantes, apartamentos rústicos de pinar e instalaciones unifamiliares con porche de leña en barrios de la sierra alta. | Eje de la Sierra del Moncayo soriana occidental y la Sierra de Toranzo. Destaca por la ruta de senderismo de la Mina de la Juana (itinerario que recorre antiguas explotaciones mineras integradas en el bosque), caminatas forestales bajo los encinares de dehesa del entorno de la ermita, paseos por hayedos aislados repletos de líquenes en otoño, recolección micológica y cicloturismo.') WHERE codigo_ine = '42134';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de pueblo tradicionales de mampostería oscura caliza junto al cauce fluvial, pequeños alojamientos con encanto a la sombra de su castillo fronterizo. | Custodia el espectacular e imponente Nacimiento del Río Queiles (un Monumento Natural donde el agua brota a borbotones a presión desde una colosal gruta kárstica caliza, siendo el segundo manantial con mayor caudal de Europa). Rutas de senderismo de cañón bajo encinares cantábricos, senderos forestales llanos de interpretación fluvial de ribera y observación de aves rapaces de roca. PROVINCIA: MALLORCA (Islas Baleares - Datos Curados)') WHERE codigo_ine = '42217';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Complejos de casas rurales de piedra y madera situados a orillas del agua, chalets rústicos independientes con embarcaderos privados y pequeños hoteles boutique de interior con encanto y vistas a las cascadas del valle. | En el corazón del Parque Natural de las Lagunas de Ruidera, uno de los oasis de agua dulce más impresionantes del país. Sede de rutas de senderismo plano perimetral que bordean las quince lagunas kársticas interconectadas (como la Laguna del Rey o la Colgada). Destaca por el buceo en agua dulce de máxima visibilidad, rutas guiadas en kayak, piragüismo, senderos de interpretación de formaciones de barreras de toba caliza que crean saltos de agua naturales y cascadas, y paseos ornitológicos.') WHERE codigo_ine = '13902';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Palacetes de turismo de interior integrados en casonas nobiliarias y antiguos conventos del siglo XVI y XVII de sillería dorada con escudos heráldicos en sus patios de columnas de madera, posadas castellanas reales y apartamentos rústicos familiares de gran porte en el casco histórico (Conjunto Histórico). | Capital histórica de la Comarca del Campo de Montiel, entorno literario del Quijote y transición hacia Sierra Morena. Ofrece rutas de senderismo plano de interpretación histórica que siguen cañadas reales ganaderas de largo recorrido, caminatas agrícolas entre dehesas agrarias de encinas centenarias y campos llanos de cereal, rutas cicloturistas llanas de paseo familiar por pistas rurales sin tráfico y paseos arqueológicos hacia el yacimiento prerromano de Jamila.') WHERE codigo_ine = '13093';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hoteles de interior vinculados al termalismo histórico de su célebre balneario medicinal, apartamentos tradicionales de montaña construidos en piedra caliza con chimeneas rústicas de campana y cabañas de madera forestales. | En el interior del Parque Natural del Valle de Alcudia y Sierra Madrona (el techo de Ciudad Real alta). Custodia los Abrigos Rupestres de Peña Escrita (la mayor concentración de pinturas rupestres esquemáticas de la península, Patrimonio de la Humanidad por la UNESCO). Ofrece exigentes rutas de senderismo de alta montaña que ascienden hacia el pico de la Bañuela (1.332 metros de altitud) o el Abulagar bajo densos bosques boreales de robles melojos y madroños centenarios, senderos micológicos otoñales extremos (recogida de níscalos) y avistamiento de ciervos (berrea).') WHERE codigo_ine = '13042';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de campo tradicionales de labranza manchega bajas de tapial y fachadas blancas de cal con antiguas almazaras de aceite recuperadas, posadas de interior rústicas y apartamentos rurales familiares en el llano de la cuenca. | Custodia el Parque Nacional de las Tablas de Daimiel. Espectacular y singular ecosistema palustre de tablas fluviales de interior único en Europa, formado por la confluencia de los ríos Guadiana y Cigüela. Ofrece rutas de senderismo plano de alta protección ecológica a través de pasarelas de madera acondicionadas e islas botánicas interiores (Senda del Agua), paseos de observación ornitológica masiva de aves acuáticas migratorias y palustres (flamencos, garzas, somormujos), piragüismo de baja dificultad en las lunas de agua del entorno, y paseos fotográficos. PROVINCIA: LEÓN (Castilla y León - Datos Curados)') WHERE codigo_ine = '13039';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hoteles de alta montaña de sillería caliza, apartamentos rústicos con vistas a los macizos calcáreos y la mayor concentración de hórreos leoneses y asturianos protegidos de la provincia. | En el corazón del Parque Nacional de los Picos de Europa (Vertiente Leonesa). Punto de partida oficial para la exigente vertiente leonesa de la Ruta del Cares. Destaca por el senderismo al Mirador del Tombo, el ascenso al Macizo Occidental (Torre de Santa María), paseos por el hayedo de Asotín y raquetas de nieve invernales.') WHERE codigo_ine = '24116';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Posadas reales de piedra y pizarra en el casco histórico fortificado (Conjunto Histórico), casas rurales tradicionales sanabresas con chimeneas de piedra de leña y apartamentos de montaña con vistas al valle. | Nexo de acceso principal al Parque Natural del Lago de Sanabria y Sierras de Segundera y de Porto. Custodia el lago de origen glaciar más grande de la península ibérica. Ofrece rutas de senderismo de alta montaña que recorren cañones glaciares (Cañón del Tera, Cañón del Cárdenas), playas fluviales de arena e interior en el lago aptas para el baño y el kayak, senderos micológicos y observación del lobo ibérico.') WHERE codigo_ine = '49166';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales cimentadas sobre roca granítica pura, hostales rurales con encanto enriscados y apartamentos de interior vinculados a una colosal red de bodegas subterráneas medievales excavadas en la roca viva (calados históricos). | Capital de los Arribes del Duero zamoranos (Parque Natural). Ofrece espectaculares rutas de senderismo hacia miradores colgados sobre el vacío (Mirador del Castillo, Mirador de las Escaleras) con vistas verticales al río Duero encajonado en cañones graníticos brutales. Cruceros fluviales en barca por los cañones de agua, dehesas mediterráneas de olivos y viñedos viejos de colina (enoturismo), y ornitología.') WHERE codigo_ine = '49065';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casonas serranas tradicionales construidas con sillería de piedra arenisca rojiza con solanas de madera, hostales de interior y casas de campo independientes rodeadas de pinares y robledales. | En el corazón de la Sierra de la Culebra (Reserva Nacional de Caza). La zona de Europa con mayor densidad y mejor enclave para el avistamiento fotográfico y rastreo guiado del Lobo Ibérico en libertad. Ofrece rutas de senderismo micológico de primer nivel (boletus, níscalos), paseos hacia la playa fluvial de Valparaíso, avistamiento de ciervos (berrea) y dehesas forestales puras bajo cielos negros Starlight. 📂 PROVINCIA: PALENCIA (Castilla y León - Datos Curados)') WHERE codigo_ine = '49262';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casonas solariegas de piedra de cantería con escudos heráldicos, parador nacional de turismo integrado en el bosque de alta montaña, hostales rurales para montañeros y apartamentos de montaña con chimenea. | Centro logístico e histórico del Parque Natural de la Montaña Palentina. Destaca por la ruta de senderismo del Roblón de Estalaya (caminata que visita un roble monumental protegido de más de 800 años de antigüedad), senderos de ascensión hacia picos calizos alpinos (Curavacas, Espigüete), paseos fluviales por el curso alto del río Pisuerga y senderos micológicos de otoño.') WHERE codigo_ine = '34056';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Palacetes de turismo de interior integrados en antiguas casas señoriales, casonas de labranza tradicionales y apartamentos rurales familiares a las orillas del gran embalse. | Puerta natural del Románico Palentino y las hoces calizas, bañado por el Embalse de Aguilar. Custodia la ruta de senderismo del espacio protegido del Espacio Natural de Las Tuerces (espectacular laberinto kárstico de figuras de roca caliza esculpidas por la erosión en mitad del páramo). Ofrece caminatas por el cañón de la Horadada, piragüismo y deportes de remo en el embalse, y paseos botánicos por bosques de galería.') WHERE codigo_ine = '35001';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de montaña de piedra tradicionales con muros anchos aislantes, apartamentos rústicos pequeños de fin de semana para familias y albergues de naturaleza. | Vertiente occidental de la Montaña Palentina, cuenca alta del río Carrión. Custodia el Monumento Natural de las Fuentes Tamáricas (fuentes históricas de la era romana de flujo intermitente). Ofrece rutas de senderismo alpino de alta exigencia hacia el pico Espigüete (colosal pirámide caliza vertical de 2.450 metros), caminatas por el bosque del pinar de Velilla (reliquia de pino silvestre autóctono), senderos micológicos de otoño y lagunas glaciares de montaña (Pozo de las Lomas). PROVINCIA: TENERIFE (Canarias - Datos Curados)') WHERE codigo_ine = '34199';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Palacetes indianos a pie de playa, casonas rurales señoriales con hórreos tradicionales en las parroquias interiores de su término y apartamentos rústicos de costa. | Desembocadura del río Sella y Cuevas del agua de Tito Bustillo (Patrimonio de la Humanidad). Destaca por la espectacular ruta de senderismo costero de los Acantilados de Guadamía (donde se encuentran los bufones o chimeneas de roca que expulsan agua marina a presión), las huellas de dinosaurio en los acantilados de la playa de Vega, y rutas fluviales en kayak.') WHERE codigo_ine = '33056';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Cortijos toledanos de arquitectura tradicional serrana Morena con anchos muros de piedra y cal, complejos de cabañas forestales de madera mimetizadas y casas de campo de aislamiento total. | En el interior de la vertiente norte del Parque Nacional de Cabañeros y la Sierra de la Demanda toledana. Sede de la ruta de senderismo de la Chorrera de los Navalucillos (un espectacular salto de agua natural de montaña de más de 15 metros de caída encajonado en un desfiladero umbrío de la garganta del río Pusa). Ofrece rutas de ascensión al pico Rocigalgo (el techo de la provincia de Toledo con 1.449 metros de altitud), caminatas bajo robledales centenarios y encinares maduros, observación de la berrea del ciervo y grandes aves rapaces (águila imperial).') WHERE codigo_ine = '45113';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Parador de turismo nacional emplazado de forma monumental en el colosal castillo medieval de los condes de Oropesa, casonas solariegas de sillería con patios castellanos de columnas de madera y apartamentos rurales de campiña. | Comarca de la Campana de Oropesa y transición al Valle del Tiétar bajo. Ofrece rutas que conectan con senderos agrícolas y cañadas reales ganaderas de largo recorrido, caminatas llanas de cicloturismo de dehesa agraria familiar de relax entre encinares centenarios donde pasta el ganado, rutas ecuestres y paseos fotográficos de naturaleza de interior. PROVINCIA: GUIPÚZCOA (País Vasco - Datos Curados)') WHERE codigo_ine = '45125';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Caseríos vascos monumentales de sillería de piedra con amplias solanas, hostales rurales especializados en montaña y apartamentos rústicos con vistas a los valles interiores. | Puerta de entrada principal al Parque Natural de Aizkorri-Aratz. Destaca por la emblemática ruta de senderismo de ascensión al Pico Aizkorri (un colosal macizo calizo sagrado para el montañismo vasco), caminatas hacia las campas altas de Urbia donde pasta el ganado, senderos micológicos otoñales extremos bajo frondosos hayedos, y la visita guiada de aventura a las colosales Cuevas de Arrikrutz (galerías kársticas con ríos subterráneos activos).') WHERE codigo_ine = '21014';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Alojamientos de agroturismo integrados en colinas verdes costeras, caseríos tradicionales rehabilitados rodeados de praderas y apartamentos rurales con vistas al estuario. | En el corazón del Geoparque Mundial de la UNESCO de la Costa Vasca. Sede de una de las rutas de senderismo geológico más espectaculares del planeta: la Ruta del Flysch (un sendero litoral que transita sobre colosales acantilados verticales donde la erosión marina ha dejado al descubierto millones de años de historia de la Tierra en finas láminas de roca). Paseos fotográficos por la rasa mareal, kayak en la ría del Urola y senderos botánicos en encinares cantábricos.') WHERE codigo_ine = '21019';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de turismo rural intramuros de mampostería medieval, hoteles boutique integrados en antiguos palacetes señoriales del Maestrazgo con vistas al castillo y masías aisladas en la periferia forestal. | Capital de la indómita comarca de Els Ports. Destaca por las rutas de senderismo que bordean sus kilométricas murallas medievales, paseos arqueológicos hacia las pinturas rupestres de Morella la Vella (Patrimonio de la Humanidad), circuitos de cicloturismo de montaña (BTT), senderos de micología en otoño y observación astronómica con cielos limpios certificados.') WHERE codigo_ine = '12080';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hoteles de interior y posadas rurales vinculados al patrimonio termal tradicional de su balneario, apartamentos turísticos orientados al turismo activo y casas de pueblo rústicas junto al cauce. | Cañón fluvial del Alto Mijares. Célebre por la espectacular surgencia de agua termal de la Fuente de los Baños (una poza natural turquesa donde brota el agua a unos constantes 25 °C todo el año apta para el baño medicinal). Ofrece la espectacular ruta de senderismo de los Estrechos del Río Mijares (desfiladero angosto con paredes de roca de más de 100 metros), escalada deportiva de primer nivel mundial y kayak de aguas bravas.') WHERE codigo_ine = '12079';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales integradas en fincas forestales, complejos orientados al turismo activo y la escalada deportiva, hostales de montaña a las faldas del Parque y apartamentos rústicos. | Principal nudo logístico y de acceso al Parque Natural de Sierra Espuña. Ofrece las rutas de senderismo que recorren el Valle de Leiva, la Senda del Dinosaurio con puentes colgantes, y caminatas geológicas interpretativas por los espectaculares Pozos de la Nieve del siglo XVI integrados en las cumbres alpinas. Destaca por las dehesas forestales de pino carrasco y laricio más densas del levante, y cuenta con certificación Starlight por la excelente calidad de sus cielos nocturnos.') WHERE codigo_ine = '30008';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hoteles boutique rurales en conventos del siglo XVII rehabilitados, cortijos tradicionales andaluces rodeados de dehesas de encinas y casas de cal con teja árabe y chimeneas de leña a los pies de las ruinas de su castillo templario. | Capital y centro neurálgico del Parque Natural Sierra de Aracena y Picos de Aroche. Custodia la impresionante Gruta de las Maravillas (colosal cueva kárstica subterránea de estalactitas, estalagmitas y lagos interiores de agua turquesa cristalina en pleno urbano, transitable con visitas guiadas de aventura). Destaca por el sendero hacia Linares de la Sierra, paseos botánicos por el castañar alto, avistamiento ornitológico y micología de otoño.') WHERE codigo_ine = '22004';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales andaluzas de cal blanca de alquiler íntegro con grandes porches, apartamentos rústicos de montaña orientados al turismo activo y fincas de agroturismo ganadero destinadas a la cría tradicional del cerdo ibérico. | Sierra de Huelva occidental, vigilado de forma monumental por su imponente y fotogénico castillo medieval del siglo XIII intacto. Destaca por las rutas de senderismo de los Senderos del Chanza (itinerarios fluviales que siguen el curso joven del río), caminatas bajo sotos umbríos de castaños viejos, senderos micológicos otoñales de primer nivel (especializados en la seta del gurumelo) y dehesas ganaderas.') WHERE codigo_ine = '21025';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de pueblo tradicionales con fachadas de mampostería antigua y calles empedradas rústicas, apartamentos boutique rurales con encanto en el casco medieval y posadas rurales. | Faldas del cerro de San Cristóbal. Alberga la única mezquita rural del siglo X conservada casi intacta en España, erigida de forma espectacular sobre las ruinas de un castillo en plena cumbre boscosa. Ofrece la ruta de senderismo de ascensión al Pico de San Cristóbal (techo de la zona con miradores panorámicos), paseos botánicos por el sendero del arroyo de la Acebuche, caminatas de dehesa agraria y avistamiento de aves rapaces (colonia de buitre negro). 📂 PROVINCIA: SEVILLA (Andalucía - Datos Curados)') WHERE codigo_ine = '22001';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Cortijos andaluces señoriales de sillería rústica Morena, antiguos monasterios y cartujas del siglo XV reconvertidos en pernoctas exclusivas de interior, y dehesas de agroturismo ganadero y ecuestre. | En pleno Parque Natural de la Sierra Norte de Sevilla (Sierra Morena sevillana). Un paraíso interior dominado por inmensas dehesas de encinas y alcornoques. Ofrece la espectacular ruta de senderismo de las Riberas del Huéznar (bosque de galería fluvial cerrado con cascadas de toba caliza catalogadas como Monumento Natural), paseos por el sendero de las dehesas ganaderas donde pasta el toro bravo, cicloturismo por la Vía Verde de la Sierra Norte y es una reserva de máxima pureza estelar certificada como Reserva Starlight de cielos oscuros negros.') WHERE codigo_ine = '41032';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Complejos de cabañas de madera forestales mimetizadas en el encinar, casas rurales de cal de pueblo serrano unifamiliares con chimenea de leña y apartamentos rústicos junto al cauce fluvial. | Sierra Norte de Sevilla alta. Custodia el espectacular paraje natural del Monumento Natural de las Cascadas del Huéznar (saltos de agua y pozas de agua helada de montaña ideales para el baño y el descanso veraniego) y el Cerro del Hierro (colosal paisaje kárstica caliza calada por una antigua explotación minera romana que simula un laberinto de agujas de roca). Rutas senderistas de aventura geológica, vías ferratas de montaña para escaladores y senderos micológicos de otoño.') WHERE codigo_ine = '41088';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casonas solariegas andaluzas de gran porte y cal blanca en el barrio de la Morería, hostales rurales especializados en turismo ecuestre de dehesa, y cortijos agrícolas aislados entre olivares de pendiente. | Valle del río Galindón, bajo la silueta de su castillo almorávide. Ofrece rutas de senderismo hacia el paraje de la encina de los perros, caminatas de interpretación botánica por sotos de castaños centenarios (el castañar de Constantina es un oasis húmedo singular en la provincia), senderos micológicos micológicos otoñales (setas de cardo, níscalos), y paseos a caballo por cañadas reales ganaderas. PROVINCIA: LLEIDA (Cataluña - Datos Curados)') WHERE codigo_ine = '41033';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hoteles tradicionales de alta montaña construidos con sillería de piedra oscura y cubiertas de pizarra, apartamentos alpinos rústicos con chimeneas de leña y bordas pirenaicas restauradas para alquiler íntegro. | Puerta de entrada oriental principal al Parque Nacional de Aigüestortes y Estany de Sant Maurici. Sede de la mítica ruta senderista que asciende al fotogénico Estany de Sant Maurici vigilado por las colosales agujas de roca caliza de Els Encantats. Destaca por el senderismo de alta montaña (red de refugios Carros de Foc), el ascenso al pico Peguera, rutas invernales de esquí y raquetas de nieve, y avistamiento de fauna alpina (rebecos, urogallos).') WHERE codigo_ine = '25082';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de turismo rural (casas de payés) integradas en pequeñas aldeas tradicionales de montaña, hoteles boutique rurales a orillas del río y alojamientos de ecoturismo orientados a los deportes de aventura. | Capital del Pallars Sobirà, bañado por el río Noguera Pallaresa. La meca internacional absoluta del turismo activo de aguas bravas en España; destaca por la práctica de rafting, hidrospeed, descenso de cañones y kayak fluvial de nivel extremo. Ofrece rutas de senderismo hacia el Parque Natural del Alt Pirineu, caminatas por el Valle de Àssua siguiendo itinerarios pastoriles literarios y senderos micológicos en sus frondosos abetales y pinares de pino negro.') WHERE codigo_ine = '25209';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Antiguas masías fortificadas aisladas en el llano de la cuenca caliza, campamentos ecoturísticos rurales de diseño bioclimático y apartamentos para deportistas de aventura e investigadores del cielo. | Al pie de la Sierra del Montsec. Nudo de acceso principal al colosal y vertiginoso Congost de Montrebei (un impresionante y angosto desfiladero calizo transitable a pie mediante pasarelas excavadas en acantilados verticales de roca sobre el río Noguera Ribagorzana). Destaca por el kayak fluvial de cañón y piragüismo, rutas cicloturistas y es el epicentro nacional del astroturismo y la observación de estrellas al contar con el Parque Astronómico del Montsec (Reserva y Destino Turístico Starlight de máxima pureza).') WHERE codigo_ine = '27015';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Posadas reales en impresionantes casonas pinariegas de sillería de los siglos XVI al XVIII, hoteles de montaña rústicos con acabados en madera de pino de Soria y casas de alquiler íntegro con chimeneas de granito. | En la comarca de Pinares y a los pies del Parque Natural de la Laguna Negra y los Circos Glaciares de Urbión. Sede del acceso principal a la legendaria Laguna Negra de Urbión, un lago de origen glaciar encajonado entre colosales paredes de roca y pinos silvestres. Ofrece rutas de senderismo de alta montaña que ascienden al Pico Urbión (nacimiento del río Duero), paseos botánicos por los pinares continuos más extensos de España, turismo micológico extremo (boletus) y deportes de nieve.') WHERE codigo_ine = '42215';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de turismo rural construidas en piedra caliza con solanas rústicas de madera, hostales orientados al excursionismo y apartamentos rústicos a orillas del río Ucero bajo la sombra de su castillo medieval. | Puerta de entrada oficial meridional al Parque Natural del Cañón del Río Lobos. Célebre por su colosal desfiladero kárstico de calizas rojizas esculpido por el río. Ofrece la ruta de senderismo de la Senda del Río (caminata plana bajo imponentes acantilados verticales de roca donde anidan buitres leonados hasta llegar a la Ermita templaria de San Bartolomé y la cueva Grande), senderos de interpretación geológica y botánica de sabinas albares.') WHERE codigo_ine = '42189';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Grandes chalets rústicos de montaña independientes integrados bajo la sombra forestal, complejos de cabañas de madera pinariegas y apartamentos para montañeros y recolectores. | Flanqueado por la Sierra de Urbión y bañado por el curso más joven e indómito del río Duero, con puentes medievales perfectamente integrados en la naturaleza fluvial. Ofrece exigentes rutas de senderismo de alta montaña hacia los circos glaciares, la ruta de los Senderos del Duero joven entre saltos de agua y rocas musgosas, y es uno de los mayores centros nacionales de micología para la recolección regulada de níscalos y hongos boletus.') WHERE codigo_ine = '42069';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Palacetes rurales barrocos con portadas heráldicas de sillería dorada dentro de un casco histórico monumental amurallado, posadas con encanto de interior y casas de cal de dehesa. | Encaramado sobre un cerro estratégico que domina el Valle del Jalón. Ofrece rutas de senderismo histórico que rodean su monumental arco de triunfo romano de tres vanos, caminatas botánicas por los páramos calizos y dehesas de encinas y sabinas que lo circundan, cicloturismo de carretera sin tráfico y cercanía al nacimiento del río Jalón.') WHERE codigo_ine = '42113';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales tradicionales pinariegas construidas con mampostería oscura y piedra arenisca, apartamentos rústicos de alta montaña con chimeneas de leña y albergues forestales. | Situado en la vertiente soriana de Urbión. Custodia el espectacular paraje natural de Castroviejo (un laberinto geológico de colosales rocas areniscas esculpidas de forma caprichosa por la erosión en mitad de un bosque cerrado). Rutas de senderismo que ascienden al Nacimiento del Río Duero y a la cascada de la Cueva de la Serra, vías ferratas de montaña de aventura y micología de boletus.') WHERE codigo_ine = '42078';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de turismo rural puras que conservan la arquitectura popular medieval (muros de mampostería caliza, entramados de madera de enebro o sabina, barro y chimeneas cónicas de cesto tradicionales), posadas con encanto sobre el risco. | Conjunto Histórico colgado sobre un cerro calizo escarpado que mira al Valle de la Sangre. Custodia la Reserva Natural del Sabinar de Calatañazor (el bosque de Sabinas Albares más denso, maduro y mejor conservado del planeta, con ejemplares milenarios gigantescos). Ofrece la ruta de senderismo del cañón del río Milanos, caminatas geológicas interpretativas y observación ornitológica de rapaces de roca.') WHERE codigo_ine = '42046';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales unifamiliares con porches de roca caliza en pequeños núcleos agrícolas puros aislados en valles de pinos y sabinas, apartamentos rústicos pequeños. | Entorno de pinares y sabinares del interior soriano central. Es reconocido a nivel mundial como Destino Turístico y Cielo Starlight por la absoluta ausencia de contaminación lumínica y la máxima nitidez para la observación de estrellas en la naturaleza. Rutas de senderismo micológico otoñal, caminatas hacia el Manantial de la Fuentona cercano y senderos forestales llanos. PROVINCIA: PONTEVEDRA (Galicia - Datos Curados)') WHERE codigo_ine = '42125';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casonas de piedra mariñanas restauradas, hoteles rurales de costa orientados al turismo de relax marino, apartamentos rústicos con vistas a las marismas y alojamientos de agroturismo tradicional. | Ubicado plenamente en el complejo intermareal Umia-O Grove (sitio Ramsar de alta protección). Destaca por la espectacular ruta de senderismo costero de las Pedras Negras en San Vicente do Mar (pasarelas de madera sobre formaciones caprichosas de granito frente al Atlántico), observación ornitológica masiva de aves acuáticas, playas salvajes de dunas protegidas como Lanzada, y kayak de mar.') WHERE codigo_ine = '36009';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Colosales pazos gallegos señoriales con portalones heráldicos y hórreos gigantes, casas rectorales restauradas en valles fluviales de interior y granjas escuela de agroturismo ganadero. | En el interior de la comarca del Deza, rodeado de frondosos bosques gallegos autóctonos. Destaca por el Monumento Natural de la Fraga de Catasós (un bosque mágico con los castaños y robles de mayor altura de Europa central), rutas de senderismo fluvial a lo largo del río Asneiro, senderos micológicos otoñales extremos y senderos del Camino de Santiago de Invierno.') WHERE codigo_ine = '36024';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Pazos de turismo rural vinculados a la viticultura tradicional y bodegas solariegas, casas de piedra tradicionales integradas en el conjunto histórico y apartamentos litorales de ría. | Corazón de la Comarca del Salnés, bañado por la Ría de Arousa. Ofrece rutas que conectan senderos agrícolas entre interminables viñedos de uva albariño emparrados sobre granito, paseos llanos por las marismas del río Umia (ornitología de primer nivel de ánades y flamencos), y rutas ecuestres de costa. 📂 PROVINCIA: LA CORUÑA (Galicia - Datos Curados)') WHERE codigo_ine = '36004';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de pueblo tradicionales de cal blanca adaptadas con patios rústicos, apartamentos turísticos optimizados para escaladores y senderistas mundiales, y hostales de montaña. | Ubicado de forma espectacular en el cañón calizo de la Hoz del Río Turia (Comarca de Los Serranos). Sede de la célebre y fotogénica ruta de senderismo de los Puentes Colgantes de Chulilla (itinerario que transita por el fondo del desfiladero cruzando colosales pasarelas suspendidas a gran altura sobre el río Turia). Es una de las grandes mecas nacionales de la escalada deportiva en roca caliza vertical, ofrece baños de agua dulce en el Charco Azul, senderos geológicos y rutas micológicas.') WHERE codigo_ine = '46112';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales integradas en su histórico barrio morisco y judío (Conjunto Histórico), antiguos molinos harineros de agua rehabilitados a orillas del agua y posadas rústicas de interior con chimeneas de leña. | Comarca de Los Serranos alta, flanqueada por la Sierra de Javalambre meridional. Sede de la espectacular ruta de senderismo de la Ruta del Agua de Chelva (un sendero plano e ideal para familias que combina túneles excavados en la roca viva, playas fluviales naturales de agua cristalina aptas para el baño veraniego como el Playón, y canales de riego árabes). Caminatas históricas hacia el Acueducto Romano de Peña Cortada, cicloturismo BTT y dehesas forestales bajo cielos oscuros Starlight.') WHERE codigo_ine = '46106';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de labranza tradicionales de la montaña alicantina con muros anchos aislantes, apartamentos rústicos forestales pegados al pinar y masías de agroturismo aisladas entre olivares y almendros de colina. | Comarca de la Marina Alta interior, Valle de Jalón alto. Sede de una de las formaciones geológicas y paisajísticas más espectaculares de la provincia: Es Arcs (un Monumento Natural formado por colosales arcos de roca caliza naturales esculpidos por la erosión en mitad del monte). Rutas de senderismo exigentes de montaña hacia la Peña Alta, paseos arqueológicos hacia el Santuario del Pla de Petracos (pinturas rupestres prehistóricas, Patrimonio de la Humanidad por la UNESCO), senderos botánicos y micología de otoño.') WHERE codigo_ine = '03054';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales unifamiliares distribuidas en los ocho pequeños núcleos o pueblos rurales de piedra compactos que forman el valle (como Benialí o Alpatró), apartamentos rústicos con chimeneas de leña y fincas de agroturismo frutal de montaña. | El valle de los cerezos de la montaña de Alicante. Célebre a nivel nacional por el espectáculo botánico primaveral de la floración masiva del cerezo y sus dehesas agrícolas tradicionales en terrazas de piedra seca (Patrimonio de la Humanidad). Rutas de senderismo hacia la Foradada (colosal agujero natural en la cresta de la roca caliza de la montaña por donde pasa la luz del sol), caminatas micológicas, rutas cicloturistas de carretera de gran pendiente y turismo gastronómico-rural. PROVINCIA: MÁLAGA (Andalucía - Datos Curados)') WHERE codigo_ine = '03136';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Cortijos andaluces señoriales rodeados de olivares y viñedos, hoteles rurales boutique en fincas de agroturismo y antiguas casas de piedra de la serranía rehabilitadas con chimenea de leña. | Centro logístico y natural de la Serranía de Ronda y nexo con la Sierra de las Nieves. Destaca por las rutas de senderismo que descienden al fondo del Tajo de Ronda siguiendo el río Guadalevín, vías ferratas verticales en las paredes del desfiladero, senderos que cruzan encinares maduros de la comarca y rutas enológicas en sus bodegas de interior.') WHERE codigo_ine = '29084';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales integradas en fincas de cítricos y olivos, complejos orientados al turismo activo y de escalada y apartamentos rústicos con vistas a los cañones fluviales. | Entorno del Paraje Natural Desfiladero de los Gaitanes. Co-propietario de la entrada al célebre sendero del Caminito del Rey (espectacular pasarela aérea de madera anclada a 100 metros de altura sobre las paredes verticales del cañón del río Guadalhorce). Destaca por el senderismo geológico, escalada deportiva de primer nivel en El Chorro y kayak en los embalses linderos de Guadalteba.') WHERE codigo_ine = '32025';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Haciendas agrícolas tradicionales andaluzas de gran porte, antiguos molinos de aceite reconvertidos en hoteles con encanto y casas de campo de llanura alta con amplios porches rústicos. | Custodia el espectacular Paraje Natural de El Torcal de Antequera (Patrimonio de la Humanidad por la UNESCO), uno de los paisajes kársticos de roca caliza más impresionantes y fotogénicos de Europa. Rutas senderistas señalizadas (Ruta Verde y Amarilla) entre callejones y figuras de piedra modeladas por la erosión, observación de cabra montés, avistamiento ornitológico de rapaces y rutas históricas hacia los Dólmenes prehistóricos de Antequera.') WHERE codigo_ine = '32002';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hoteles y posadas rurales vinculados al termalismo histórico de su balneario, casas tradicionales blancas de pueblo serrano con patios y apartamentos de montaña independientes. | Puerta de entrada oficial al Parque Nacional Sierra de las Nieves. Sede de rutas de senderismo alpino de alta exigencia que ascienden al pico Torrecilla (el techo del parque con 1.919 metros de altitud). Ofrece paseos botánicos únicos por los misteriosos bosques relictos de Pinsapos (abetos de la era glaciar), caminatas por el sendero de las Cascadas y rutas de observación de fauna de alta montaña.') WHERE codigo_ine = '29090';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de pueblo andalusí de cal impecable con azulejos y macetas de flores, pequeños apartamentos rurales de colina con vistas a la sierra y el mar mediterráneo lejano. | En el interior del Parque Natural de las Sierras de Tejeda, Almijara y Alhama. Sede de la espectacular ruta de senderismo del Río Chíllar (caminata fluvial que transita por el cauce del agua dentro de estrechos cañones calizos conocidos como \"Cahorros\"), senderos micológicos de pinar y quejigal alto en la Axarquía, y rutas ecuestres de montaña.') WHERE codigo_ine = '29053';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Complejos de cabañas forestales de madera, apartamentos rurales adaptados para familias y deportistas de aventura, y casas rurales aisladas junto a pinares. | Entorno de los Embalses del Guadalhorce y el Desfiladero de los Gaitanes. Nudo de acceso principal al recorrido del Caminito del Rey. Destaca por el senderismo botánico por la dehesa de Ardales, caminatas arqueológicas hacia la Cueva de Ardales (pinturas rupestres prehistóricas integradas en la naturaleza), piragüismo, vela y dehesas náuticos sin motor en el embalse del Conde de Guadalhorce. PROVINCIA: LEÓN (Castilla y León - Datos Curados)') WHERE codigo_ine = '32004';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hoteles de alta montaña de sillería caliza y madera de roble, apartamentos rústicos con vistas a los macizos calcáreos y la mayor dehesa de hórreos tradicionales de tipo leonés y asturiano protegidos. | En el corazón del Parque Nacional de los Picos de Europa (Vertiente Leonesa). Punto de partida oficial para la exigente vertiente leonesa de la Ruta del Cares. Destaca por el senderismo al Mirador del Tombo, el ascenso al Macizo Occidental (Torre de Santa María), paseos por el hayedo de Asotín y raquetas de nieve invernales.') WHERE codigo_ine = '24116';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hoteles de montaña con amplias cristaleras y vistas al lago de interior, apartamentos rústicos optimizados para montañeros y albergues fluviales. | Parque Regional de la Montaña de Riaño y Mampodre. Famoso por sus paisajes calcáreos que emulan los fiordos noruegos. Rutas de senderismo alpino de ascensión al Pico Gilbo (el Cervino leonés) y al Yordas, paseos náuticos y rutas de kayak en el Embalse de Riaño, avistamiento de lobo ibérico, cabra montés y ciervos, y rutas de raquetas de nieve.') WHERE codigo_ine = '24130';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales integradas en antiguas colonias e instalaciones mineras industriales del siglo XIX rehabilitadas, apartamentos rústicos para turismo activo. | Valle del río Esla medio. El mayor hub de turismo activo y aguas bravas de la provincia; destaca por el Canal de Aguas Bravas de Sabero (sede de campeonatos de kayak y rafting). Rutas de senderismo por la Senda de las Minas, caminatas exigentes hacia las cumbres calizas de la Peña de la Valdoré, vías ferratas verticales y dehesas de escalada deportiva. PROVINCIA: HUELVA (Andalucía - Datos Curados)') WHERE codigo_ine = '24137';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hoteles boutique rurales en conventos del siglo XVII rehabilitados, cortijos tradicionales andaluces rodeados de dehesas de encinas y casas de cal con teja árabe y chimeneas de leña a los pies de las ruinas de su castillo templario. | Capital y centro neurálgico del Parque Natural Sierra de Aracena y Picos de Aroche. Custodia la impresionante Gruta de las Maravillas (colosal cueva kárstica subterránea de estalactitas, estalagmitas y lagos interiores de agua turquesa cristalina en pleno casco urbano, transitable con visitas guiadas de aventura). Destaca por el sendero hacia Linares de la Sierra, paseos botánicos por el castañar alto, avistamiento ornitológico y micología de dehesa en otoño.') WHERE codigo_ine = '22004';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de turismo de aldea de piedra blanqueada andaluza, apartamentos rústicos con vigas de castaño e históricas posadas con patios empedrados y fuentes de agua viva. | En el interior de la sierra profunda húmeda, declarado Conjunto Histórico. Custodia el espectacular y místico paraje natural de la Peña de Arias Montano (colosal afloramiento de roca caliza rodeado de cuevas naturales y manantiales sagrados que domina todo el valle). Ofrece la ruta de senderismo circular Alájar-Linares de la Sierra a través de caminos tradicionales empedrados entre muros de piedra seca, paseos bajo densos alcornocales y quejigales, y micología.') WHERE codigo_ine = '22003';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales andaluzas de cal blanca de alquiler íntegro con grandes porches, apartamentos rústicos de montaña orientados al turismo activo y fincas de agroturismo ganadero destinadas a la cría tradicional del cerdo ibérico. | Sierra de Huelva occidental, vigilado de forma monumental por su imponente y fotogénico castillo medieval del siglo XIII intacto. Destaca por las rutas de senderismo de los Senderos del Chanza (itinerarios fluviales que siguen el curso joven del río), caminatas bajo sotos umbríos de castaños viejos, senderos micológicos otoñales de primer nivel (especializados en la seta del gurumelo) y dehesas ganaderas.') WHERE codigo_ine = '21025';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casonas de labranza tradicionales de sillería blanqueada y madera, hostales con encanto rústico junto a campos de frutales de montaña y fincas de agroturismo aisladas de la civilización. | En el corazón geográfico y más lluvioso de la sierra baja. Célebre por albergar la Fuente de los Doce Caños en pleno centro del pueblo, de donde brota un colosal manantial vivo de agua pura de deshielo del río Múrtigas. Ofrece la espectacular ruta de senderismo del Sendero de los Llanos (caminata plana bajo túneles vegetales umbríos de castaños y huertas antiguas), senderos forestales de alcornoques y quejigos, y rutas micológicas otoñales.') WHERE codigo_ine = '21033';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de labranza tradicionales de la sierra alta con huertos integrados, apartamentos rústicos con chimeneas de piedra de suelo y alojamientos ecoturísticos rurales de aislamiento fluvial. | Valle del río Múrtigas, en una zona de humedad extrema. Sede de la espectacular e mítica ruta de senderismo del Ribera del Múrtigas (un recorrido plano bajo un bosque de dehesa atlántico denso y cerrado de alisos, sauces y chopos monumentales que emula el norte peninsular). Caminatas por sotos de castaños centenarios, paseos fotográficos de naturaleza interior y senderos ganaderos tradicionales de montaña.') WHERE codigo_ine = '21034';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de campo de penillanura independientes rústicas, antiguos alojamientos agrícolas de dehesa bajos rehabilitados y hostales de interior dedicados al agroturismo gastronómico. | La meca internacional absoluta de la cultura del cerdo ibérico de bellota y la dehesa madura. Ofrece rutas de senderismo de interpretación ambiental por sus interminables campos adehesados de encinas y alcornoques centenarios donde pasta el ganado porcino en libertad (Senda de la Dehesa de Jabugo), paseos fluviales por las riberas linderas del Múrtigas alto, senderos micológicos y observación de estrellas (cielos negros Starlight). PROVINCIA: ALBACETE (Castilla-La Mancha Datos Curados)') WHERE codigo_ine = '21043';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Cabañas forestales de madera y piedra perfectamente integradas en la vegetación serrana, casas rurales tradicionales de alta montaña con chimeneas de leña en el núcleo histórico de Riópar Viejo, y hostales de montaña para senderistas. | En el corazón del Parque Natural de los Calares del Mundo y de la Sima (Sierra de Alcaraz). Sede del acceso principal al Monumento Natural del Nacimiento del Río Mundo (célebre por \"Los Chorros\", una espectacular surgencia kárstica donde el agua brota a presión desde una colosal cueva caliza en una pared vertical y cae en cascadas de más de 80 metros). Ofrece senderismo de alta montaña por el Calar del Mundo, rutas micológicas otoñales, avistamiento de fauna y raquetas de nieve en invierno.') WHERE codigo_ine = '02067';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales cueva auténticas (viviendas excavadas directamente en el interior de la montaña caliza con chimeneas exteriores blancas), hoteles boutique rústicos con vistas panorámicas al desfiladero fluvial y apartamentos adaptados para el turismo activo. | Ubicado de forma espectacular en el cañón de la Hoz del Río Júcar. El mayor hub de turismo activo y de aventura de la provincia; destaca por la práctica de rafting, piragüismo, barranquismo, kayak de río y rutas en quads. Ofrece la ruta de senderismo del Sendero del Júcar (caminata plana que bordea el curso del agua bajo imponentes paredes de roca vertical), paseos fotográficos por sus callejones empinados y playas fluviales de agua dulce en verano.') WHERE codigo_ine = '02003';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Complejos de turismo rural de alquiler íntegro con barbacoas y piscinas a orillas del agua, casas rurales de piedra de mampostería tradicional serrana en sus pedanías aisladas y hostales de montaña a las faldas de su castillo medieval. | Valle del río Segura alto y el río Tus, a los pies del Parque Natural de la Sierra de Segura y los Calares. Sede de rutas de senderismo fluvial y de aventura hacia el Estrecho de los Infiernos o la Cerrada de tus (angostos desfiladeros de roca caliza con pasarelas de madera y pozas turquesas heladas aptas para el baño veraniego). Ofrece piragüismo en el Embalse de la Fuensanta, senderos hacia el Calar de la Sima, observación de grandes rapaces y micología de sierra.') WHERE codigo_ine = '02086';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Palacetes de turismo de interior integrados en casonas renacentistas de sillería con balcones de forja tradicional en su conjunto monumental, casas de labranza tradicionales con huertos y apartamentos rurales familiares. | Centro logístico e histórico de la Sierra de Alcaraz. Punto de inicio neurálgico de la Vía Verde de la Sierra de Alcaraz (antiguo trazado de tren acondicionado ideal para caminantes y cicloturistas). Ofrece rutas de senderismo hacia el paraje natural de los Estrechos del río Alcaraz, caminatas de interpretación botánica entre pinares y encinares centenarios de media montaña, y rutas gastronómico-rurales.') WHERE codigo_ine = '02004';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de pastores de la alta sierra tradicionales rehabilitadas con muros anchos aislantes, apartamentos rústicos de montaña aislados de la civilización urbana y dehesas de agroturismo ganadero. | Extremo sur de la provincia, enclavado en las estribaciones de la Sierra de las Cabras y la Sierra de Taibilla, lindando con Murcia y Andalucía. Custodia el conjunto de Pinturas Rupestres del Barranco de la Tóbola (Patrimonio de la Humanidad por la UNESCO). Ofrece la espectacular ruta de senderismo del Sendero de los Nogales Centenarios, caminatas de alta montaña hacia el pico Taibilla (2.081 metros, el techo de Albacete), senderos pastoriles trashumantes y observación de estrellas Starlight. PROVINCIA: MALLORCA (Islas Baleares - Datos Curados)') WHERE codigo_ine = '02055';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casonas solariegas de cantería integradas dentro de un casco histórico medieval fortificado intacto (Conjunto Histórico), hostales rústicos de montaña con chimeneas tradicionales y casas de alquiler íntegro. | Vertiente sur de la Ribeira Sacra alta, vigilado por su imponente fortaleza del siglo XIV. Destaca por las rutas de senderismo de los Bosques de Caldelas (itinerarios que transitan bajo sotos mágicos de castaños y robles autóctonos), paseos fluviales por el sendero del río Edo, senderos micológicos de primer nivel y punto de partida hacia los catamaranes que navegan las aguas interiores del Sil.') WHERE codigo_ine = '34003';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hoteles boutique rurales en antiguas fábricas de curtidos restauradas junto al cauce, casonas hidalgas gallegas con patios empedrados y apartamentos rústicos con encanto arquitectónico. | Bañado por el río Arnoia (Reserva de la Biosfera de las Áreas de Allariz). Sede del sendero fluvial del Arnoia, un bosque de galería impecable con molinos harineros y aceñas medievales de granito. Ofrece rutas de senderismo ecológico hacia el Eco-espacio de O Rexo (diseñado por Agustín Ibarrola fusionando arte y naturaleza en el campo), senderos tradicionales ganaderos y cicloturismo de baja dificultad.') WHERE codigo_ine = '34002';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Pazos de turismo rural vinculados a la viticultura tradicional de la Comarca del Ribeiro, casas de piedra en el casco histórico judío y fincas agrícolas con encanto. | Confluencia de los ríos Avia y Miño. Sede de rutas que conectan senderos agrícolas entre viñedos de uva treixadura cultivados en bancales escarpados de interior. Destaca por las Pozas termales de Prexigueiro (instalaciones termales rodeadas de densos bosques caducifolios), paseos ornitológicos en el embalse de Castrelo de Miño (piragüismo, kayak de interior) y caminatas fluviales. [1]') WHERE codigo_ine = '32069';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Cortijos toledanos de arquitectura tradicional serrana con anchos muros de piedra y cal, complejos de cabañas forestales de madera mimetizadas en el entorno e instalaciones de campo de aislamiento total. | En el interior de la vertiente norte del Parque Nacional de Cabañeros y los Montes de Toledo. Sede de la célebre ruta de senderismo de la Chorrera de los Navalucillos (un espectacular salto de agua natural de montaña de más de 15 metros de caída encajonado en un desfiladero umbrío de la garganta del río Pusa). Ofrece rutas de ascensión al pico Rocigalgo (el techo de la provincia de Toledo con 1.449 metros de altitud), caminatas bajo robledales centenarios y encinares maduros, observación de la berrea del ciervo y grandes aves rapaces (águila imperial).') WHERE codigo_ine = '45113';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Parador de turismo nacional emplazado de forma monumental en el colosal castillo medieval de los condes de Oropesa, casonas solariegas de sillería con patios castellanos de columnas de madera y apartamentos rurales de campiña. | Comarca de la Campana de Oropesa y transición al Valle del Tiétar bajo. Ofrece rutas que conectan con senderos agrícolas y cañadas reales ganaderas de largo recorrido, caminatas llanas de cicloturismo de dehesa agraria familiar de relax entre encinares centenarios donde pasta el ganado, rutas ecuestres y paseos fotográficos de naturaleza de interior.') WHERE codigo_ine = '45125';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de montaña de piedra tradicionales con gruesos muros aislantes, hostales rurales orientados al excursionismo y chalets rústicos de montaña independientes con chimenea de leña rodeados de naturaleza. | En el corazón de la Sierra de San Vicente (el pulmón verde del norte de Toledo). Destaca por las rutas de senderismo hacia el pico de Cruces, caminatas botánicas bajo los espectaculares y frondosos bosques de castaños centenarios (el castañar de El Real es único en la provincia), senderos micológicos micológicos otoñales (recogida de setas y castañas), paseos hacia las ruinas del convento del Piélago y dehesas forestales puras.') WHERE codigo_ine = '45144';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Cabañas de madera forestales mimetizadas bajo densos encinares, casas rurales de piedra tradicionales serranas unifamiliares con porches y alojamientos de montaña orientados al turismo activo. | En pleno macizo de los Montes de Toledo altos, a más de 900 metros de altitud. Rutas de senderismo de media y alta montaña que exploran bosques mediterráneos aromáticos de encinas, quejigos y madroños centenarios, caminatas fluviales por el sendero del arroyo de la Dehesa con manantiales limpios de montaña, senderos micológicos otoñales extremos, avistamiento de ciervos (berrea) y rutas cicloturistas de montaña (BTT).') WHERE codigo_ine = '45153';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de campo de interior unifamiliares independientes con amplios porches de roca caliza, y pequeños apartamentos rurales rústicos de fin de semana en un valle resguardado de montaña. | Valle interior de los Montes de Toledo, lindando con el Parque Nacional de Cabañeros nororiental. Ofrece las rutas de senderismo arqueológico e histórico hacia el yacimiento arqueológico medieval del Malamoneda (con su torre fortificada, castillo enterrado en la naturaleza y necrópolis excavada en la roca viva), caminatas geológicas interpretativas por los barrancos de cuarcita, y observación astronómica de cielos negros. PROVINCIA: ZAMORA (Castilla y León - Datos Curados)') WHERE codigo_ine = '45075';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Posadas reales de piedra y pizarra en su casco histórico fortificado (Conjunto Histórico), casas rurales tradicionales sanabresas con grandes chimeneas de piedra de leña y apartamentos de montaña con corredores de madera. | Nexo de acceso principal al Parque Natural del Lago de Sanabria y Sierras de Segundera y de Porto. Custodia el lago de origen glaciar más grande de la península ibérica. Ofrece espectaculares rutas de senderismo de alta montaña que recorren profundos cañones glaciares (Cañón del Tera, Cañón del Cárdenas), playas fluviales de arena e interior en el lago aptas para el baño y el kayak, senderos micológicos de otoño y dehesas de montaña.') WHERE codigo_ine = '49166';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales cimentadas sobre roca granítica pura, hostales rurales con encanto enriscados y apartamentos de interior vinculados a una colosal red de bodegas subterráneas medievales excavadas en la roca viva (calados históricos). | Capital de los Arribes del Duero zamoranos (Parque Natural). Ofrece espectaculares rutas de senderismo hacia miradores colgados sobre el vacío (Mirador del Castillo, Mirador de las Escaleras) con vistas verticales al río Duero encajonado en cañones graníticos brutales. Cruceros fluviales en barca por los cañones de agua, dehesas mediterráneas de olivos y viñedos viejos de colina (enoturismo), y ornitología.') WHERE codigo_ine = '49065';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casonas serranas tradicionales construidas con sillería de piedra arenisca rojiza con solanas de madera, hostales de interior y casas de campo independientes rodeadas de pinares y robledales. | En el corazón de la Sierra de la Culebra (Reserva Nacional de Caza). La zona de Europa con mayor densidad y mejor enclave para el avistamiento fotográfico y rastreo guiado del Lobo Ibérico en libertad. Ofrece rutas de senderismo micológico de primer nivel (boletus, níscalos), paseos hacia la playa fluvial de Valparaíso, avistamiento de ciervos (berrea) y dehesas forestales puras bajo cielos negros Starlight.') WHERE codigo_ine = '49262';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales de piedra de mampostería tradicional integradas en el entorno natural, cabañas forestales de madera junto al río y apartamentos turísticos rurales orientados al turismo activo familiar. | Integrado plenamente en el Parque Natural del Lago de Sanabria. Bañado por el río Tera joven. Sede de rutas de senderismo suave perimetral que bordean el lago y conectan con pequeñas pozas y playas fluviales (Playa de los Enanos, Playa Custa Llago). Ofrece senderos botánicos bajo densos robledales y castañares húmedos, paseos en piragua, cicloturismo de montaña y rutas de micología de pinar.') WHERE codigo_ine = '49085';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de campo agrícolas tradicionales bajas de tapial y piedra de interior, apartamentos rústicos con chimeneas y dehesas de agroturismo ganadero. | Piedemonte oriental de la Sierra de la Culebra, Camino de Santiago de la Plata (Camino Sanabrés). Ofrece rutas de senderismo plano de interpretación ambiental entre encinares centenarios y brezales, caminatas que se adentran en las lomas forestales linderas para el avistamiento de fauna ibérica silvestre (ciervo, corzo, lobo), cicloturismo de paseo familiar y observación de estrellas con cielos negros limpios. PROVINCIA: BADAJOZ (Extremadura - Datos Curados)') WHERE codigo_ine = '49214';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Cortijos extremeños tradicionales restaurados con anchos muros de cal, dehesas ganaderas destinadas al agroturismo, complejos de cabañas de madera de interior y apartamentos rústicos a las faldas de su castillo fortificado medieval. | En pleno corazón de la Reserva de la Biosfera de La Siberia Extremeña. Flanqueado por la Reserva Nacional de Caza de Cíjara. Ofrece espectaculares rutas de senderismo y avistamiento ornitológico por los farallones de cuarcita y riscos del embalse de Cíjar, caminatas entre dehesas maduras de encinas y alcornoques, rutas micológicas otoñales, observación de la berrea del ciervo y observación astronómica nocturna bajo cielos negros certificados (Starlight).') WHERE codigo_ine = '06063';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Palacetes de turismo de interior integrados en casonas nobiliarias señoriales con influencia lusoextremeña, hostales rurales con encanto en el casco amurallado gótico e históricas fincas agrícolas de dehesa. | Comarca de Llanos de Olivenza, lindando con la ribera del Guadiana y las aguas transfronterizas del Gran Lago de Alqueva. Ofrece la ruta de senderismo de los Alquevares (itinerarios que recorren dehesas ganaderas y campos llanos de cereal que miran al embalse), paseos fluviales por el embarcadero de Villarreal con la práctica de deportes náuticos sin motor (kayak, piragüismo, vela de interior), senderos ecuestres y cicloturismo de paseo familiar.') WHERE codigo_ine = '06095';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casonas solariegas bajas de dehesa de cal blanca unifamiliares con patios extremeños tradicionales llenos de fuentes y azulejos, apartamentos rústicos de montaña integrados en su castillo templario que aloja una plaza de toros interior, y fincas ganaderas dedicadas a la cría tradicional del cerdo ibérico de bellota. | Enclavado en las estribaciones de la Sierra Suroeste húmeda (Sierra Morena pacense). Meca del agroturismo ibérico; destaca por las rutas de interpretación ambiental por sus interminables e inmensos dehesas de encinas y alcornoques centenarios donde pasta el ganado en libertad. Rutas de senderismo plano de baja dificultad por antiguos caminos ganaderos, caminatas hacia los valles de olivos de pendiente y senderos micológicos de otoño.') WHERE codigo_ine = '06050';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Complejos de casas rurales y apartamentos situados a orillas del agua, chalets de campo rústicos independientes con barbacoa y porches de roca caliza, y hostales de interior orientados al turismo náutico familiar. | Bañado por el colosal Embalse de Orellana. Sede de la Playa de Orellana (\"Costa Dulce\"), la primera playa fluvial de interior de España en conseguir el galardón internacional de Bandera Azul por la pureza de sus aguas cristalinas. Ofrece rutas de senderismo plano perimetral homologado (Senda del embalse), observación ornitológica de primer nivel en el humedal de la Zona ZEPA (aves acuáticas y palustres migratorias), windsurf, piragüismo y pesca deportiva limpia.') WHERE codigo_ine = '06097';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hostales rurales especializados en turismo de paso por la Vía de la Plata, casas de labranza tradicionales de montaña baja con chimeneas de leña, y cortijos ganaderos aislados en dehesas forestales. | Puerto de las Marismas, en pleno paso de la histórica Vía de la Plata y de la Sierra de Tentudía. Ofrece rutas de senderismo e interpretación ambiental e histórica que ascienden hacia el Monasterio de Tentudía (el punto más alto de la provincia a 1.100 metros de altitud), caminatas por dehesas ganaderas maduras bajo robles melojos y encinas viejas, senderos micológicos de otoño y turismo gastronómico de secaderos tradicionales. PROVINCIA: ZARAGOZA - ZONA MONCAYO E INTERIOR (Texto Plano Limpio)') WHERE codigo_ine = '06085';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Parador de turismo nacional emplazado en un colosal palacio aragonés con fachada monumental de sillería dorada, casas de turismo rural intramuros empedradas con entramados de madera rústica y apartamentos boutique en el casco histórico medieval (Conjunto Histórico). | Comarca de las Cinco Villas septentrional, enclavado sobre una colina escarpada que mira a la Sierra de la Peña. Ofrece rutas de senderismo histórico y natural que rodean sus kilométricas murallas calizas y restos de fortificaciones de frontera, caminatas por los cañones y dehesas agrícolas del río Onsella, rutas cicloturistas de colinas suaves y observación ornitológica de rapaces calizas.') WHERE codigo_ine = '50248';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de campo de interior unifamiliares con porches de roca caliza, hostales rurales de montaña orientados al turismo activo y de aventura, y apartamentos optimizados para escaladores a orillas del río. | Cañón fluvial del río Jalón medio. Capital de la escalada deportiva en roca caliza de primer nivel en Aragón por sus colosales farallones de caliza verticales (como las paredes de Chodes). Sede de las espectaculares rutas de senderismo de las Hoces del Jalón (itinerarios que transitan por estrechos desfiladeros de roca caliza cortados por el río), caminatas geológicas interpretativas y senderos entre huertos tradicionales.') WHERE codigo_ine = '50175';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casonas hidalgas fortificadas y palacios rurales de sillería gruesa, posadas de montaña orientadas a montañeros y cabañas pasiegas-burgalesas rehabilitadas en las pedanías del norte. | Comarca de Las Merindades, frontera con los Valles Pasiegos. Destaca por el Monumento Natural de Ojo Guareña (colosal complejo de cuevas kársticas con ermita rupestre y galerías subterráneas). Ofrece rutas de alta montaña hacia el macizo de Castro Valnera, senderos bajo frondosos hayedos de las faldas cantábricas, y raquetas de nieve en invierno.') WHERE codigo_ine = '09124';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de montaña de piedra roja caliza y teja curva tradicionales de la sierra alta, apartamentos rústicos con chimenea de leña y albergues de naturaleza forestal. | Corazón de la Sierra de la Demanda. Nudo de la Vía Verde de la Demanda (antiguo trazado ferroviario minero ideal para senderistas y cicloturistas). Rutas de ascensión alpina al Pico Mencilla y al San Millán (techo de la provincia con 2.131 metros), senderos rodeados de acebales protegidos, robledales centenarios y el embalse del Arlanzón.') WHERE codigo_ine = '09266';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de turismo rural intramuros con patios de mampostería antigua, apartamentos turísticos integrados en el casco histórico señorial y hostales de interior. | Eje del Parque Natural de Montes Obarenes-San Zadornil. Sede del Sendero del Desfiladero de la Horadada (colosal garganta cortada por el río Oca). Ofrece rutas de senderismo botánico entre encinares atlánticos y mediterráneos mixtos, paseos fluviales por canales medievales de agua y micología forestal de otoño.') WHERE codigo_ine = '09238';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Posadas de alta montaña construidas con vigas de pino de la Demanda y piedra caliza, casas rurales unifamiliares de pinar aisladas en las alturas y alojamientos para excursionistas. | Custodia el Parque Natural de las Lagunas Glaciares de Neila. Espectaculares rutas de senderismo de alta montaña que recorren el borde de los circos glaciares (Laguna Negra, Laguna Larga, Laguna de la Cascada), senderos micológicos de pinar húmedo alto (boletus), observación astronómica certificada Starlight y dehesas de pastores trashumantes.') WHERE codigo_ine = '09232';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hostales rurales especializados en micología y turismo activo, cabañas de madera forestales mimetizadas en la pinada y grandes casas de piedra de cantería burgalesa. | Comarca de Pinares, falda meridional de la Sierra de la Demanda. Rutas de senderismo al Comunero de Revenga (necrópolis medieval tallada en roca viva rodeada de robles centenarios), caminatas hacia las Lagunas de Neila, recolección masiva de hongos boletus y níscalos en pinares silvestres infinitos y senderos fluviales del río Arlanzón joven. PROVINCIA: MURCIA - VALLE DE RICOTE E INTERIOR (Texto Plano Limpio)') WHERE codigo_ine = '09289';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casonas solariegas de piedra de cantería con escudos heráldicos, parador nacional de turismo integrado en el bosque de alta montaña, hostales rurales para montañeros y apartamentos de montaña con chimenea. | Centro logístico e histórico del Parque Natural de la Montaña Palentina. Destaca por la ruta de senderismo del Roblón de Estalaya (caminata que visita un roble monumental protegido de más de 800 años de antigüedad), senderos de ascensión hacia picos calizos alpinos (Curavacas, Espigüete), paseos fluviales por el curso alto del río Pisuerga, dehesas y senderos micológicos de otoño.') WHERE codigo_ine = '34056';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Palacetes de turismo de interior integrados en antiguas casas señoriales, casonas de labranza tradicionales y apartamentos rurales familiares a las orillas del gran embalse. | Puerta natural del Románico Palentino y las hoces calizas, bañado por el Embalse de Aguilar. Custodia la ruta de senderismo del espacio protegido del Espacio Natural de Las Tuerces (espectacular laberinto kárstico de figuras de roca caliza esculpidas por la erosión en mitad del páramo). Ofrece caminatas por el cañón de la Horadada, piragüismo y deportes de remo en el embalse, y paseos botánicos por bosques de galería.') WHERE codigo_ine = '35001';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de montaña de piedra tradicionales con muros anchos aislantes, apartamentos rústicos pequeños de fin de semana para familias y albergues de naturaleza. | Vertiente occidental de la Montaña Palentina, cuenca alta del río Carrión. Custodia el Monumento Natural de las Fuentes Tamáricas (fuentes históricas de la era romana de flujo intermitente). Ofrece rutas de senderismo alpino de alta exigencia hacia el pico Espigüete (colosal pirámide caliza vertical de 2.450 metros), caminatas por el bosque del pinar de Velilla (reliquia de pino silvestre原 ), senderos micológicos de otoño y lagunas glaciares de montaña (Pozo de las Lomas). 生') WHERE codigo_ine = '34199';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales de piedra integradas en antiguas dependencias de colonias mineras rehabilitadas para pernocta rústica, hostales de montaña e instalaciones familiares. | Vertiente oriental de la Montaña Palentina, comarca del valle de Santullán. Destaca por el espectacular e imponente soto del Hayedo de la Pedrosa y de Cillamayor. Ofrece rutas de senderismo e interpretación histórica minera (Senda del carbón), caminatas bajo túneles vegetales umbríos de hayas y robles caducifolios, senderos micológicos otoñales extremos, rutas cicloturistas y observación de fauna cantábrica (territorio de paso de oso pardo). PROVINCIA: ALICANTE (Comunidad Valenciana Datos Curados)') WHERE codigo_ine = '34027';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de labranza tradicionales de la montaña alicantina con muros anchos aislantes, apartamentos rústicos forestales pegados al pinar y masías de agroturismo aisladas entre olivares y almendros de colina. | Comarca de la Marina Alta interior, Valle de Jalón alto. Sede de una de las formaciones geológicas y paisajísticas más espectaculares de la provincia: Es Arcs (un Monumento Natural formado por colosales arcos de roca caliza naturales esculpidos por la erosión en mitad del monte). Rutas de senderismo exigentes de montaña hacia la Peña Alta, paseos arqueológicos hacia el Santuario del Pla de Petracos (pinturas rupestres prehistóricas, Patrimonio de la Humanidad por la UNESCO), senderos botánicos y micología de otoño.') WHERE codigo_ine = '03054';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales unifamiliares distribuidas en los ocho pequeños núcleos o pueblos rurales de piedra compactos que forman el valle (como Benialí o Alpatró), apartamentos rústicos con chimeneas de leña y fincas de agroturismo frutal de montaña. | El valle de los cerezos de la montaña de Alicante. Célebre a nivel nacional por el espectáculo botánico primaveral de la floración masiva del cerezo y sus dehesas agrícolas tradicionales en terrazas de piedra seca (Patrimonio de la Humanidad). Rutas de senderismo hacia la Foradada (colosal agujero natural en la cresta de la roca caliza de la montaña por donde pasa la luz del sol), caminatas micológicas, rutas cicloturistas de carretera de gran pendiente y turismo gastronómico-rural.') WHERE codigo_ine = '03136';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales andaluzas de cal blanca de alquiler íntegro integradas a las faldas de la peña, apartamentos rústicos de montaña con chimenea de leña y pequeños hostales rurales de turismo activo. | Custodia el Parque Natural de la Sierra de Castril. Sede de la célebre y fotogénica ruta de senderismo de las Pasarelas del Río Castril (un espectacular sendero de pasarelas de madera ancladas sobre la pared de roca caliza vertical del desfiladero fluvial). Ofrece caminatas exigentes hacia el Nacimiento del Río Castril, exploración de cuevas kársticas como la Cueva del Doncel, senderos micológicos en sus pinares de montaña y avistamiento de buitres leonados y quebrantahuesos.') WHERE codigo_ine = '18046';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de campo tradicionales granadinas con huerto, hoteles de montaña rústicos y alojamientos de esquí en los núcleos altos de su término municipal. | Estribaciones occidentales de Sierra Nevada. Sede de una de las rutas de senderismo de aventura más espectaculares y transitadas de Andalucía: Los Cahorros del Río Monachil (desfiladero calizo angosto transitable mediante colosales puentes colgantes, cascadas y pasos de roca estrechos). Escalada deportiva vertical en caliza, senderos de robledales y cicloturismo de carretera exigente.') WHERE codigo_ine = '18134';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas cueva auténticas excavadas directamente en la arcilla (alojamientos bioclimáticos subterráneos tradicionales con chimeneas blancas exteriores que mantienen temperatura constante todo el año), palacetes señoriales andaluces rústicos en el casco histórico y cortijos agrícolas aislados en la hoya. | Integrado en el Geoparque de Granada (UNESCO). Ofrece una experiencia única de turismo rural en un paisaje de cárcavas arcillosas de aspecto lunar. Rutas de senderismo geológico por los cañones de arcilla, cicloturismo por pistas áridas, rutas fotográficas al atardecer en el Mirador del Fin del Mundo y cercanía al Parque Natural de la Sierra de Baza.') WHERE codigo_ine = '18089';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Posadas y hoteles rurales vinculados al termalismo histórico y medicinal, casas tradicionalmente blancas de pueblo serrano con fuentes de agua fresca en sus patios rústicos y apartamentos de montaña. | Puerta occidental de la Alpujarra alta y Parque Natural de Sierra Nevada. Destaca por la ruta senderista del Sendero de los Pescadores, caminatas fluviales junto al río Lanjarón, paseos botánicos por el Parque del Salado y el Bosque de Tello (repleto de castaños e hilos de agua de deshielo), rutas micológicas y senderos ecuestres. PROVINCIA: LEÓN - VALLES OCCIDENTAL Y GLACIARES (Texto Plano Limpio)') WHERE codigo_ine = '18116';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Caseríos aislados de piedra y pradera ganadera de la comarca de Xareta, apartamentos rústicos familiares e íntimos rodeados de bosques mágicos de castaños. | Célebre por su monumental Cueva de las Brujas (Sorginen Lezea), un colosal túnel kárstico natural horadado por el regato del Infierno. Destaca por el Sendero de las Cuevas (que conecta peatonalmente con Urdax y las cuevas de Sara en Francia mediante un camino marcado por un caballo azul), senderismo de castañares, dehesas atlánticas y mitología.') WHERE codigo_ine = '31264';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales y caseríos típicos del Valle de Larraun con grandes solanas de madera orientadas al sur, hoteles de montaña especializados en cicloturismo de interior. | Falda de la impresionante Sierra de Aralar. Eje central de la Vía Verde del Plazaola (antiguo trazado de tren reconvertido para caminantes y ciclistas). Rutas de senderismo forestal hacia el Nacedero del río Iribas, caminatas micológicas entre hayedos brumosos, dehesas ganaderas alpinas de oveja latxa y cuevas calizas como Mendukilo. PROVINCIA: GIRONA (Cataluña - Datos Curados)') WHERE codigo_ine = '33009';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Auténticas casas de payés vinculadas al agroturismo tradicional, alojamientos rurales familiares con huerto ecológico y granjas rodeadas de campos volcánicos. | En el corazón del Parque Natural de la Zona Volcánica de la Garrotxa. Sede de rutas de senderismo directas al Volcán de Santa Margarida (con su ermita en el centro del cráter) y al Volcán del Croscat. Ofrece paseos icónicos por el hayedo de la Fageda d''en Jordà (crecido de forma única sobre una colada de lava), rutas ecuestres de colina y micología.') WHERE codigo_ine = '17184';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hostales tradicionales de alta montaña de piedra vista y madera caliza, casas rústicas de alquiler íntegro con grandes chimeneas y estufas de leña. | Pueblo pirenaico de alta montaña. Destaca por la exigente ruta de senderismo hacia el nacimiento del río Ter en el circo glaciar de Ulldeter, caminatas alpinas fronterizas con Francia, turismo de nieve invernal en la estación de Vallter 2000 y recolección micológica extrema en bosques de pino negro.') WHERE codigo_ine = '18015';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casonas de piedra tradicionales lebaniegas con escudos heráldicos, hosterías de montaña con acabados en madera de roble y castaño, posadas rurales con chimenea y apartamentos rústicos. | Centro geográfico y nexo logístico del Valle de Liébana y del acceso oriental al Parque Nacional de los Picos de Europa. Destaca por el senderismo histórico del Camino Lebaniego hacia el Monasterio de Santo Toribio de Liébana, dehesas y senderos micológicos de montaña, y proximidad directa al Teleférico de Fuente Dé (ascenso vertical al circo glaciar y alta montaña).') WHERE codigo_ine = '39055';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Cabañas pasiegas auténticas rehabilitadas (antiguos establos unifamiliares de piedra caliza, vigas de roble y pradera vallada independiente), posadas rústicas de valle y hostales de montaña. | Comarca de los Valles Pasiegos. Ofrece un paisaje etnográfico único modelado por la ganadería tradicional en laderas verdes de gran pendiente. Rutas de senderismo de media montaña siguiendo el curso alto del río Pas, túneles ferroviarios abandonados de la Engaña integrados en la naturaleza, dehesas agrarias y senderos micológicos.') WHERE codigo_ine = '39097';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Cabañas rurales integradas en verdes laderas escarpadas, casonas señoriales del valle, apartamentos con estufa de leña y posadas de alta montaña aisladas de la civilización urbana. | Alberga el Parque Natural de los Collados de Asón. Rutas senderistas espectaculares hacia el Nacimiento del Río Asón (colosal cascada en forma de cola de caballo de más de 70 metros brotando del risco), senderismo de alta montaña caliza, exploración de grandes simas kársticas, lapiaces y prados alpinos altos de ganado extensivo. PROVINCIA: LUGO (Galicia - Datos Curados)') WHERE codigo_ine = '39083';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Pallozas tradicionales gallegas rehabilitadas (viviendas de piedra con techumbre circular de paja de centeno), casonas de montaña construidas en mampostería gruesa de pizarra y albergues históricos de paso jacobeo. | Entrada oficial del Camino de Santiago Francés en Galicia, a más de 1.300 metros de altitud en la frontera natural con León. Destaca por el senderismo de alta montaña que conecta con la Sierra de los Ancares, caminatas de interpretación de la arquitectura tradicional pirenaico-gallega, senderos bajo bosques de acebos y robles en la umbría, dehesas alpinas y rutas invernales con raquetas de nieve.') WHERE codigo_ine = '28009';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: El hotel rural pionero que inauguró el turismo verde en España, casas de aldea tradicionales con gruesos muros de piedra y tejados de pizarra negra, y antiguas rectorales rehabilitadas en mitad del pinar. | Cuna histórica del turismo rural español, integrado en la Reserva de la Biosfera del Río Eo, Oscos y Terras de Burón. Destaca por la emblemática Senda Verde y la Ruta del Agua (recorrido etnográfico que transita entre cascadas, molinos hidráulicos y el impresionante conjunto del mazo de Os Teixois). Ofrece senderos bajo bosques de robles y castaños, ríos salmoneros cristalinos y talleres artesanales vivos de cuchillería.') WHERE codigo_ine = '33071';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casonas e hidalguías tradicionales de piedra integradas en conjuntos etnográficos de pizarra, apartamentos rurales eco-bioclimáticos y casas de aldea unifamiliares con porches de madera. | En el corazón de la comarca de Los Oscos. Entorno de aislamiento geográfico y naturaleza atlántica virgen. Sede de la célebre ruta de senderismo de la Cascada de Seimeira (un espectacular salto de agua de más de 15 metros en caída libre escondido en un bosque cerrado). Ofrece caminatas que visitan el mazo de Mazonovo, dehesas e itinerarios micológicos otoñales, talleres de forja artesana tradicional de navajas y senderos pastoriles. 📂 PROVINCIA: LANZAROTE (Canarias - Datos Curados)') WHERE codigo_ine = '33062';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de labranza tradicionales de piedra con corrales recuperados, apartamentos rústicos pequeños con porche y posadas de dehesa e interior. | Célebre por el Valle Salado de Añana (un paisaje etnográfico único de salinas de evaporación prehistóricas estructuradas en eras de madera sobre canales de agua salada natural, catalogado como Patrimonio Mundial Agrícola por la FAO). Rutas de senderismo e interpretación de la sal, caminatas por los montes de encinas y quejigos linderos, dehesas tradicionales y cicloturismo de media montaña. 📂 PROVINCIA: SORIA - ZONA MONCAYO Y ÁGREDA (Castilla y León - Datos Curados)') WHERE codigo_ine = '50034';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casonas solariegas castellanas en el casco histórico de las tres culturas, hostales rurales especializados en montañeros y senderistas, y apartamentos rústicos con chimeneas de piedra. | \"La Villa de las Tres Culturas\", a las faldas de la vertiente soriana del Parque Natural del Moncayo. Destaca por la ruta de senderismo del Cañón del Río Val (un desfiladero calizo estrecho con túneles de sauces y cascadas naturales), caminatas botánicas que ascienden al pico de San Miguel (2.314 metros) entre dehesas altas y hayedos de umbría, rutas invernales de esquí de fondo y micología de boletus.') WHERE codigo_ine = '41011';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de pueblo tradicionales de mampostería oscura caliza junto al cauce fluvial, pequeños alojamientos con encanto a la sombra de su castillo fronterizo medieval. | Custodia el espectacular e imponente Nacimiento del Río Queiles (un Monumento Natural donde el agua brota a borbotones desde una colosal gruta kárstica caliza, siendo el segundo manantial de mayor caudal de Europa). Rutas de senderismo de cañón bajo encinares cantábricos, dehesas y senderos forestales de interpretación fluvial de ribera y observación de aves rapaces de roca. PROVINCIA: CÁDIZ (Andalucía - Datos Curados)') WHERE codigo_ine = '42217';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Cortijos andaluces tradicionales de cal blanca y teja curva, hoteles de montaña rústicos con chimenea de leña y apartamentos integrados en el casco histórico de su pueblo blanco serrano. | En el corazón del Parque Natural Sierra de Grazalema (Reserva de la Biosfera). El municipio ostenta el índice pluviométrico más alto de la península ibérica. Destaca por la emblemática y protegida ruta de senderismo del Pinsapar (colosal bosque relicto de abetos de la era glaciar), la Senda de la Garganta Verde (un desfiladero vertical calizo brutal), ascensiones al pico El Torreón (techo de la provincia con 1.648 metros) y avistamiento de buitre leonado.') WHERE codigo_ine = '11019';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de pueblo andaluzas independientes vinculadas al agroturismo olivarero, apartamentos rústicos con porches de piedra caliza y posadas rurales a los pies de su imponente silueta fortificada y su iglesia neoclásica alta. | Comarca de la Sierra de Cádiz alta. El principal punto de inicio y nexo de la Vía Verde de la Sierra (antiguo trazado de tren acondicionado ideal para familias y cicloturistas). Ofrece la espectacular ruta de senderismo hacia el paraje natural del Peñón de Zaframagón (un colosal farallón de roca caliza cortado que alberga una de las mayores colonias de buitres leonados de Europa), paseos agrícolas y rutas ecuestres de dehesa. 📂 PROVINCIA: VALENCIA (Comunidad Valenciana - Datos Curados)') WHERE codigo_ine = '11024';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de pueblo tradicionales de cal blanca adaptadas con patios rústicos, apartamentos turísticos optimizados para escaladores y senderistas mundiales, y hostales de montaña. | Ubicado de forma espectacular en el cañón calizo de la Hoz del Río Turia (Comarca de Los Serranos). Sede de la célebre y fotogénica ruta de senderismo de los Puentes Colgantes de Chulilla (itinerario que transita por el fondo del desfiladero cruzando colosales pasarelas suspendidas a gran altura sobre el río Turia). Es una de las grandes mecas nacionales de la escalada deportiva en roca caliza vertical, ofrece baños de agua dulce en el Charco Azul, senderos geológicos y rutas micológicos.') WHERE codigo_ine = '46112';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales integradas en su histórico barrio morisco y judío (Conjunto Histórico), antiguos molinos harineros de agua rehabilitados a orillas del agua y posadas rústicas de interior con chimeneas de leña. | Comarca de Los Serranos alta, flanqueada por la Sierra de Javalambre meridional. Sede de la espectacular ruta de senderismo de la Ruta del Agua de Chelva (un sendero plano e ideal para familias que combina túneles excavados en la roca viva, playas fluviales naturales de agua cristalina aptas para el baño veraniego como el Playón, y canales de riego árabes). Caminatas históricas hacia el Acueducto Romano de Peña Cortada, cicloturismo BTT y dehesas forestales bajo cielos oscuros Starlight. 📂 PROVINCIA: ÁVILA (Castilla y León - Datos Curados)') WHERE codigo_ine = '46106';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hostales de alta montaña especializados en montañeros, hoteles rurales premium construidos en piedra de granito y grandes ventanales de cristal, y cabañas alpinas independientes con chimenea de leña. | El principal centro logístico y de acceso al Parque Regional de la Sierra de Gredos. Custodia el punto de partida de la Plataforma de Gredos, de donde nace la mítica ruta senderista que asciende al Circo de Gredos y a la Laguna Grande bajo la silueta del Pico Almanzor (2.592 metros). Destaca por el avistamiento de la cabra montés de Gredos, rutas de raquetas de nieve, zonas de dehesa ganadera, baño en las pozas del río Tormes y certificación astronómica Starlight.') WHERE codigo_ine = '05105';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hoteles de campo y fincas rústicas rodeadas de campos de frutales e higueras, casas de piedra de la vertiente sur con amplios porches y apartamentos de dehesa a las faldas del castillo de Don Álvaro de Luna. | Capital de la vertiente sur de la Sierra de Gredos (el Valle del Tiétar). Custodia las impresionantes Cuevas del Águila (colosal formación geológica subterránea de estalactitas y estalagmitas gigantes iluminadas, transitable con visitas guiadas). Ofrece rutas de senderismo fluvial por las piscinas naturales del río Arenal, caminatas por densos castañares y dehesas mediterráneas, y ascensiones a los Galayos (meca de la escalada clásica en roca). 📂 PROVINCIA: SEGOVIA (Castilla y León - Datos Curados)') WHERE codigo_ine = '51001';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hoteles rurales premium con instalaciones de spa, antiguas casonas señoriales castellanas de sillería dorada, posadas de piedra con grandes chimeneas tradicionales de leña y apartamentos rústicos de cara al abismo. | El principal centro logístico y de acceso al Parque Natural de las Hoces del Río Duratón. Sede del inicio de la espectacular ruta de senderismo de la Senda de los Dos Ríos, caminatas hacia la Ermita de San Frutos colgada sobre el abismo del cañón, y es la meca nacional para el piragüismo y rutas en kayak fluvial por las aguas calmadas del meandro. Destaca por el turismo de avistamiento ornitológico (la mayor colonia europea de buitre leonado en roca) y dehesas micológicas.') WHERE codigo_ine = '40195';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Palacetes medievales y renacentistas de alquiler exclusivo dentro de una villa amurallada intacta (Conjunto Histórico), hospederías boutique reales con encanto rústico, patios empedrados de sillería y habitaciones con vigas de sabina centenarias. | Estribaciones septentrionales de la Sierra de Guadarrama. Ofrece rutas de senderismo histórico y natural que rodean sus kilométricas murallas calcáreas y su castillo del siglo XIII, caminatas de dehesa agraria entre robles y encinas centenarias donde pasta el ganado, dehesas ganaderas y cicloturismo de carretera de colinas suaves.') WHERE codigo_ine = '40156';